// ── eBay token cache (separate variable — doesn't touch _token above) ─────────
let _ebayToken = null, _ebayTokenExp = 0;

async function getEbayToken(env) {
  if (_ebayToken && Date.now() < _ebayTokenExp - 60000) return _ebayToken;
  const creds = btoa(`${env.EBAY_CLIENT_ID}:${env.EBAY_CLIENT_SECRET}`);
  const r = await fetch('https://api.ebay.com/identity/v1/oauth2/token', {
    method: 'POST',
    headers: { Authorization: `Basic ${creds}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `grant_type=refresh_token&refresh_token=${encodeURIComponent(env.EBAY_REFRESH_TOKEN)}&scope=https%3A%2F%2Fapi.ebay.com%2Foauth%2Fapi_scope%20https%3A%2F%2Fapi.ebay.com%2Foauth%2Fapi_scope%2Fsell.inventory%20https%3A%2F%2Fapi.ebay.com%2Foauth%2Fapi_scope%2Fsell.fulfillment%20https%3A%2F%2Fapi.ebay.com%2Foauth%2Fapi_scope%2Fsell.account%20https%3A%2F%2Fapi.ebay.com%2Foauth%2Fapi_scope%2Fcommerce.message`
  });
  const data = await r.json();
  if (!data.access_token) throw new Error('eBay token refresh failed: ' + JSON.stringify(data));
  _ebayToken    = data.access_token;
  _ebayTokenExp = Date.now() + (data.expires_in * 1000);
  return _ebayToken;
}

// Separate, ISOLATED token fetch for sell.finances specifically —
// deliberately NOT merged into the shared getEbayToken() above. That
// function is used by every already-working eBay feature in this
// worker (listings, offers, publishing). If the refresh token was
// never granted sell.finances during the original authorization,
// requesting it here could fail — isolating it means that failure only
// affects this one new capability, not everything else that already
// works.
let _ebayFinanceToken = null, _ebayFinanceTokenExp = 0;
async function getEbayFinanceToken(env) {
  if (_ebayFinanceToken && Date.now() < _ebayFinanceTokenExp - 60000) return _ebayFinanceToken;
  const creds = btoa(`${env.EBAY_CLIENT_ID}:${env.EBAY_CLIENT_SECRET}`);
  const r = await fetch('https://api.ebay.com/identity/v1/oauth2/token', {
    method: 'POST',
    headers: { Authorization: `Basic ${creds}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `grant_type=refresh_token&refresh_token=${encodeURIComponent(env.EBAY_REFRESH_TOKEN)}&scope=https%3A%2F%2Fapi.ebay.com%2Foauth%2Fapi_scope%20https%3A%2F%2Fapi.ebay.com%2Foauth%2Fapi_scope%2Fsell.finances`
  });
  const data = await r.json();
  if (!data.access_token) throw new Error('eBay finance token refresh failed (likely means sell.finances was never granted during original app authorization — re-authorizing the eBay connection may be required): ' + JSON.stringify(data));
  _ebayFinanceToken    = data.access_token;
  _ebayFinanceTokenExp = Date.now() + (data.expires_in * 1000);
  return _ebayFinanceToken;
}

// GET /ebay/finance-token-check — tests ONLY whether the sell.finances
// scope can actually be obtained, before building any refund logic on
// top of it. Confirms whether the app's existing eBay authorization
// already covers this scope, or whether re-authorization is genuinely
// needed first.
async function ebayFinanceTokenCheck(env) {
  try {
    const token = await getEbayFinanceToken(env);
    return cors(new Response(JSON.stringify({ ok: true, granted: true, tokenPreview: token.slice(0, 20) + '...' }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, granted: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// ── Repricer sheet helpers — uses same getToken() as everything else ──────────
// Uses SHEET_ID_REPRICER env var if set, otherwise falls back to SHEET_ID.
function repricerSheetId(env) {
  return env.SHEET_ID_REPRICER || env.SHEET_ID;
}

async function rSheetGet(env, range) {
  const token = await getToken(env);
  const [tab, cells] = range.split('!');
  const encodedRange = cells ? encodeURIComponent(tab) + '!' + cells : encodeURIComponent(tab);
  const url   = `${SHEETS_URL}/${repricerSheetId(env)}/values/${encodedRange}`;
  const r     = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  const data  = await r.json();
  if (data.error) throw new Error('Sheets read: ' + data.error.message);
  return data;
}

async function rSheetAppend(env, range, values) {
  const token = await getToken(env);
  const url   = `${SHEETS_URL}/${repricerSheetId(env)}/values/${encodeURIComponent(range)}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`;
  const r     = await fetch(url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values })
  });
  const data = await r.json();
  if (data.error) throw new Error('Sheets append: ' + data.error.message);
  return data;
}

async function rSheetUpdate(env, range, values) {
  const token = await getToken(env);
  const [tab, cells] = range.split('!');
  const encodedRange = cells ? encodeURIComponent(tab) + '!' + cells : encodeURIComponent(tab);
  const url   = `${SHEETS_URL}/${repricerSheetId(env)}/values/${encodedRange}?valueInputOption=USER_ENTERED`;
  const r     = await fetch(url, {
    method: 'PUT',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values })
  });
  const data = await r.json();
  if (data.error) throw new Error('Sheets update: ' + data.error.message);
  return data;
}

// ── Repricer route dispatcher ─────────────────────────────────────────────────
// GET /repricer/sku-lookup?q=<baseSku>
async function repricerSkuLookup(url, env) {
  try {
    const q = (url.searchParams.get('q') || '').trim().toUpperCase().replace(/^-+|-+$/g, '');
    if (!q || q.length < 2) return cors(new Response(JSON.stringify({ ok: false, error: 'Query too short' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getToken(env);
    const ranges = ['EbaySKU!A2:C5000','AmazonSKU!A2:C5000','WalmartSKU!A2:C5000','ShopifySKU!A2:C5000'];
    const batchUrl = SHEETS_URL + '/' + env.SHEET_ID + '/values:batchGet?' + ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&');
    const batchResp = await fetch(batchUrl, { headers: { Authorization: 'Bearer ' + token } });
    const batchData = await batchResp.json();
    const vrs = (batchData.valueRanges || []);
    const platformDefs = [
      { name: 'eBay',    rows: (vrs[0] && vrs[0].values) || [], idCol: 0, titleCol: 1, skuCol: 2 },
      { name: 'Amazon',  rows: (vrs[1] && vrs[1].values) || [], idCol: 0, titleCol: 1, skuCol: 2 },
      { name: 'Walmart', rows: (vrs[2] && vrs[2].values) || [], idCol: 0, titleCol: 1, skuCol: 2 },
      { name: 'Shopify', rows: (vrs[3] && vrs[3].values) || [], idCol: 1, titleCol: 1, skuCol: 2 },
    ];
    const results = [];
    const seen = new Set();
    for (const plat of platformDefs) {
      for (const row of plat.rows) {
        const rawSku  = String(row[plat.skuCol] || '').trim().toUpperCase().replace(/^-+|-+$/g, '');
        const base    = rawSku.split('=')[0].trim().replace(/^-+|-+$/g, '');
        if (!base.includes(q) && base !== q) continue;
        const listingId = String(row[plat.idCol] || '').trim();
        const title     = String(row[plat.titleCol] || '').trim();
        if (!listingId) continue;
        const dedupKey = plat.name + '|' + listingId;
        if (seen.has(dedupKey)) continue;
        seen.add(dedupKey);
        results.push({ platform: plat.name, listingId, title, sku: rawSku, baseSku: base });
      }
    }
    return cors(new Response(JSON.stringify({ ok: true, results, count: results.length }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /repricer/price-flags
async function repricerPriceFlagsGet(env) {
  try {
    const data = await invSheetGet(env, 'Price_Flags!A2:J5000').catch(() => ({ values: [] }));
    const rows = data.values || [];
    const flags = rows.map((r, i) => ({
      rowIndex: i + 2, timestamp: r[0] || '', baseSku: r[1] || '', platform: r[2] || '',
      listingId: r[3] || '', title: r[4] || '', oldCogs: r[5] || '', newCogs: r[6] || '',
      pctChange: r[7] || '', suggestedPrice: r[8] || '', status: r[9] || 'Open',
    })).filter(f => f.baseSku);
    return cors(new Response(JSON.stringify({ ok: true, flags }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// POST /repricer/price-flags/resolve
async function repricerPriceFlagsResolve(request, env) {
  try {
    const { rowIndex } = await request.json().catch(() => ({}));
    if (!rowIndex || rowIndex < 2) return cors(new Response(JSON.stringify({ ok: false, error: 'Invalid rowIndex' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    await invSheetUpdate(env, `Price_Flags!J${rowIndex}`, [['Resolved']]);
    return cors(new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

