// ═══════════════════════════════════════════════════════════════════════════
// AMAZON ACTIVE LISTINGS — 3-step request/status/download, same shape as the
// already-proven awdVelocityRequest/Status/Download pattern above. Report
// generation isn't instant, so this is deliberately split into 3 separate
// calls rather than one synchronous call that risks a Worker timeout while
// waiting for Amazon to finish building the report.
//
// IMPORTANT — unlike everything else built this session, this could NOT be
// tested against live data (no Amazon SP-API credentials available here).
// Built to match SP-API's documented report shape and this codebase's own
// proven pattern, but the report type, exact column headers, and price
// field location should be verified against a real report the first time
// this runs — logged clearly below if headers don't match what's expected,
// rather than failing silently.
//
// Report type: GET_MERCHANT_LISTINGS_ALL_DATA — Amazon's standard "all my
// active listings" flat-file report. Unlike GET_SALES_AND_TRAFFIC_REPORT
// (JSON), this comes back as tab-separated text, so the download/parse step
// is different from awdVelocityDownload even though the request/status
// steps are identical in shape.
// ═══════════════════════════════════════════════════════════════════════════

async function amazonListingsRequest(env) {
  try {
    const token = await getAmazonToken(env);
    const mid   = env.AMAZON_MARKETPLACE_ID || 'ATVPDKIKX0DER';
    const amzDate = new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';
    const res = await fetch('https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/reports', {
      method: 'POST',
      headers: { 'x-amz-access-token': token, 'x-amz-date': amzDate, 'Content-Type': 'application/json' },
      body: JSON.stringify({ reportType: 'GET_MERCHANT_LISTINGS_ALL_DATA', marketplaceIds: [mid] })
    });
    const data = await res.json();
    if (!res.ok) throw new Error('Report request failed: ' + JSON.stringify(data.errors || data));
    return cors(new Response(JSON.stringify({ ok: true, reportId: data.reportId, requestedAt: new Date().toISOString() }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) { return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } })); }
}

async function amazonListingsStatus(url, env) {
  try {
    const reportId = url.searchParams.get('reportId');
    if (!reportId) return cors(new Response(JSON.stringify({ ok: false, error: 'reportId required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getAmazonToken(env);
    const amzDate = new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';
    const res = await fetch(`https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/reports/${reportId}`, { headers: { 'x-amz-access-token': token, 'x-amz-date': amzDate } });
    const data = await res.json();
    if (!res.ok) throw new Error('Status failed: ' + JSON.stringify(data.errors || data));
    return cors(new Response(JSON.stringify({ ok: true, status: data.processingStatus, reportDocumentId: data.reportDocumentId || null, reportId }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) { return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } })); }
}

async function amazonListingsDownload(request, env) {
  try {
    const { reportDocumentId } = await request.json().catch(() => ({}));
    if (!reportDocumentId) return cors(new Response(JSON.stringify({ ok: false, error: 'reportDocumentId required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const amzToken = await getAmazonToken(env);
    const amzDate = new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';
    const docRes = await fetch(`https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/documents/${reportDocumentId}`, { headers: { 'x-amz-access-token': amzToken, 'x-amz-date': amzDate } });
    const docData = await docRes.json();
    if (!docRes.ok || !docData.url) throw new Error('Document fetch failed: ' + JSON.stringify(docData));

    const reportRes = await fetch(docData.url);
    const rawBytes = await reportRes.arrayBuffer();
    const magic = new Uint8Array(rawBytes.slice(0,2));
    let reportText;
    if (magic[0]===0x1f && magic[1]===0x8b) {
      // Same gzip-decompression approach already proven in awdVelocityDownload
      try {
        const ds = new DecompressionStream('gzip');
        const writer = ds.writable.getWriter();
        const reader = ds.readable.getReader();
        writer.write(new Uint8Array(rawBytes)); writer.close();
        const chunks = []; let done = false;
        while (!done) { const { value, done: d } = await reader.read(); if (value) chunks.push(value); done = d; }
        const total = chunks.reduce((a,c)=>a+c.length,0);
        const combined = new Uint8Array(total); let offset = 0;
        for (const chunk of chunks) { combined.set(chunk, offset); offset += chunk.length; }
        reportText = new TextDecoder().decode(combined);
      } catch(e) { reportText = new TextDecoder().decode(rawBytes); }
    } else {
      reportText = new TextDecoder().decode(rawBytes);
    }

    // Merchant listings reports are tab-separated, not JSON. Parse by
    // HEADER NAME rather than fixed column position — Amazon's exact
    // column set/order for this report type can vary by account/region,
    // same defensive approach already used elsewhere in this codebase
    // (see salesComputeTabs' findIdx helper).
    const lines = reportText.split(/\r?\n/).filter(l => l.trim());
    if (!lines.length) throw new Error('Report is empty');
    const headers = lines[0].split('\t').map(h => h.trim().toLowerCase());
    const idx = {
      sku:   headers.findIndex(h => h === 'seller-sku' || h === 'sku'),
      asin:  headers.findIndex(h => h === 'asin1' || h === 'asin'),
      price: headers.findIndex(h => h === 'price'),
      qty:   headers.findIndex(h => h === 'quantity'),
      title: headers.findIndex(h => h === 'item-name'),
      status:headers.findIndex(h => h === 'status'),
    };
    if (idx.sku === -1 || idx.price === -1) {
      // Surfacing this clearly rather than silently returning garbage —
      // if Amazon's actual column names differ from what's expected here,
      // this is exactly what needs to be checked/fixed first.
      console.error('[Amazon listings] Unexpected report headers:', headers.join(', '));
      throw new Error('Report headers did not match expected format (missing seller-sku or price column) — actual headers: ' + headers.join(', '));
    }

    const rawItems = [];
    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split('\t');
      const sku = (cols[idx.sku] || '').trim();
      const status = idx.status >= 0 ? (cols[idx.status] || '').trim().toLowerCase() : '';
      if (!sku) continue;
      if (status && status !== 'active') continue; // skip inactive/incomplete listings if the column exists
      rawItems.push({
        sku, asin: idx.asin >= 0 ? (cols[idx.asin] || '').trim() : '',
        price: parseFloat(cols[idx.price]) || 0,
        qty: idx.qty >= 0 ? (parseInt(cols[idx.qty]) || 0) : 0,
        title: idx.title >= 0 ? (cols[idx.title] || '').trim() : '',
      });
    }

    // Enrich with COGS + D1 price_tiers, same pattern as ebayListings —
    // direct SKU extraction (base_sku = everything before '='), no
    // dependency on the AmazonSKU sheet. Confirmed acceptable: FBA SKUs
    // reliably use the correct format; FBM siblings on the same ASIN that
    // don't just won't match COGS, same as any malformed SKU would today.
    if (!env.DB) throw new Error('D1 not available — cannot compute suggested pricing');
    await ensurePriceTiersTables(env);
    const tierRows = await d1All(env, "SELECT min_qty, max_qty, multiplier FROM price_tiers WHERE marketplace='amazon' ORDER BY sort_order");
    const configRows = await d1All(env, 'SELECT key, value FROM price_calc_config');
    const cfg = { ...PRICE_CALC_DEFAULTS };
    configRows.forEach(r => { cfg[r.key] = r.value; });

    const enriched = [];
    for (const item of rawItems) {
      const baseSku = item.sku.includes('=') ? item.sku.split('=')[0].trim() : item.sku.trim();
      const packQty = item.sku.includes('=') ? (parseInt(item.sku.split('=')[1]) || 1) : 1;
      const cogsRow = await d1First(env, 'SELECT unit_price FROM cogs WHERE UPPER(base_sku)=?', [baseSku.toUpperCase()]);
      const unitCogs = cogsRow ? parseFloat(cogsRow.unit_price) || 0 : 0;
      let floor = null, target = null, max = null, cog1pc = null;
      if (unitCogs > 0) {
        cog1pc = +(unitCogs * cfg.landed_multiplier).toFixed(4);
        const landedTotal = +(cog1pc * packQty).toFixed(4);
        const matched = tierRows.find(t => packQty >= t.min_qty && packQty <= t.max_qty) || tierRows[tierRows.length-1];
        const mult = matched ? matched.multiplier : 1;
        floor  = +(landedTotal * cfg.floor_multiplier + cfg.shipping).toFixed(2);
        target = Math.max(+(cog1pc * mult * packQty + cfg.shipping).toFixed(2), floor);
        max    = +(landedTotal * cfg.ceiling_multiplier + cfg.shipping).toFixed(2);
      }
      enriched.push({
        marketplace: 'amazon', sku: item.sku, baseSku, asin: item.asin,
        title: item.title, price: item.price, packQty, qty: item.qty,
        cog1pc, floor, target, max,
        status: !cog1pc ? 'no-cog' : item.price < floor ? 'below-floor' : item.price >= target ? 'ok' : 'needs-review',
      });
    }

    return cors(new Response(JSON.stringify({ ok: true, listings: enriched, total: enriched.length, syncedAt: new Date().toISOString() }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// POST /amazon/fba-inventory-request
// Confirmed from Amazon's own official SP-API docs:
// GET_FBA_MYI_UNSUPPRESSED_INVENTORY_DATA returns sku, fnsku, asin, and
// critically afn-listing-exists — a direct, explicit flag for whether a
// SKU is actually FBA-listed. This is the foundational data source for
// mapping every marketplace's SKUs to their real Amazon FBA equivalent.
// No date range needed (current-state report, not historical) and no
// chunking required. Reuses the existing, already-generic
// /amazon/listings-status endpoint for polling.
async function amazonFbaInventoryRequest(env) {
  try {
    const token = await getAmazonToken(env);
    const mid = env.AMAZON_MARKETPLACE_ID || 'ATVPDKIKX0DER';
    const amzDate = new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';
    const res = await fetch('https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/reports', {
      method: 'POST',
      headers: { 'x-amz-access-token': token, 'x-amz-date': amzDate, 'Content-Type': 'application/json' },
      body: JSON.stringify({ reportType: 'GET_FBA_MYI_UNSUPPRESSED_INVENTORY_DATA', marketplaceIds: [mid] })
    });
    const data = await res.json();
    if (!res.ok) throw new Error('Report request failed: ' + JSON.stringify(data.errors || data));
    return cors(new Response(JSON.stringify({ ok: true, reportId: data.reportId, requestedAt: new Date().toISOString() }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) { return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } })); }
}

// POST /amazon/fba-inventory-download — Body: {reportDocumentId}
// Downloads, parses (by header name, not fixed position - same
// defensive approach already proven for the merchant listings report,
// since Amazon's exact column set/order can vary), and stores into a
// new D1 table. This becomes the source of truth for "is this SKU
// actually FBA" going forward, replacing the incomplete platform_skus-
// based guess.
async function amazonFbaInventoryDownload(request, env) {
  try {
    const { reportDocumentId } = await request.json().catch(() => ({}));
    if (!reportDocumentId) return cors(new Response(JSON.stringify({ ok: false, error: 'reportDocumentId required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));

    const amzToken = await getAmazonToken(env);
    const amzDate = new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';
    const docRes = await fetch(`https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/documents/${reportDocumentId}`, { headers: { 'x-amz-access-token': amzToken, 'x-amz-date': amzDate } });
    const docData = await docRes.json();
    if (!docRes.ok || !docData.url) throw new Error('Document fetch failed: ' + JSON.stringify(docData));

    const reportRes = await fetch(docData.url);
    const rawBytes = await reportRes.arrayBuffer();
    const magic = new Uint8Array(rawBytes.slice(0,2));
    let reportText;
    if (magic[0]===0x1f && magic[1]===0x8b) {
      const ds = new DecompressionStream('gzip');
      const writer = ds.writable.getWriter();
      const reader = ds.readable.getReader();
      writer.write(new Uint8Array(rawBytes)); writer.close();
      const chunks = []; let done = false;
      while (!done) { const { value, done: d } = await reader.read(); if (value) chunks.push(value); done = d; }
      const total = chunks.reduce((a,c)=>a+c.length,0);
      const combined = new Uint8Array(total); let offset = 0;
      for (const chunk of chunks) { combined.set(chunk, offset); offset += chunk.length; }
      reportText = new TextDecoder().decode(combined);
    } else {
      reportText = new TextDecoder().decode(rawBytes);
    }

    const lines = reportText.split(/\r?\n/).filter(l => l.trim());
    if (!lines.length) throw new Error('Report is empty');
    const headers = lines[0].split('\t').map(h => h.trim().toLowerCase());
    const idx = {
      sku: headers.findIndex(h => h === 'sku'),
      fnsku: headers.findIndex(h => h === 'fnsku'),
      asin: headers.findIndex(h => h === 'asin'),
      productName: headers.findIndex(h => h === 'product-name'),
      afnListingExists: headers.findIndex(h => h === 'afn-listing-exists'),
      mfnListingExists: headers.findIndex(h => h === 'mfn-listing-exists'),
    };
    if (idx.sku === -1 || idx.fnsku === -1) {
      console.error('[FBA inventory] Unexpected report headers:', headers.join(', '));
      throw new Error('Report headers did not match expected format (missing sku or fnsku column) — actual headers: ' + headers.join(', '));
    }

    await env.DB.prepare(`
      CREATE TABLE IF NOT EXISTS amazon_fba_inventory (
        sku TEXT PRIMARY KEY, fnsku TEXT, asin TEXT, product_name TEXT,
        afn_listing_exists TEXT, mfn_listing_exists TEXT, updated_at TEXT
      )
    `).run().catch(()=>{});

    const ts = new Date().toISOString();
    const stmts = [];
    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split('\t');
      const sku = (cols[idx.sku] || '').trim();
      if (!sku) continue;
      stmts.push(env.DB.prepare(`INSERT OR REPLACE INTO amazon_fba_inventory (sku, fnsku, asin, product_name, afn_listing_exists, mfn_listing_exists, updated_at) VALUES (?,?,?,?,?,?,?)`)
        .bind(
          sku,
          (cols[idx.fnsku] || '').trim(),
          idx.asin >= 0 ? (cols[idx.asin] || '').trim() : '',
          idx.productName >= 0 ? (cols[idx.productName] || '').trim() : '',
          idx.afnListingExists >= 0 ? (cols[idx.afnListingExists] || '').trim() : '',
          idx.mfnListingExists >= 0 ? (cols[idx.mfnListingExists] || '').trim() : '',
          ts
        ));
    }
    // Batched in chunks of 100 - D1's batch() has its own practical
    // limits on statement count per call, same caution already applied
    // elsewhere in this codebase for large bulk writes.
    let written = 0;
    for (let i = 0; i < stmts.length; i += 100) {
      const chunk = stmts.slice(i, i + 100);
      await env.DB.batch(chunk);
      written += chunk.length;
    }

    return cors(new Response(JSON.stringify({ ok: true, written, updatedAt: ts }), { headers: { 'Content-Type': 'application/json' } }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /amazon/fba-sku-format-check — diagnostic: how many real FBA
// SKUs (afn_listing_exists = Yes) match the standard base_sku=packQty
// naming convention vs. auto-generated random codes (confirmed present
// via real sample data - e.g. "0M-WVXS-YP25"). Built specifically to
// quantify this before committing to a mapping strategy, rather than
// guess at the scale of the problem from 2 sample rows.
async function amazonFbaSkuFormatCheck(env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const all = await d1All(env, "SELECT sku, fnsku, asin, product_name FROM amazon_fba_inventory WHERE afn_listing_exists='Yes'");
    // Standard convention: starts with digits, contains '=' somewhere
    // after a hyphenated numeric prefix (e.g. "3-2-1=1", "202-6-9=10X").
    const standardPattern = /^\d+(-\d+)*\s*=/;
    const standard = [];
    const nonStandard = [];
    for (const row of all) {
      if (standardPattern.test((row.sku || '').trim())) standard.push(row);
      else nonStandard.push(row);
    }
    return cors(new Response(JSON.stringify({
      ok: true,
      totalFbaSkus: all.length,
      standardFormatCount: standard.length,
      nonStandardFormatCount: nonStandard.length,
      standardSample: standard.slice(0, 5).map(r => r.sku),
      nonStandardSample: nonStandard.slice(0, 10).map(r => ({ sku: r.sku, productName: r.product_name })),
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /amazon/fba-mapping-analysis — read-only preview of the actual
// SKU-to-FBA mapping situation across the whole catalog, before
// building any mapping table. Confirmed with the user: trailing X/XX
// on a SKU is a listing-recency marker, NOT a quantity signal -
// "=2", "=2X", "=2XX" are the exact same 2-pack product and must be
// treated as one for both pack-quantity extraction and sales grouping.
function normalizeSkuForMapping(sku) {
  // Strips trailing X's/dashes (case-insensitive) after the pack
  // quantity - "3-2-1=2XX" and "202-6-9=10X-" both normalize to their
  // real canonical form ("3-2-1=2", "202-6-9=10").
  return (sku || '').trim().replace(/[x\-]+$/i, '');
}

async function amazonFbaMappingAnalysis(env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    // Real, standard-format FBA SKUs only - confirmed with the user
    // that non-standard/legacy-format listings aren't actually shipped
    // into FBA and don't matter for this.
    const fbaRows = await d1All(env, "SELECT sku, fnsku, asin FROM amazon_fba_inventory WHERE afn_listing_exists='Yes'");
    const standardPattern = /^\d+(-\d+)*\s*=/;
    const fbaByNormalized = {}; // normalizedSku -> real fba sku (first one wins if duplicates exist)
    const fbaByBaseSku = {};    // base_sku -> array of {normalizedSku, realSku}
    for (const row of fbaRows) {
      const sku = (row.sku || '').trim();
      if (!standardPattern.test(sku)) continue; // skip non-standard/legacy, confirmed not needed
      const normalized = normalizeSkuForMapping(sku);
      const baseSku = normalized.split('=')[0].trim();
      if (!fbaByNormalized[normalized]) fbaByNormalized[normalized] = sku;
      if (!fbaByBaseSku[baseSku]) fbaByBaseSku[baseSku] = [];
      fbaByBaseSku[baseSku].push({ normalizedSku: normalized, realSku: sku });
    }

    // All known marketplace SKUs from the real, established tables.
    // FIXED real bug found via the data-quality check: master_list's
    // actual full SKU (with pack size) lives in part_num, not sku -
    // confirmed from real data showing sku as just the bare base_sku
    // for nearly every row, meaning the earlier version of this
    // analysis silently missed pack-size info for most of that table.
    // Also excludes confirmed junk (empty/near-empty base_sku) and
    // non-standard items like packing/shipping supplies - confirmed
    // real and intentionally tracked, but not relevant to FBA mapping
    // since they're not sellable product SKUs.
    const standardSkuPattern = /^\d+(-\d+)+(=|$)/;
    const allSkusRaw = await d1All(env, `
      SELECT part_num AS sku, base_sku FROM master_list WHERE part_num IS NOT NULL AND part_num != '' AND base_sku IS NOT NULL AND length(trim(base_sku)) > 1
      UNION
      SELECT sku, base_sku FROM products WHERE sku IS NOT NULL AND sku != '' AND base_sku IS NOT NULL AND length(trim(base_sku)) > 1
      UNION
      SELECT sku, base_sku FROM upc WHERE sku IS NOT NULL AND sku != '' AND base_sku IS NOT NULL AND length(trim(base_sku)) > 1
    `);
    // Confirmed with the user: "=OLD" suffixed SKUs are retired items
    // that will have no sales velocity - excluded entirely rather than
    // normalized/merged, since they're not real active products
    // needing a mapping decision at all.
    const allSkus = allSkusRaw.filter(r => {
      const sku = (r.sku || '').trim();
      return standardSkuPattern.test(sku) && !/=old\s*$/i.test(sku);
    });

    const directMatch = [];      // this exact pack size already has its own FBA listing
    const needsDecision = [];    // no direct match, but base_sku has at least one other FBA pack size
    const noFbaAtAll = [];       // base_sku has zero FBA listings of any pack size

    const seenNormalized = new Set();
    for (const row of allSkus) {
      const normalized = normalizeSkuForMapping(row.sku);
      if (seenNormalized.has(normalized)) continue; // dedupe repeat pack-size entries across platforms
      seenNormalized.add(normalized);
      const baseSku = (row.base_sku || normalized.split('=')[0]).trim();

      if (fbaByNormalized[normalized]) {
        directMatch.push({ sku: row.sku, normalizedSku: normalized, fbaSku: fbaByNormalized[normalized] });
      } else if (fbaByBaseSku[baseSku] && fbaByBaseSku[baseSku].length) {
        needsDecision.push({ sku: row.sku, normalizedSku: normalized, baseSku, options: fbaByBaseSku[baseSku].map(o => o.realSku) });
      } else {
        noFbaAtAll.push({ sku: row.sku, normalizedSku: normalized, baseSku });
      }
    }

    return cors(new Response(JSON.stringify({
      ok: true,
      directMatchCount: directMatch.length,
      needsDecisionCount: needsDecision.length,
      noFbaAtAllCount: noFbaAtAll.length,
      needsDecisionSample: needsDecision.slice(0, 15),
      needsDecisionSplitMethod: 'proportional — confirmed with the user: when sales velocity data is integrated, a pack size with no direct FBA match splits its demand proportionally across all existing FBA sibling pack sizes for the same base_sku, not assigned to just one.',
      noFbaAtAllSample: noFbaAtAll.slice(0, 15),
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /inventory/sku-data-quality — investigates suspicious patterns
// found in real mapping-analysis results before deciding how to
// handle them: junk base_sku values (like a bare "."), and rows where
// "sku" actually holds a raw UPC number instead of a real SKU. Shows
// full row context, including which source table each came from, so
// nothing gets silently filtered without understanding it first.
async function skuDataQualityCheck(env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const tables = ['master_list', 'products', 'upc'];
    const findings = {};

    for (const table of tables) {
      // Junk base_sku: empty, pure punctuation, or suspiciously short
      const junkBaseSku = await d1All(env, `SELECT * FROM ${table} WHERE base_sku IS NULL OR base_sku = '' OR base_sku = '.' OR length(trim(base_sku)) <= 1 LIMIT 10`);
      // sku that's actually a raw UPC: all-digit, 11+ characters, no
      // "=" (real SKUs always have a pack-size suffix in this catalog)
      const rawUpcAsSku = await d1All(env, `SELECT * FROM ${table} WHERE sku GLOB '[0-9]*' AND length(sku) >= 11 AND sku NOT LIKE '%=%' LIMIT 10`);
      // Bare base_sku with no pack-size suffix at all (no "=" anywhere)
      // - these showed up in the mapping analysis sample and may be
      // legacy/placeholder rows rather than real sellable variants.
      const bareSkuNoSuffix = await d1All(env, `SELECT * FROM ${table} WHERE sku IS NOT NULL AND sku != '' AND sku NOT LIKE '%=%' AND NOT (sku GLOB '[0-9]*' AND length(sku) >= 11) LIMIT 10`);

      const junkBaseSkuCount = (await d1All(env, `SELECT COUNT(*) as c FROM ${table} WHERE base_sku IS NULL OR base_sku = '' OR base_sku = '.' OR length(trim(base_sku)) <= 1`))[0].c;
      const rawUpcAsSkuCount = (await d1All(env, `SELECT COUNT(*) as c FROM ${table} WHERE sku GLOB '[0-9]*' AND length(sku) >= 11 AND sku NOT LIKE '%=%'`))[0].c;
      const bareSkuNoSuffixCount = (await d1All(env, `SELECT COUNT(*) as c FROM ${table} WHERE sku IS NOT NULL AND sku != '' AND sku NOT LIKE '%=%' AND NOT (sku GLOB '[0-9]*' AND length(sku) >= 11)`))[0].c;

      findings[table] = {
        totalRows: (await d1All(env, `SELECT COUNT(*) as c FROM ${table}`))[0].c,
        junkBaseSku: { count: junkBaseSkuCount, samples: junkBaseSku },
        rawUpcAsSku: { count: rawUpcAsSkuCount, samples: rawUpcAsSku },
        bareSkuNoSuffix: { count: bareSkuNoSuffixCount, samples: bareSkuNoSuffix },
      };
    }

    return cors(new Response(JSON.stringify({ ok: true, findings }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /inventory/upc-coverage-check — answers directly, with real
// data: does the upc table alone have every real base_sku, or are
// there base_skus in master_list/products that don't exist in upc at
// all? Built to check this rather than assume either way.
async function upcCoverageCheck(env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const upcBaseSkus = new Set((await d1All(env, "SELECT DISTINCT base_sku FROM upc WHERE base_sku IS NOT NULL AND length(trim(base_sku)) > 1")).map(r => r.base_sku.trim()));
    const masterListBaseSkus = await d1All(env, "SELECT DISTINCT base_sku FROM master_list WHERE base_sku IS NOT NULL AND length(trim(base_sku)) > 1");
    const productsBaseSkus = await d1All(env, "SELECT DISTINCT base_sku FROM products WHERE base_sku IS NOT NULL AND length(trim(base_sku)) > 1");

    const missingFromMasterList = masterListBaseSkus.filter(r => !upcBaseSkus.has(r.base_sku.trim()));
    const missingFromProducts = productsBaseSkus.filter(r => !upcBaseSkus.has(r.base_sku.trim()));

    return cors(new Response(JSON.stringify({
      ok: true,
      upcTotalDistinctBaseSkus: upcBaseSkus.size,
      masterListTotalDistinctBaseSkus: masterListBaseSkus.length,
      productsTotalDistinctBaseSkus: productsBaseSkus.length,
      masterListBaseSkusMissingFromUpc: { count: missingFromMasterList.length, sample: missingFromMasterList.slice(0, 20).map(r => r.base_sku) },
      productsBaseSkusMissingFromUpc: { count: missingFromProducts.length, sample: missingFromProducts.slice(0, 20).map(r => r.base_sku) },
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

async function amazonSalesTrafficRequest(request, env) {
  try {
    const body = await request.json().catch(() => ({}));
    const days = body.days === 90 ? 90 : 30;
    const token = await getAmazonToken(env);
    const mid = env.AMAZON_MARKETPLACE_ID || 'ATVPDKIKX0DER';
    const amzDate = () => new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';

    // Build <=14-day chunks covering the requested window, most recent
    // first. Amazon's own lookback limit is 30 days for this report, so
    // a 90-day request genuinely needs data older than that window is
    // designed for -- flagged in the response rather than silently
    // returning incomplete data.
    const now = new Date();
    const chunks = [];
    let cursor = new Date(now);
    let remaining = days;
    while (remaining > 0) {
      const span = Math.min(14, remaining);
      const end = new Date(cursor);
      const start = new Date(cursor);
      start.setDate(start.getDate() - span);
      chunks.push({ dataStartTime: start.toISOString(), dataEndTime: end.toISOString() });
      cursor = start;
      remaining -= span;
    }

    const requests = [];
    for (const chunk of chunks) {
      const res = await fetch('https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/reports', {
        method: 'POST',
        headers: { 'x-amz-access-token': token, 'x-amz-date': amzDate(), 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reportType: 'GET_SALES_AND_TRAFFIC_REPORT',
          reportOptions: { reportPeriod: 'DAY', asinGranularity: 'SKU' },
          dataStartTime: chunk.dataStartTime,
          dataEndTime: chunk.dataEndTime,
          marketplaceIds: [mid],
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        requests.push({ ok: false, error: JSON.stringify(data.errors || data), dataStartTime: chunk.dataStartTime, dataEndTime: chunk.dataEndTime });
        continue;
      }
      requests.push({ ok: true, reportId: data.reportId, dataStartTime: chunk.dataStartTime, dataEndTime: chunk.dataEndTime });
    }

    const anyFailed = requests.some(r => !r.ok);
    const beyondLookback = days > 30;
    return cors(new Response(JSON.stringify({
      ok: !anyFailed, days, chunkCount: chunks.length, requests,
      warning: beyondLookback ? 'Requested window exceeds this report\'s documented 30-day lookback -- older chunks may return incomplete or no data.' : null,
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// ── AUTOMATED WEEKLY AMAZON SALES PULL ──
// Confirmed with the user: weekly, non-overlapping 7-day windows
// (not monthly) — a monthly cadence risks a permanent data gap if a
// fetch is ever missed by more than a few days, since Amazon's report
// only looks back 30 days from whenever it's actually requested.
// Weekly windows mean Amazon's own 30-day lookback provides real
// safety margin even if a week or two gets missed. Confirmed: fully
// automatic, no manual button click required. Confirmed: re-fetching
// the same period overwrites rather than duplicates, keyed on
// sku + period_start.
//
// Runs in two separate cron-driven steps rather than one, because a
// real report can take 15-20+ minutes to finish processing (confirmed
// from testing the FBA inventory report) — far longer than a single
// scheduled invocation should block for:
//   1. cronAmazonWeeklySalesKickoff — runs once a week, requests a
//      fresh 7-day report, stores the pending reportId.
//   2. cronAmazonWeeklySalesCheck — runs frequently, checks for any
//      pending report, downloads and stores it once Amazon marks it
//      DONE.
async function ensureAmazonSalesTables(env) {
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS amazon_sales_weekly (
      sku TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT,
      units_ordered REAL, ordered_product_sales REAL, asin TEXT,
      fetched_at TEXT, PRIMARY KEY (sku, period_start)
    )
  `).run().catch(()=>{});
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS amazon_sales_pending (
      report_id TEXT PRIMARY KEY, period_start TEXT, period_end TEXT,
      requested_at TEXT, status TEXT
    )
  `).run().catch(()=>{});
}

async function cronAmazonWeeklySalesKickoff(env) {
  try {
    await ensureAmazonSalesTables(env);

    // Don't kick off a new request if one is already pending — avoids
    // piling up duplicate in-flight reports if the check step is
    // somehow lagging.
    const existing = await d1All(env, "SELECT COUNT(*) as c FROM amazon_sales_pending WHERE status != 'done' AND status != 'failed'");
    if (existing[0].c > 0) { console.log('[cronAmazonWeeklySales] Skipping kickoff — a report is already pending'); return; }

    const token = await getAmazonToken(env);
    const mid = env.AMAZON_MARKETPLACE_ID || 'ATVPDKIKX0DER';
    const amzDate = new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';
    const now = new Date();
    const start = new Date(now); start.setDate(start.getDate() - 7);
    const dataStartTime = start.toISOString();
    const dataEndTime = now.toISOString();

    const res = await fetch('https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/reports', {
      method: 'POST',
      headers: { 'x-amz-access-token': token, 'x-amz-date': amzDate, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        reportType: 'GET_SALES_AND_TRAFFIC_REPORT',
        reportOptions: { reportPeriod: 'DAY', asinGranularity: 'SKU' },
        dataStartTime, dataEndTime, marketplaceIds: [mid],
      }),
    });
    const data = await res.json();
    if (!res.ok || !data.reportId) { console.error('[cronAmazonWeeklySales] Kickoff failed:', JSON.stringify(data)); return; }

    await env.DB.prepare(`INSERT INTO amazon_sales_pending (report_id, period_start, period_end, requested_at, status) VALUES (?,?,?,?,?)`)
      .bind(data.reportId, dataStartTime, dataEndTime, now.toISOString(), 'pending').run();
    console.log('[cronAmazonWeeklySales] Kicked off report', data.reportId, 'for', dataStartTime, 'to', dataEndTime);
  } catch (e) {
    console.error('[cronAmazonWeeklySales] Kickoff error:', e.message);
  }
}

async function cronAmazonWeeklySalesCheck(env) {
  try {
    await ensureAmazonSalesTables(env);
    const pending = await d1All(env, "SELECT * FROM amazon_sales_pending WHERE status = 'pending' LIMIT 1");
    if (!pending.length) return;
    const row = pending[0];

    const token = await getAmazonToken(env);
    const amzDate = new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';
    const statusRes = await fetch(`https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/reports/${row.report_id}`, { headers: { 'x-amz-access-token': token, 'x-amz-date': amzDate } });
    const statusData = await statusRes.json();

    if (statusData.processingStatus === 'FATAL' || statusData.processingStatus === 'CANCELLED') {
      await env.DB.prepare("UPDATE amazon_sales_pending SET status='failed' WHERE report_id=?").bind(row.report_id).run();
      console.error('[cronAmazonWeeklySales] Report failed:', row.report_id, statusData.processingStatus);
      return;
    }
    if (statusData.processingStatus !== 'DONE') return; // still processing, check again next cron tick

    // Download and parse - same logic as the manual download endpoint
    const docRes = await fetch(`https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/documents/${statusData.reportDocumentId}`, { headers: { 'x-amz-access-token': token, 'x-amz-date': amzDate } });
    const docData = await docRes.json();
    if (!docRes.ok || !docData.url) { console.error('[cronAmazonWeeklySales] Document fetch failed:', JSON.stringify(docData)); return; }

    const reportRes = await fetch(docData.url);
    const rawBytes = await reportRes.arrayBuffer();
    const magic = new Uint8Array(rawBytes.slice(0,2));
    let reportText;
    if (magic[0]===0x1f && magic[1]===0x8b) {
      const ds = new DecompressionStream('gzip');
      const writer = ds.writable.getWriter();
      const reader = ds.readable.getReader();
      writer.write(new Uint8Array(rawBytes)); writer.close();
      const chunks = []; let done = false;
      while (!done) { const { value, done: d } = await reader.read(); if (value) chunks.push(value); done = d; }
      const total = chunks.reduce((a,c)=>a+c.length,0);
      const combined = new Uint8Array(total); let offset = 0;
      for (const chunk of chunks) { combined.set(chunk, offset); offset += chunk.length; }
      reportText = new TextDecoder().decode(combined);
    } else {
      reportText = new TextDecoder().decode(rawBytes);
    }

    const parsed = JSON.parse(reportText);
    const salesRows = parsed.salesAndTrafficByAsin || [];

    // Amazon's report sometimes omits the sku field for a row (seen in
    // testing), and the old fallback stored that row under the ASIN
    // itself as if it were a SKU. Every other part of this system - the
    // dashboard, reorder's own matching - looks up sales by real SKU
    // against the UPC table, so any row stored under a bare ASIN was
    // silently invisible everywhere downstream, undercounting real sales
    // that did happen. fba_catalog already has a real sku<->asin mapping
    // (built for the reorder engine), so resolve through that instead of
    // guessing or silently dropping the row.
    const asinsNeedingLookup = [...new Set(salesRows.filter(r => !r.sku).map(r => r.childAsin || r.parentAsin).filter(Boolean))];
    const asinToSku = {};
    if (asinsNeedingLookup.length) {
      const placeholders = asinsNeedingLookup.map(() => '?').join(',');
      const rows = (await env.DB.prepare(`SELECT sku, asin FROM fba_catalog WHERE asin IN (${placeholders})`).bind(...asinsNeedingLookup).all()).results || [];
      rows.forEach(r => { if (r.asin && r.sku) asinToSku[r.asin] = r.sku; });
    }

    const bySku = {};
    let unresolvedAsinRows = 0;
    for (const r of salesRows) {
      const asin = r.childAsin || r.parentAsin || null;
      const sku = r.sku || (asin && asinToSku[asin]) || null;
      if (!sku) { unresolvedAsinRows++; continue; } // can't resolve to a real SKU - skip rather than store junk under the ASIN
      if (!bySku[sku]) bySku[sku] = { sku, asin, unitsOrdered: 0, orderedProductSales: 0 };
      const sales = r.salesByAsin || r.sales || r;
      bySku[sku].unitsOrdered += Number(sales.unitsOrdered || 0);
      const opsVal = sales.orderedProductSales;
      bySku[sku].orderedProductSales += Number((opsVal && typeof opsVal === 'object' ? opsVal.amount : opsVal) || 0);
    }
    if (unresolvedAsinRows > 0) {
      console.error('[cronAmazonWeeklySales]', unresolvedAsinRows, 'rows had no sku and no fba_catalog match for their ASIN - skipped, not counted');
    }

    const fetchedAt = new Date().toISOString();
    const periodStart = row.period_start.slice(0, 10); // date-only key, matches confirmed sku+period_start uniqueness
    const stmts = Object.values(bySku).map(r => env.DB.prepare(
      `INSERT OR REPLACE INTO amazon_sales_weekly (sku, period_start, period_end, units_ordered, ordered_product_sales, asin, fetched_at) VALUES (?,?,?,?,?,?,?)`
    ).bind(r.sku, periodStart, row.period_end, r.unitsOrdered, r.orderedProductSales, r.asin, fetchedAt));
    for (let i = 0; i < stmts.length; i += 100) { await env.DB.batch(stmts.slice(i, i + 100)); }

    await env.DB.prepare("UPDATE amazon_sales_pending SET status='done' WHERE report_id=?").bind(row.report_id).run();
    console.log('[cronAmazonWeeklySales] Stored', stmts.length, 'SKUs for period', periodStart);
  } catch (e) {
    console.error('[cronAmazonWeeklySales] Check/store error:', e.message);
  }
}

// ── AUTOMATED WEEKLY EBAY SALES PULL ──
// Simpler than the Amazon version - eBay's Fulfillment API returns
// order data directly (no async report generation, no polling needed),
// so this is a single function rather than a kickoff+check pair.
// Reuses the exact same proven order-fetch pattern already working in
// ebaySalesWindowToSalesSheet (pagination, cancelled-order filtering,
// per-line-item extraction) but aggregates by SKU and stores into D1
// instead of writing raw rows to Google Sheets. Same schema shape and
// same overwrite-on-sku+period_start behavior as amazon_sales_weekly,
// confirmed with the user as the correct pattern.
async function ensureEbaySalesTable(env) {
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS ebay_sales_weekly (
      sku TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT,
      units_ordered REAL, sales_amount REAL, fetched_at TEXT,
      PRIMARY KEY (sku, period_start)
    )
  `).run().catch(()=>{});
}

async function cronEbayWeeklySales(env) {
  try {
    await ensureEbaySalesTable(env);

    const now = new Date();
    const start = new Date(now); start.setDate(start.getDate() - 7);
    const from = start.toISOString();
    const to = now.toISOString();
    const filterVal = `creationdate:[${from}..${to}]`;

    const ebayToken = await getEbayToken(env);
    let orders = [], offset = 0, page = 0;
    const PAGE_CAP = 15; // matches the existing 30d page cap - one week should need far fewer, this is headroom
    let lastError = null;

    while (page < PAGE_CAP) {
      const r = await fetch(
        `https://api.ebay.com/sell/fulfillment/v1/order?filter=${encodeURIComponent(filterVal)}&limit=200&offset=${offset}`,
        { headers: { Authorization: `Bearer ${ebayToken}` } }
      );
      if (!r.ok) { lastError = `eBay API ${r.status} on page ${page + 1}`; break; }
      const data = await r.json().catch(() => ({}));
      if (data.errors?.length) { lastError = data.errors[0]?.message || 'eBay error'; break; }
      const batch = data.orders || [];
      orders = orders.concat(batch);
      page++;
      if (batch.length < 200) break;
      offset += 200;
    }

    if (lastError && !orders.length) {
      console.error('[cronEbayWeeklySales] Fetch failed:', lastError);
      return;
    }

    const CANCELLED = new Set(['CANCEL_COMPLETE']);
    const bySku = {};
    for (const order of orders) {
      const cancelState = (order.cancelStatus?.cancelState || '').toUpperCase();
      if (CANCELLED.has(cancelState)) continue;
      for (const line of (order.lineItems || [])) {
        const sku = (line.sku || '').trim();
        if (!sku) continue;
        const qty = parseInt(line.quantity) || 1;
        const unitPrice = parseFloat(line.lineItemCost?.value || 0);
        const price = unitPrice * qty;

        // eBay's order-level cancelStatus (checked above) is a genuinely
        // separate mechanism from line-item-level refunds — a seller can
        // refund one line item in a multi-item order via issueRefund
        // without the order's overall cancelState ever becoming
        // CANCEL_COMPLETE. Without this, a partially-refunded line item
        // was counted in full, inflating both units and revenue.
        // line.refunds[].amount is the seller's net amount already
        // refunded for that line - there's no separate "quantity
        // refunded" field in eBay's schema, so a fully-refunded line
        // (refunded amount >= the line's total price, allowing for
        // floating-point slack) is excluded entirely; a partial refund
        // reduces both price and quantity proportionally to how much of
        // the line's value was refunded.
        const refunds = line.refunds || [];
        const refundedAmount = refunds.reduce((sum, r) => sum + (parseFloat(r.amount?.value || 0)), 0);
        if (refundedAmount <= 0) {
          if (!bySku[sku]) bySku[sku] = { sku, unitsOrdered: 0, salesAmount: 0 };
          bySku[sku].unitsOrdered += qty;
          bySku[sku].salesAmount += price;
          continue;
        }
        if (price > 0 && refundedAmount >= price - 0.01) continue; // fully refunded - skip line entirely
        const refundRatio = price > 0 ? Math.min(refundedAmount / price, 1) : 0;
        const netQty = qty * (1 - refundRatio);
        const netPrice = price - refundedAmount;
        if (!bySku[sku]) bySku[sku] = { sku, unitsOrdered: 0, salesAmount: 0 };
        bySku[sku].unitsOrdered += netQty;
        bySku[sku].salesAmount += netPrice;
      }
    }

    const fetchedAt = new Date().toISOString();
    const periodStart = from.slice(0, 10); // date-only key, matches confirmed sku+period_start uniqueness
    const stmts = Object.values(bySku).map(r => env.DB.prepare(
      `INSERT OR REPLACE INTO ebay_sales_weekly (sku, period_start, period_end, units_ordered, sales_amount, fetched_at) VALUES (?,?,?,?,?,?)`
    ).bind(r.sku, periodStart, to, r.unitsOrdered, Math.round(r.salesAmount * 100) / 100, fetchedAt));
    for (let i = 0; i < stmts.length; i += 100) { await env.DB.batch(stmts.slice(i, i + 100)); }

    console.log('[cronEbayWeeklySales] Stored', stmts.length, 'SKUs for period', periodStart, '(from', orders.length, 'orders)');
  } catch (e) {
    console.error('[cronEbayWeeklySales] Error:', e.message);
  }
}

// ── AUTOMATED WEEKLY WALMART SALES PULL ──
// Reuses the proven getWalmartToken() and WM_SEC.ACCESS_TOKEN header
// pattern already confirmed working (walmartOrderLookup). Confirmed
// from Walmart's own docs and multiple independent real examples:
// createdStartDate/createdEndDate for date filtering, CURSOR-based
// pagination (different from eBay's offset-based paging) via
// nextCursor, and orders structured as
// order.orderLines.orderLine[].item.sku /
// .orderLineQuantity.amount / .charges.charge[] filtered by
// chargeType='PRODUCT'. HONESTY NOTE: schema confirmed from Walmart's
// docs and third-party examples, not yet verified against a real
// response from this specific account - debug capture included so a
// mismatch is diagnosable rather than silently returning zero.
async function ensureWalmartSalesTable(env) {
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS walmart_sales_weekly (
      sku TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT,
      units_ordered REAL, sales_amount REAL, fetched_at TEXT,
      PRIMARY KEY (sku, period_start)
    )
  `).run().catch(()=>{});
}

async function cronWalmartWeeklySales(env) {
  try {
    await ensureWalmartSalesTable(env);

    const now = new Date();
    const start = new Date(now); start.setDate(start.getDate() - 7);
    const createdStartDate = start.toISOString().slice(0, 10);
    const createdEndDate = now.toISOString();

    const token = await getWalmartToken(env);
    let orders = [];
    let queryString = `?limit=200&createdStartDate=${encodeURIComponent(createdStartDate)}&createdEndDate=${encodeURIComponent(createdEndDate)}`;
    let page = 0;
    const PAGE_CAP = 20; // headroom - one week of orders shouldn't need many pages
    let lastError = null;
    let firstResponseSample = null;

    while (page < PAGE_CAP) {
      const res = await fetch(`https://marketplace.walmartapis.com/v3/orders${queryString}`, {
        headers: {
          'WM_SEC.ACCESS_TOKEN': token,
          'WM_QOS.CORRELATION_ID': crypto.randomUUID(),
          'WM_SVC.NAME': 'Walmart Marketplace',
          'Accept': 'application/json',
        },
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) { lastError = `Walmart API ${res.status}: ${JSON.stringify(data)}`; break; }
      if (page === 0) firstResponseSample = JSON.stringify(data).slice(0, 1500);

      const batch = (data.list && data.list.elements && data.list.elements.order) || [];
      orders = orders.concat(Array.isArray(batch) ? batch : [batch]);
      page++;

      const meta = data.list && data.list.meta;
      const nextCursor = meta && meta.nextCursor;
      if (!nextCursor || !nextCursor.includes('hasMoreElements=true')) break;
      queryString = nextCursor; // Walmart's cursor is a full query string, used directly
    }

    if (lastError && !orders.length) {
      console.error('[cronWalmartWeeklySales] Fetch failed:', lastError);
      return;
    }
    if (!orders.length) {
      console.log('[cronWalmartWeeklySales] No orders returned. Response sample:', firstResponseSample);
      return;
    }

    const bySku = {};
    let parseIssues = 0;
    for (const order of orders) {
      const lines = (order.orderLines && order.orderLines.orderLine) || [];
      const lineArr = Array.isArray(lines) ? lines : [lines];
      for (const line of lineArr) {
        const sku = line.item && line.item.sku;
        if (!sku) { parseIssues++; continue; }
        const qty = parseFloat((line.orderLineQuantity && line.orderLineQuantity.amount) || 1) || 1;
        const charges = (line.charges && line.charges.charge) || [];
        const chargeArr = Array.isArray(charges) ? charges : [charges];
        const priceCharge = chargeArr.find(c => c.chargeType === 'PRODUCT' && c.chargeName === 'ItemPrice');
        const price = (priceCharge && priceCharge.chargeAmount && priceCharge.chargeAmount.amount) || 0;
        if (!bySku[sku]) bySku[sku] = { sku, unitsOrdered: 0, salesAmount: 0 };
        bySku[sku].unitsOrdered += qty;
        bySku[sku].salesAmount += Number(price);
      }
    }

    if (!Object.keys(bySku).length) {
      console.error('[cronWalmartWeeklySales] Parsed 0 SKUs from', orders.length, 'orders — schema likely mismatched. Sample:', firstResponseSample);
      return;
    }

    const fetchedAt = new Date().toISOString();
    const stmts = Object.values(bySku).map(r => env.DB.prepare(
      `INSERT OR REPLACE INTO walmart_sales_weekly (sku, period_start, period_end, units_ordered, sales_amount, fetched_at) VALUES (?,?,?,?,?,?)`
    ).bind(r.sku, createdStartDate, createdEndDate, r.unitsOrdered, Math.round(r.salesAmount * 100) / 100, fetchedAt));
    for (let i = 0; i < stmts.length; i += 100) { await env.DB.batch(stmts.slice(i, i + 100)); }

    console.log('[cronWalmartWeeklySales] Stored', stmts.length, 'SKUs for period', createdStartDate, '(from', orders.length, 'orders,', parseIssues, 'lines skipped for missing sku)');
  } catch (e) {
    console.error('[cronWalmartWeeklySales] Error:', e.message);
  }
}

// ── AUTOMATED WEEKLY SHOPIFY SALES PULL ──
// Reuses the proven shopifyGraphQL(env, query, variables) helper
// already working for listing creation. Confirmed from Shopify's own
// official docs: standard GraphQL cursor pagination (pageInfo /
// hasNextPage / endCursor), date-range filtering via the query string
// argument, and line items expose sku/quantity directly (no nested
// item.sku wrapper like Walmart). Simpler structure to parse than
// either Amazon or Walmart as a result.
async function ensureShopifySalesTable(env) {
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS shopify_sales_weekly (
      sku TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT,
      units_ordered REAL, sales_amount REAL, fetched_at TEXT,
      PRIMARY KEY (sku, period_start)
    )
  `).run().catch(()=>{});
}

async function cronShopifyWeeklySales(env) {
  try {
    await ensureShopifySalesTable(env);

    const now = new Date();
    const start = new Date(now); start.setDate(start.getDate() - 7);
    const periodStart = start.toISOString().slice(0, 10);
    const periodEnd = now.toISOString();
    const dateFilter = `created_at:>='${start.toISOString()}' AND created_at:<='${now.toISOString()}'`;

    const query = `
      query GetOrders($cursor: String, $filter: String!) {
        orders(first: 100, after: $cursor, query: $filter) {
          edges {
            cursor
            node {
              id
              cancelledAt
              lineItems(first: 50) {
                edges {
                  node {
                    sku
                    quantity
                    originalUnitPriceSet { shopMoney { amount } }
                  }
                }
              }
            }
          }
          pageInfo { hasNextPage }
        }
      }
    `;

    const bySku = {};
    let cursor = null;
    let hasNextPage = true;
    let page = 0;
    const PAGE_CAP = 20; // headroom for one week of orders
    let orderCount = 0;

    while (hasNextPage && page < PAGE_CAP) {
      const data = await shopifyGraphQL(env, query, { cursor, filter: dateFilter });
      const edges = (data.orders && data.orders.edges) || [];
      for (const edge of edges) {
        const order = edge.node;
        if (order.cancelledAt) continue; // exclude cancelled orders, same as eBay's cancel filter
        orderCount++;
        const lineEdges = (order.lineItems && order.lineItems.edges) || [];
        for (const le of lineEdges) {
          const line = le.node;
          const sku = (line.sku || '').trim();
          if (!sku) continue;
          const qty = Number(line.quantity) || 0;
          const unitPrice = Number(
            (line.originalUnitPriceSet && line.originalUnitPriceSet.shopMoney && line.originalUnitPriceSet.shopMoney.amount) || 0
          );
          if (!bySku[sku]) bySku[sku] = { sku, unitsOrdered: 0, salesAmount: 0 };
          bySku[sku].unitsOrdered += qty;
          bySku[sku].salesAmount += qty * unitPrice;
        }
        cursor = edge.cursor;
      }
      hasNextPage = data.orders && data.orders.pageInfo && data.orders.pageInfo.hasNextPage;
      page++;
    }

    if (!Object.keys(bySku).length) {
      console.log('[cronShopifyWeeklySales] No SKUs found from', orderCount, 'orders this period.');
      return;
    }

    const fetchedAt = new Date().toISOString();
    const stmts = Object.values(bySku).map(r => env.DB.prepare(
      `INSERT OR REPLACE INTO shopify_sales_weekly (sku, period_start, period_end, units_ordered, sales_amount, fetched_at) VALUES (?,?,?,?,?,?)`
    ).bind(r.sku, periodStart, periodEnd, r.unitsOrdered, Math.round(r.salesAmount * 100) / 100, fetchedAt));
    for (let i = 0; i < stmts.length; i += 100) { await env.DB.batch(stmts.slice(i, i + 100)); }

    console.log('[cronShopifyWeeklySales] Stored', stmts.length, 'SKUs for period', periodStart, '(from', orderCount, 'orders)');
  } catch (e) {
    console.error('[cronShopifyWeeklySales] Error:', e.message);
  }
}

// product sales) -- not yet verified against a real response from
// this specific account.
async function amazonSalesTrafficDownload(request, env) {
  try {
    const { reportDocumentIds } = await request.json().catch(() => ({}));
    if (!reportDocumentIds || !Array.isArray(reportDocumentIds) || !reportDocumentIds.length) {
      return cors(new Response(JSON.stringify({ ok: false, error: 'reportDocumentIds array required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    }

    const amzToken = await getAmazonToken(env);
    const amzDate = () => new Date().toISOString().replace(/[:\-.]/g,'').slice(0,15)+'Z';

    // sku -> { sku, asin, unitsOrdered, orderedProductSales }
    const bySku = {};
    const errors = [];
    const rawSamples = [];

    for (const reportDocumentId of reportDocumentIds) {
      try {
        const docRes = await fetch(`https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/documents/${reportDocumentId}`, { headers: { 'x-amz-access-token': amzToken, 'x-amz-date': amzDate() } });
        const docData = await docRes.json();
        if (!docRes.ok || !docData.url) { errors.push(`${reportDocumentId}: document fetch failed - ${JSON.stringify(docData)}`); continue; }

        const reportRes = await fetch(docData.url);
        const rawBytes = await reportRes.arrayBuffer();
        const magic = new Uint8Array(rawBytes.slice(0,2));
        let reportText;
        if (magic[0]===0x1f && magic[1]===0x8b) {
          const ds = new DecompressionStream('gzip');
          const writer = ds.writable.getWriter();
          const reader = ds.readable.getReader();
          writer.write(new Uint8Array(rawBytes)); writer.close();
          const chunks = []; let done = false;
          while (!done) { const { value, done: d } = await reader.read(); if (value) chunks.push(value); done = d; }
          const total = chunks.reduce((a,c)=>a+c.length,0);
          const combined = new Uint8Array(total); let offset = 0;
          for (const chunk of chunks) { combined.set(chunk, offset); offset += chunk.length; }
          reportText = new TextDecoder().decode(combined);
        } else {
          reportText = new TextDecoder().decode(rawBytes);
        }

        const parsed = JSON.parse(reportText);
        // DEBUG: capture the real top-level shape whenever nothing
        // matches, so the next fix is based on what Amazon actually
        // sent rather than another guess at field names.
        rawSamples.push({ reportDocumentId, topLevelKeys: Object.keys(parsed), sample: JSON.stringify(parsed).slice(0, 2000) });
        // CONFIRMED via a real response: the correct key is
        // salesAndTrafficByAsin (both prior guesses were wrong).
        const salesRows = parsed.salesAndTrafficByAsin || [];
        if (salesRows.length) {
          rawSamples.push({ reportDocumentId, firstAsinRow: salesRows[0] });
        }
        for (const row of salesRows) {
          const sku = row.sku || row.parentAsin || row.childAsin || 'UNKNOWN';
          if (!bySku[sku]) bySku[sku] = { sku, asin: row.childAsin || row.parentAsin || null, unitsOrdered: 0, orderedProductSales: 0 };
          // Field names within each row unconfirmed until we see a real
          // one — try the most likely nesting based on the confirmed
          // salesByDate/trafficByDate pattern (salesByAsin/trafficByAsin),
          // falling back to a flatter shape in case it differs.
          const sales = row.salesByAsin || row.sales || row;
          bySku[sku].unitsOrdered += Number(sales.unitsOrdered || 0);
          const opsVal = sales.orderedProductSales;
          bySku[sku].orderedProductSales += Number((opsVal && typeof opsVal === 'object' ? opsVal.amount : opsVal) || 0);
        }
      } catch (e) {
        errors.push(`${reportDocumentId}: ${e.message}`);
      }
    }

    return cors(new Response(JSON.stringify({
      ok: true, skuCount: Object.keys(bySku).length, rows: Object.values(bySku),
      errors: errors.length ? errors : null,
      debug: rawSamples.length ? rawSamples : undefined,
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

let _amazonTokenCache = null;

// Shopify client_credentials grant — mirrors getAmazonToken exactly.
// Confirmed working against the real store (2026-07-25): this specific
// store IS permitted for client_credentials (some Shopify stores require
// token exchange or authorization code grant instead — see Shopify's own
// docs on this — but this one works). Token expires in ~24h
// (expires_in from Shopify was 86399), same short-lived-token pattern as
// Amazon, so this needs the same auto-refresh caching, not a static env
// var holding a fixed token.
let _shopifyTokenCache = null;
async function getShopifyToken(env) {
  const now = Date.now();
  if (_shopifyTokenCache && _shopifyTokenCache.exp > now + 60000) return _shopifyTokenCache.token;
  const res = await fetch(`https://${env.SHOPIFY_STORE_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'client_credentials', client_id: env.SHOPIFY_CLIENT_ID, client_secret: env.SHOPIFY_CLIENT_SECRET }),
  });
  const data = await res.json();
  if (!data.access_token) throw new Error('Shopify token error: ' + JSON.stringify(data));
  _shopifyTokenCache = { token: data.access_token, exp: now + (data.expires_in * 1000) };
  return data.access_token;
}

// Walmart Marketplace client_credentials — genuinely different auth
// convention from every other platform in this project: Basic auth
// (base64 client_id:client_secret) rather than a body-based exchange,
// custom WM_QOS.CORRELATION_ID/WM_SVC.NAME headers required alongside
// it, and the resulting token goes in a WM_SEC.ACCESS_TOKEN header on
// every subsequent call, not a standard Authorization: Bearer header.
// Also a much shorter-lived token (15 min / 900s) than eBay/Shopify, so
// the same caching pattern refreshes noticeably more often here.
let _walmartTokenCache = null;
async function getWalmartToken(env) {
  const now = Date.now();
  if (_walmartTokenCache && _walmartTokenCache.exp > now + 60000) return _walmartTokenCache.token;
  const basicAuth = btoa(`${env.WALMART_CLIENT_ID}:${env.WALMART_CLIENT_SECRET}`);
  const res = await fetch('https://marketplace.walmartapis.com/v3/token', {
    method: 'POST',
    headers: {
      'Authorization': `Basic ${basicAuth}`,
      'Content-Type': 'application/x-www-form-urlencoded',
      'Accept': 'application/json',
      'WM_SVC.NAME': 'Walmart Marketplace',
      'WM_QOS.CORRELATION_ID': crypto.randomUUID(),
    },
    body: 'grant_type=client_credentials',
  });
  const data = await res.json();
  if (!data.access_token) throw new Error('Walmart token error: ' + JSON.stringify(data));
  _walmartTokenCache = { token: data.access_token, exp: now + (data.expires_in * 1000) };
  return data.access_token;
}

// GET /walmart/order-lookup?customerOrderId=... — confirmed from
// Walmart's own docs: their Orders API supports searching by
// customerOrderId (the value Veeqo shows as "order number") and
// returns purchaseOrderId in the same response — the actual value
// Walmart Seller Center's order-detail URL needs. Built specifically
// because Veeqo's order number and Walmart's real PO number are
// confirmed genuinely different values, with no PO number available
// from Veeqo's data at all.
// RESTORED: this function was accidentally lost when a later build
// started from an earlier base file instead of the then-current
// latest one. Re-applied here verbatim from the original delivery.
async function walmartOrderLookup(url, env) {
  try {
    const customerOrderId = url.searchParams.get('customerOrderId');
    if (!customerOrderId) return cors(new Response(JSON.stringify({ ok: false, error: 'customerOrderId parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getWalmartToken(env);

    const res = await fetch(`https://marketplace.walmartapis.com/v3/orders?customerOrderId=${encodeURIComponent(customerOrderId)}`, {
      headers: {
        'WM_SEC.ACCESS_TOKEN': token,
        'WM_QOS.CORRELATION_ID': crypto.randomUUID(),
        'WM_SVC.NAME': 'Walmart Marketplace',
        'Accept': 'application/json',
      },
    });
    const data = await res.json();
    if (!res.ok) return cors(new Response(JSON.stringify({ ok: false, error: 'Walmart order lookup failed: ' + JSON.stringify(data) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const order = data.list && data.list.elements && data.list.elements.order && data.list.elements.order[0];
    if (!order) return cors(new Response(JSON.stringify({ ok: true, found: false }), { headers: { 'Content-Type': 'application/json' } }));

    return cors(new Response(JSON.stringify({ ok: true, found: true, purchaseOrderId: order.purchaseOrderId, customerOrderId: order.customerOrderId }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

async function shopifyGraphQL(env, query, variables) {
  const token = await getShopifyToken(env);
  const apiVersion = '2026-07';
  const res = await fetch(`https://${env.SHOPIFY_STORE_DOMAIN}/admin/api/${apiVersion}/graphql.json`, {
    method: 'POST',
    headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, variables }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error('Shopify GraphQL HTTP ' + res.status + ': ' + JSON.stringify(data));
  if (data.errors) throw new Error('Shopify GraphQL errors: ' + JSON.stringify(data.errors));
  return data.data;
}

// ═══════════════════════════════════════════════════════════════════════
// SHOPIFY NEW LISTING UPLOAD
//
// Confirmed with the user: Shopify listings are always single-piece
// (qty=1) — the tiered pack-size pricing that Amazon/eBay get as separate
// listings/variants is instead handled by a volume-discount app at
// checkout on Shopify. This means NO product options/variants are
// needed — genuinely simpler than the multi-variant "new product model"
// flow, which has real, actively-reported gotchas (default variant
// replacement bugs, etc) that this design sidesteps entirely by not
// using variants at all.
//
// Flow (2 GraphQL calls, both confirmed against Shopify's own current
// docs — REST is fully deprecated for products as of 2024-04, this is
// GraphQL-only):
//   1. productCreate — creates the product (title, description, vendor,
//      productType, tags, media/images). Shopify auto-creates ONE default
//      variant since no options were specified.
//   2. productVariantsBulkUpdate — sets price, weight, SKU, barcode on
//      that single default variant. Shopify has no plain single-variant
//      update mutation — the bulk one is the documented correct call
//      even for exactly one variant.
//
// Reads from the product_catalog D1 table (imported earlier from the
// Product_Catalog sheet) — base_sku rows only, since Shopify doesn't need
// the pack-size fan-out the marketplace platforms do. If multiple SKUs
// share a base_sku (the =1XX/=5XX/etc pack variants), only ONE Shopify
// listing gets created per base_sku — pack size doesn't apply here.
// ═══════════════════════════════════════════════════════════════════════

// GET /shopify/catalog-list — one row per base_sku (pack_qty=1 preferred,
// same deterministic ordering as shopifyListingCreate), for the Shopify
// Listings tab's table. Includes shopify_product_id/pushed_at so the
// frontend can show already-pushed status without a separate call.
async function shopifyCatalogList(url, env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    // BUGFIX: this always grouped to one row per base_sku (the pack_qty=1
    // variant), which is correct for Shopify (single-piece only, by
    // design) but wrong for eBay — individual eBay listings are meant to
    // be one PER PACK SIZE, so the eBay tab's table was silently only
    // showing/letting the user select the 1-pack row, even though
    // staging actually creates listings for every pack size. Defaults to
    // grouped=true (Shopify's existing behavior, unchanged) unless
    // ?grouped=false is passed, which the eBay tab now does.
    const grouped = url.searchParams.get('grouped') !== 'false';
    const allRows = await d1All(env, 'SELECT * FROM product_catalog ORDER BY base_sku, pack_qty ASC');

    let sourceRows;
    if (grouped) {
      const byBaseSku = {};
      for (const row of allRows) {
        if (!byBaseSku[row.base_sku]) byBaseSku[row.base_sku] = row; // first row per base_sku wins — already ordered by pack_qty ASC
      }
      sourceRows = Object.values(byBaseSku);
    } else {
      sourceRows = allRows; // every pack-size row, ungrouped
    }

    const rows = sourceRows.map(r => ({
      baseSku: r.base_sku, sku: r.sku, packQty: r.pack_qty, title: r.title, titleShort: r.title_short, manufacturer: r.manufacturer,
      fittingType: r.fitting_type, price: r.starting_price, status: r.status,
      shopifyProductId: r.shopify_product_id, shopifyPushedAt: r.shopify_pushed_at,
      ebayCategoryId: r.ebay_category_id, ebayOfferId: r.ebay_offer_id,
      ebayListingId: r.ebay_listing_id, ebayStagedAt: r.ebay_staged_at, ebayPublishedAt: r.ebay_published_at,
      ebayVariationGroupKey: r.ebay_variation_group_key, ebayVariationListingId: r.ebay_variation_listing_id,
    }));
    return cors(new Response(JSON.stringify({ ok: true, rows }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// ═══════════════════════════════════════════════════════════════════════
// EBAY NEW LISTING UPLOAD — account discovery first
//
// eBay's Inventory API create-listing flow needs THREE things referenced
// by ID that are specific to this seller's account and can't be
// defaulted the way Shopify's productType could:
//   - A payment policy ID, fulfillment (shipping) policy ID, and return
//     policy ID — normally set up once in Seller Hub > Business Policies
//   - A merchant inventory location key
//   - An eBay category ID for the listing
//
// Rather than asking the user to hunt these down manually, the existing
// eBay OAuth token already includes sell.account scope, so this reads
// them directly from the account via the Account API and Inventory API.
// Read-only, safe to call any time — this is the discovery step before
// building the actual create-listing flow, not the create flow itself.
// ═══════════════════════════════════════════════════════════════════════
// POST /ebay/location-create
// Creates the inventory location required before any offer can be
// created — confirmed via ebayAccountDiscover that none currently exist
// on this account. merchantLocationKey is a fixed, simple identifier
// since there's only ever one warehouse for this business.
// GET /ebay/category-suggest?q=... — finds real, valid eBay category IDs
// for a search term via the Taxonomy API, rather than guessing a numeric
// ID from memory (a wrong guess would silently misfile every listing
// into the wrong category with no obvious error). 2-step flow per eBay's
// own docs: get the marketplace's category tree ID, then query
// suggestions within that tree.
// ═══════════════════════════════════════════════════════════════════════
// EBAY LISTING CREATE — stage, then publish separately
//
// eBay's own Inventory API naturally splits into: create the inventory
// item record, create an offer referencing it (policies/location/
// category/price), and only THEN publish to make it live. This gives the
// same "review before it's live" safety Shopify's draft status gave us,
// using eBay's own staging mechanism instead of a status flag — nothing
// created here is a live listing until listing-publish is called
// separately with the returned offerId.
//
// Confirmed account specifics used as defaults:
//   locationKey: XFITTING_WAREHOUSE (created earlier)
//   paymentPolicyId: 252377429011 (eBay Managed Payments)
//   returnPolicyId: 132540225011 (seller-paid, 30 days)
//   fulfillmentPolicyId: selectable per item — defaults to 148662065011
//     (charges shipping), since 1-piece listings on this account don't
//     bake shipping into the price the way the tiered-pack pricing does
//
// HONESTY NOTE: eBay categories can have REQUIRED "item specifics"
// (aspects) that vary by category and aren't something I have full
// visibility into without an additional Taxonomy API call
// (getItemAspectsForCategory) this doesn't make yet. Mapped the
// product_catalog fields that clearly correspond (material, connection
// types, sizes) as a best-effort aspects payload, but if eBay's category
// requires something not covered here, createOffer will fail with a
// specific error naming what's missing — not a guess, a real answer from
// eBay directly, which is a fast fix once we see it. Always dry-run
// first, same as everywhere else in this project.
// ═══════════════════════════════════════════════════════════════════════

const EBAY_DEFAULTS = {
  merchantLocationKey: 'XFITTING_WAREHOUSE',
  paymentPolicyId: '252377429011',
  returnPolicyId: '132540225011',
  fulfillmentPolicyId: '148662065011', // charges shipping — 1-piece default
  marketplaceId: 'EBAY_US',
};

// Account-level constants, confirmed with the user — same everywhere
// across the catalog, not per-product, so these live here rather than as
// new product_catalog columns.
const WALMART_DEFAULTS = {
  fulfillmentCenterID: '10001604424',
  countryOfOrigin: 'China',
  quantity: 8888, // same "always in stock" convention as eBay/Shopify
};

async function ebayListingStage(request, env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const body = await request.json().catch(() => ({}));
    const items = Array.isArray(body.items) ? body.items : [];
    const dryRun = body.dryRun === true;
    if (!items.length) return cors(new Response(JSON.stringify({ ok: false, error: 'items array required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const results = [];
    for (const item of items) {
      const baseSku = String(item.baseSku || '').trim().toUpperCase();
      const quantity = item.quantity !== undefined && item.quantity !== null ? parseInt(item.quantity) : 8888;
      const fulfillmentPolicyId = item.fulfillmentPolicyId || EBAY_DEFAULTS.fulfillmentPolicyId;

      if (!baseSku || !quantity || quantity < 1) { results.push({ baseSku, ok: false, error: 'baseSku and a positive quantity are required' }); continue; }

      // BUGFIX: previously picked only the single pack_qty=1 row per
      // base_sku, so 2X/5X/10X pack variants never got their own listing
      // at all. Individual listings (this function) are meant to be one
      // per PACK SIZE — confirmed as the account's established
      // convention, matching Amazon's per-ASIN pack-size listings — not
      // one per base product. Loops every pack-size row now.
      const rows = await d1All(env, 'SELECT * FROM product_catalog WHERE base_sku=? ORDER BY pack_qty ASC', [baseSku]);
      if (!rows.length) { results.push({ baseSku, ok: false, error: 'Not found in product_catalog' }); continue; }

      for (const row of rows) {
      if (!row.title_short || !row.starting_price || !row.ebay_category_id) {
        results.push({ baseSku, sku: row.sku, ok: false, error: 'Missing required field (title_short, starting_price, or ebay_category_id)' }); continue;
      }
      if (row.title_short.length > 80) { results.push({ baseSku, sku: row.sku, ok: false, error: `title_short is ${row.title_short.length} chars — exceeds eBay's 80-char limit` }); continue; }

      // Guard against accidental duplicate offers — same pattern as
      // Shopify's already-pushed check. Publishing is a separate step,
      // so "already staged" doesn't necessarily mean "already live" —
      // surfaced distinctly so the frontend can tell the difference.
      const alreadyStaged = !!row.ebay_offer_id;
      const alreadyPublished = !!row.ebay_listing_id;
      if (alreadyStaged && !item.force && !dryRun) {
        results.push({ baseSku, sku: row.sku, ok: false, error: `Already staged (offer ${row.ebay_offer_id})${alreadyPublished ? ', already published as listing ' + row.ebay_listing_id : ' — not yet published'} — pass force:true to stage another offer anyway`, alreadyStaged, alreadyPublished, existingOfferId: row.ebay_offer_id, existingListingId: row.ebay_listing_id || null });
        continue;
      }

      const images = [row.image_url_1, row.image_url_2, row.image_url_3, row.image_url_4, row.image_url_5].filter(Boolean);
      const bullets = [row.bullet_1, row.bullet_2, row.bullet_3, row.bullet_4, row.bullet_5].filter(Boolean);
      const descriptionHtml = (row.description || '') + (bullets.length ? '<ul>' + bullets.map(b => `<li>${b}</li>`).join('') + '</ul>' : '');

      // Best-effort aspects mapping — see HONESTY NOTE above
      const aspects = {};
      // BUGFIX: confirmed via a real "item specific Type is missing"
      // error — this category requires a Type aspect that was never
      // being set at all. Maps directly to fitting_type, already in the
      // catalog (e.g. "Check Valve").
      if (row.fitting_type) aspects['Type'] = [row.fitting_type];
      if (row.material) aspects['Material'] = [row.material];
      if (row.connection_type_1) aspects['Connection Type'] = [row.connection_type_1];
      if (row.size_1) aspects['Size'] = [row.size_1];
      if (row.manufacturer) aspects['Brand'] = [row.manufacturer];

      const inventoryItemPayload = {
        availability: { shipToLocationAvailability: { quantity } },
        condition: 'NEW',
        product: {
          title: row.title_short,
          description: descriptionHtml,
          aspects,
          imageUrls: images,
          ...(row.upc ? { upc: [row.upc] } : {}),
        },
      };

      const offerPayload = {
        sku: row.sku,
        marketplaceId: EBAY_DEFAULTS.marketplaceId,
        format: 'FIXED_PRICE',
        availableQuantity: quantity,
        categoryId: row.ebay_category_id,
        listingDescription: descriptionHtml,
        listingPolicies: {
          paymentPolicyId: EBAY_DEFAULTS.paymentPolicyId,
          fulfillmentPolicyId,
          returnPolicyId: EBAY_DEFAULTS.returnPolicyId,
        },
        pricingSummary: { price: { value: String(row.starting_price), currency: 'USD' } },
        merchantLocationKey: EBAY_DEFAULTS.merchantLocationKey,
      };

      if (dryRun) {
        results.push({ baseSku, ok: true, dryRun: true, sku: row.sku, alreadyStaged, alreadyPublished, preview: { inventoryItemPayload, offerPayload } });
        continue;
      }

      try {
        const token = await getEbayToken(env);
        const itemRes = await fetch(`https://api.ebay.com/sell/inventory/v1/inventory_item/${encodeURIComponent(row.sku)}`, {
          method: 'PUT',
          headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Language': 'en-US' },
          body: JSON.stringify(inventoryItemPayload),
        });
        if (itemRes.status !== 200 && itemRes.status !== 204) {
          const errData = await itemRes.json().catch(() => ({}));
          results.push({ baseSku, sku: row.sku, ok: false, error: 'createOrReplaceInventoryItem failed: ' + JSON.stringify(errData) });
          continue;
        }

        const offerRes = await fetch('https://api.ebay.com/sell/inventory/v1/offer', {
          method: 'POST',
          headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Language': 'en-US' },
          body: JSON.stringify(offerPayload),
        });
        const offerData = await offerRes.json();
        if (!offerRes.ok || !offerData.offerId) {
          // BUGFIX: confirmed via a real report — this function never
          // had the "offer already exists" reuse fix that the variation
          // flow already has. When createOffer fails with errorId 25002
          // (D1's own ebay_offer_id tracking was empty/out of sync with
          // what eBay's system actually has — likely from an earlier
          // partial attempt), extracts the existing offerId from the
          // error and updates it with current data instead of failing
          // outright.
          const existingOfferId = offerData.errors && offerData.errors[0] && offerData.errors[0].errorId === 25002
            ? (offerData.errors[0].parameters || []).find(p => p.name === 'offerId')
            : null;
          if (existingOfferId && existingOfferId.value) {
            const updateRes = await fetch(`https://api.ebay.com/sell/inventory/v1/offer/${encodeURIComponent(existingOfferId.value)}`, {
              method: 'PUT',
              headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Language': 'en-US' },
              body: JSON.stringify(offerPayload),
            });
            if (updateRes.status !== 200 && updateRes.status !== 204) {
              const updateErrData = await updateRes.json().catch(() => ({}));
              results.push({ baseSku, sku: row.sku, ok: false, error: `updateOffer failed for existing offer ${existingOfferId.value}: ` + JSON.stringify(updateErrData) });
              continue;
            }
            offerData.offerId = existingOfferId.value;
          } else {
            results.push({ baseSku, sku: row.sku, ok: false, error: 'createOffer failed: ' + JSON.stringify(offerData) });
            continue;
          }
        }

        const stagedAt = new Date().toISOString();
        await env.DB.prepare('UPDATE product_catalog SET ebay_offer_id=?, ebay_staged_at=? WHERE sku=?')
          .bind(offerData.offerId, stagedAt, row.sku).run().catch(e => console.error('[eBay] tracking write-back failed (offer still created fine):', e.message));

        results.push({ baseSku, ok: true, sku: row.sku, offerId: offerData.offerId, status: 'STAGED_NOT_PUBLISHED', stagedAt });
      } catch (e) {
        results.push({ baseSku, sku: row.sku, ok: false, error: e.message });
      }
      } // end for (const row of rows)
    } // end for (const item of items)

    return cors(new Response(JSON.stringify({ ok: true, results }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// POST /ebay/listing-publish — Body: { offerIds: [...] }
// The actual "go live" step, only reachable with offerIds already
// returned by a successful ebayListingStage call.
async function ebayListingPublish(request, env) {
  try {
    const body = await request.json().catch(() => ({}));
    const offerIds = Array.isArray(body.offerIds) ? body.offerIds : [];
    if (!offerIds.length) return cors(new Response(JSON.stringify({ ok: false, error: 'offerIds array required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const token = await getEbayToken(env);
    const results = [];
    for (const offerId of offerIds) {
      try {
        const res = await fetch(`https://api.ebay.com/sell/inventory/v1/offer/${encodeURIComponent(offerId)}/publish`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        });
        const data = await res.json();
        if (!res.ok || !data.listingId) { results.push({ offerId, ok: false, error: JSON.stringify(data) }); continue; }

        const publishedAt = new Date().toISOString();
        if (env.DB) {
          await env.DB.prepare('UPDATE product_catalog SET ebay_listing_id=?, ebay_published_at=? WHERE ebay_offer_id=?')
            .bind(data.listingId, publishedAt, offerId).run().catch(e => console.error('[eBay] publish tracking write-back failed (listing still went live fine):', e.message));
        }

        results.push({ offerId, ok: true, listingId: data.listingId, publishedAt });
      } catch (e) {
        results.push({ offerId, ok: false, error: e.message });
      }
    }

    return cors(new Response(JSON.stringify({ ok: true, results }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// POST /ebay/offer-delete — Body: {offerId, sku}
// Deletes an offer entirely (not just unpublishes it) and clears D1's
// tracking columns for that SKU, so it can be re-staged completely
// fresh. Built for the "Product not found" publishOffer error (errorId
// 25604) — a genuinely known, widely-reported eBay issue with no
// consistent documented root cause across years of their own developer
// forums. Deleting and recreating from scratch is the most reliable
// path other developers report working, rather than continuing to
// update a potentially stuck offer record.
async function ebayOfferDelete(request, env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const body = await request.json().catch(() => ({}));
    const offerId = (body.offerId || '').trim();
    const sku = (body.sku || '').trim();
    if (!offerId) return cors(new Response(JSON.stringify({ ok: false, error: 'offerId required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const token = await getEbayToken(env);
    const delRes = await fetch(`https://api.ebay.com/sell/inventory/v1/offer/${encodeURIComponent(offerId)}`, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${token}` },
    });

    // eBay returns 204 with no body on success. A 404 here is treated
    // as success too — the offer's already gone, which is the desired
    // end state either way.
    if (delRes.status !== 204 && delRes.status !== 404) {
      const errData = await delRes.json().catch(() => ({}));
      return cors(new Response(JSON.stringify({ ok: false, error: 'deleteOffer failed: ' + JSON.stringify(errData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
    }

    if (sku) {
      await env.DB.prepare('UPDATE product_catalog SET ebay_offer_id=NULL, ebay_staged_at=NULL, ebay_listing_id=NULL, ebay_published_at=NULL WHERE sku=?')
        .bind(sku).run().catch(e => console.error('[eBay] D1 tracking clear failed (offer still deleted fine):', e.message));
    }

    return cors(new Response(JSON.stringify({ ok: true, deletedOfferId: offerId, sku: sku || null }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /ebay/return-lookup?returnId=... — full return details (reason,
// state, refund amount) via eBay's Post-Order API.
// HONESTY NOTE: a real developer on eBay's own community forum reported
// this exact endpoint returning "prohibited" through code despite
// working in the API Explorer, suggesting it may need permissions not
// granted by default seller API access. Genuinely unverified whether
// this account's credentials have that access — this is the actual
// test of that, not a confirmed-working feature yet.
async function ebayReturnLookup(url, env) {
  try {
    const returnId = url.searchParams.get('returnId');
    if (!returnId) return cors(new Response(JSON.stringify({ ok: false, error: 'returnId parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getEbayToken(env);

    const res = await fetch(`https://api.ebay.com/post-order/v2/return/${encodeURIComponent(returnId)}`, {
      headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) return cors(new Response(JSON.stringify({ ok: false, error: `Return lookup failed (HTTP ${res.status}): ` + JSON.stringify(data) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const s = data.summary || {};
    return cors(new Response(JSON.stringify({
      ok: true, returnId,
      state: s.state || null,
      type: s.currentType || null,
      reason: (s.creationInfo && s.creationInfo.reason) || null,
      createdAt: (s.creationInfo && s.creationInfo.creationDate && s.creationInfo.creationDate.value) || null,
      buyerRefund: (s.buyerTotalRefund && s.buyerTotalRefund.actualRefundAmount) || null,
      itemId: (s.creationInfo && s.creationInfo.item && s.creationInfo.item.itemId) || null,
      rawResponse: data,
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// ═══════════════════════════════════════════════════════════════════════
// EBAY VARIATION LISTING — one listing, all pack sizes as a dropdown
//
// Built alongside (not instead of) the individual per-pack-size listings
// above — confirmed both are wanted simultaneously.
//
// BUGFIX: this previously reused the same real SKU as the standalone
// listings, based on an earlier confirmation that this was fine. Live
// testing proved otherwise — eBay rejects createOrReplaceInventoryItemGroup
// with a specific, confirmed error when a SKU is already published as a
// standalone listing: "The following SKU is already listed as a single
// SKU listing." Once a SKU has an active standalone listing, eBay locks
// it out of group membership entirely. Reverted to a derived SKU
// (suffixed "-VAR") for every variation-group member, which sidesteps
// this conflict regardless of whether a given SKU happens to already be
// published standalone — genuinely a separate inventory item on eBay's
// side, so there's nothing for the two listing types to collide over.
// ═══════════════════════════════════════════════════════════════════════

function ebayVariationSku(realSku) { return realSku + '-VAR'; }

async function ebayVariationStage(request, env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const body = await request.json().catch(() => ({}));
    const baseSku = String(body.baseSku || '').trim().toUpperCase();
    const dryRun = body.dryRun === true;
    const quantity = body.quantity !== undefined && body.quantity !== null ? parseInt(body.quantity) : 8888;
    const fulfillmentPolicyId = body.fulfillmentPolicyId || EBAY_DEFAULTS.fulfillmentPolicyId;
    if (!baseSku) return cors(new Response(JSON.stringify({ ok: false, error: 'baseSku required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const rows = await d1All(env, 'SELECT * FROM product_catalog WHERE base_sku=? ORDER BY pack_qty ASC', [baseSku]);
    if (!rows.length) return cors(new Response(JSON.stringify({ ok: false, error: 'Not found in product_catalog' }), { status: 404, headers: { 'Content-Type': 'application/json' } }));
    if (rows.length < 2) return cors(new Response(JSON.stringify({ ok: false, error: 'Only 1 pack size found — a variation listing needs at least 2 to make sense' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    for (const row of rows) {
      if (!row.starting_price || !row.ebay_category_id) {
        return cors(new Response(JSON.stringify({ ok: false, error: `${row.sku} is missing starting_price or ebay_category_id` }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
      }
    }

    const alreadyStaged = rows.some(r => r.ebay_variation_group_key);
    if (alreadyStaged && !body.force && !dryRun) {
      return cors(new Response(JSON.stringify({ ok: false, error: `Already staged as variation group ${rows[0].ebay_variation_group_key}${rows[0].ebay_variation_listing_id ? ', already published as listing ' + rows[0].ebay_variation_listing_id : ' — not yet published'} — pass force:true to stage again`, alreadyStaged: true, existingGroupKey: rows[0].ebay_variation_group_key, existingListingId: rows[0].ebay_variation_listing_id || null }), { headers: { 'Content-Type': 'application/json' } }));
    }

    const groupKey = baseSku + '-GROUP';
    const groupTitleRow = rows[0]; // any row's base product info works — title/description below are shared across all variants
    const images = [groupTitleRow.image_url_1, groupTitleRow.image_url_2, groupTitleRow.image_url_3, groupTitleRow.image_url_4, groupTitleRow.image_url_5].filter(Boolean);
    const bullets = [groupTitleRow.bullet_1, groupTitleRow.bullet_2, groupTitleRow.bullet_3, groupTitleRow.bullet_4, groupTitleRow.bullet_5].filter(Boolean);
    const descriptionHtml = (groupTitleRow.description || '') + (bullets.length ? '<ul>' + bullets.map(b => `<li>${b}</li>`).join('') + '</ul>' : '');
    // Group title must be <=80 chars too, same eBay-wide limit as individual listings
    const groupTitle = groupTitleRow.title_short ? groupTitleRow.title_short.replace(/^\d+\s*Pack\s*/i, '').trim() : '';
    if (!groupTitle || groupTitle.length > 80) {
      return cors(new Response(JSON.stringify({ ok: false, error: `Could not derive a valid group title (<=80 chars) from title_short` }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    }

    // BUGFIX: confirmed via real eBay errors — this previously (a) built
    // ONE shared aspects object reused identically for every inventory
    // item, so no member had its own distinguishing value at all, and
    // (b) used a made-up "Pack Size" aspect with values like "5 Pack".
    // Confirmed via the account's own manual listing convention: the
    // correct aspect name is "Quantity", and the value is the bare
    // number ("5", not "5 Pack") — this is what's actually used when
    // creating this exact kind of listing by hand. Each member's
    // inventory item needs its OWN aspects including its OWN specific
    // Quantity value, not just the group-level declaration of which
    // aspect varies.
    const baseAspects = {};
    if (groupTitleRow.fitting_type) baseAspects['Type'] = [groupTitleRow.fitting_type];
    if (groupTitleRow.material) baseAspects['Material'] = [groupTitleRow.material];
    if (groupTitleRow.connection_type_1) baseAspects['Connection Type'] = [groupTitleRow.connection_type_1];
    if (groupTitleRow.manufacturer) baseAspects['Brand'] = [groupTitleRow.manufacturer];

    const variantSKUs = rows.map(r => ebayVariationSku(r.sku));
    const quantityValues = rows.map(r => String(r.pack_qty));

    const groupPayload = {
      title: groupTitle,
      description: descriptionHtml,
      imageUrls: images,
      variantSKUs,
      variesBy: {
        aspectsImageVariesBy: [],
        specifications: [{ name: 'Quantity', values: quantityValues }],
      },
    };

    if (dryRun) {
      const preview = {
        groupKey, groupPayload,
        members: rows.map((r, i) => ({
          realSku: r.sku, variationSku: variantSKUs[i], packQty: r.pack_qty, price: r.starting_price,
        })),
      };
      return cors(new Response(JSON.stringify({ ok: true, dryRun: true, baseSku, alreadyStaged, preview }), { headers: { 'Content-Type': 'application/json' } }));
    }

    const token = await getEbayToken(env);

    // Step 1: create an inventory item for each variant's DERIVED sku —
    // see the top-of-section note for why this is a separate sku from
    // the standalone listing again, not the same one.
    for (const row of rows) {
      const vSku = ebayVariationSku(row.sku);
      const itemAspects = { ...baseAspects, 'Quantity': [String(row.pack_qty)] };
      const itemPayload = {
        availability: { shipToLocationAvailability: { quantity } },
        condition: 'NEW',
        product: { title: row.title_short, description: descriptionHtml, aspects: itemAspects, imageUrls: images, ...(row.upc ? { upc: [row.upc] } : {}) },
      };
      const res = await fetch(`https://api.ebay.com/sell/inventory/v1/inventory_item/${encodeURIComponent(vSku)}`, {
        method: 'PUT',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Language': 'en-US' },
        body: JSON.stringify(itemPayload),
      });
      if (res.status !== 200 && res.status !== 204) {
        const errData = await res.json().catch(() => ({}));
        return cors(new Response(JSON.stringify({ ok: false, error: `createOrReplaceInventoryItem failed for ${vSku}: ` + JSON.stringify(errData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
      }
    }

    // Step 2: create the group, linking all the variant SKUs together
    const groupRes = await fetch(`https://api.ebay.com/sell/inventory/v1/inventory_item_group/${encodeURIComponent(groupKey)}`, {
      method: 'PUT',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Language': 'en-US' },
      body: JSON.stringify(groupPayload),
    });
    if (groupRes.status !== 200 && groupRes.status !== 204) {
      const errData = await groupRes.json().catch(() => ({}));
      return cors(new Response(JSON.stringify({ ok: false, error: 'createOrReplaceInventoryItemGroup failed: ' + JSON.stringify(errData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
    }

    // Step 3: create an offer for each variant's DERIVED SKU —
    // listingDescription omitted here since it's set at the group level,
    // per eBay's docs.
    const offerIds = [];
    for (const row of rows) {
      const vSku = ebayVariationSku(row.sku);
      const offerPayload = {
        sku: vSku,
        marketplaceId: EBAY_DEFAULTS.marketplaceId,
        format: 'FIXED_PRICE',
        availableQuantity: quantity,
        categoryId: row.ebay_category_id,
        listingPolicies: {
          paymentPolicyId: EBAY_DEFAULTS.paymentPolicyId,
          fulfillmentPolicyId,
          returnPolicyId: EBAY_DEFAULTS.returnPolicyId,
        },
        pricingSummary: { price: { value: String(row.starting_price), currency: 'USD' } },
        merchantLocationKey: EBAY_DEFAULTS.merchantLocationKey,
      };
      const offerRes = await fetch('https://api.ebay.com/sell/inventory/v1/offer', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Language': 'en-US' },
        body: JSON.stringify(offerPayload),
      });
      const offerData = await offerRes.json();
      if (!offerRes.ok || !offerData.offerId) {
        // BUGFIX: confirmed via a real retry attempt — if an earlier
        // staging attempt got partway through (e.g. failed later at
        // publish due to the category not supporting variations, an
        // unrelated failure), the offer for this sku may already exist.
        // createOffer isn't idempotent the way createOrReplaceInventoryItem
        // is, so a blind retry fails here with errorId 25002. eBay
        // conveniently includes the existing offerId right in the error's
        // parameters.
        //
        // BUGFIX 2: the first version of this fix just reused the
        // existing offerId as-is — confirmed via a second real failure
        // that this silently carries forward STALE data (e.g. the old,
        // wrong category from before a sheet correction), since the
        // offer itself was never actually updated, just reused. Now
        // calls updateOffer (PUT) with the CURRENT payload before
        // reusing the id, so a corrected category (or price, etc.)
        // actually takes effect on retry instead of silently persisting
        // whatever was there when the offer was first created.
        const existingOfferId = offerData.errors && offerData.errors[0] && offerData.errors[0].errorId === 25002
          ? (offerData.errors[0].parameters || []).find(p => p.name === 'offerId')
          : null;
        if (existingOfferId && existingOfferId.value) {
          const updateRes = await fetch(`https://api.ebay.com/sell/inventory/v1/offer/${encodeURIComponent(existingOfferId.value)}`, {
            method: 'PUT',
            headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Language': 'en-US' },
            body: JSON.stringify(offerPayload),
          });
          if (updateRes.status !== 200 && updateRes.status !== 204) {
            const updateErrData = await updateRes.json().catch(() => ({}));
            return cors(new Response(JSON.stringify({ ok: false, error: `updateOffer failed for existing offer ${existingOfferId.value} (${vSku}): ` + JSON.stringify(updateErrData), partialOfferIds: offerIds }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
          }
          offerIds.push(existingOfferId.value);
          continue;
        }
        return cors(new Response(JSON.stringify({ ok: false, error: `createOffer failed for ${vSku}: ` + JSON.stringify(offerData), partialOfferIds: offerIds }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
      }
      offerIds.push(offerData.offerId);
    }

    const stagedAt = new Date().toISOString();
    const writeBackStmts = rows.map(r => env.DB.prepare(
      'UPDATE product_catalog SET ebay_variation_group_key=?, ebay_variation_staged_at=? WHERE sku=?'
    ).bind(groupKey, stagedAt, r.sku));
    await env.DB.batch(writeBackStmts).catch(e => console.error('[eBay] variation tracking write-back failed (group still created fine):', e.message));

    return cors(new Response(JSON.stringify({ ok: true, baseSku, groupKey, offerIds, status: 'STAGED_NOT_PUBLISHED', stagedAt }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// POST /ebay/variation-publish — Body: { groupKey }
async function ebayVariationPublish(request, env) {
  try {
    const body = await request.json().catch(() => ({}));
    const groupKey = String(body.groupKey || '').trim();
    if (!groupKey) return cors(new Response(JSON.stringify({ ok: false, error: 'groupKey required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const token = await getEbayToken(env);
    const res = await fetch('https://api.ebay.com/sell/inventory/v1/offer/publish_by_inventory_item_group', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ inventoryItemGroupKey: groupKey, marketplaceId: EBAY_DEFAULTS.marketplaceId }),
    });
    const data = await res.json();
    if (!res.ok || !data.listingId) return cors(new Response(JSON.stringify({ ok: false, error: JSON.stringify(data) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const publishedAt = new Date().toISOString();
    if (env.DB) {
      await env.DB.prepare('UPDATE product_catalog SET ebay_variation_listing_id=?, ebay_variation_published_at=? WHERE ebay_variation_group_key=?')
        .bind(data.listingId, publishedAt, groupKey).run().catch(e => console.error('[eBay] variation publish tracking write-back failed (listing still went live fine):', e.message));
    }

    return cors(new Response(JSON.stringify({ ok: true, groupKey, listingId: data.listingId, publishedAt }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

async function ebayCategorySuggest(url, env) {
  try {
    const q = url.searchParams.get('q');
    if (!q) return cors(new Response(JSON.stringify({ ok: false, error: 'q parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getEbayToken(env);

    const treeRes = await fetch('https://api.ebay.com/commerce/taxonomy/v1/get_default_category_tree_id?marketplace_id=EBAY_US', {
      headers: { Authorization: `Bearer ${token}` },
    });
    const treeData = await treeRes.json();
    if (!treeData.categoryTreeId) return cors(new Response(JSON.stringify({ ok: false, error: 'Could not get category tree: ' + JSON.stringify(treeData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const suggestRes = await fetch(`https://api.ebay.com/commerce/taxonomy/v1/category_tree/${treeData.categoryTreeId}/get_category_suggestions?q=${encodeURIComponent(q)}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const suggestData = await suggestRes.json();
    const suggestions = (suggestData.categorySuggestions || []).map(s => ({
      categoryId: s.category.categoryId,
      categoryName: s.category.categoryName,
      // ancestor path, root-to-leaf, so it's clear where in the tree this sits
      path: (s.categoryTreeNodeAncestors || []).map(a => a.categoryName).reverse().concat([s.category.categoryName]).join(' > '),
    }));

    return cors(new Response(JSON.stringify({ ok: true, query: q, suggestions }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /ebay/category-check-leaf?categoryId=... — confirms whether a
// specific category ID is currently a valid leaf category. Built after
// a real publish failure ("category selected is not a leaf category")
// for a categoryId that presumably was a valid leaf when originally
// set — eBay's taxonomy can restructure over time, turning a former
// leaf into a parent as new subcategories get added underneath it.
// Uses getCategorySubtree, whose root node directly reports its own
// leafCategoryTreeNode status, confirmed from eBay's own docs.
async function ebayCategoryCheckLeaf(url, env) {
  try {
    const categoryId = url.searchParams.get('categoryId');
    if (!categoryId) return cors(new Response(JSON.stringify({ ok: false, error: 'categoryId parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getEbayToken(env);

    const treeRes = await fetch('https://api.ebay.com/commerce/taxonomy/v1/get_default_category_tree_id?marketplace_id=EBAY_US', {
      headers: { Authorization: `Bearer ${token}` },
    });
    const treeData = await treeRes.json();
    if (!treeData.categoryTreeId) return cors(new Response(JSON.stringify({ ok: false, error: 'Could not get category tree: ' + JSON.stringify(treeData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const subtreeRes = await fetch(`https://api.ebay.com/commerce/taxonomy/v1/category_tree/${treeData.categoryTreeId}/get_category_subtree?category_id=${encodeURIComponent(categoryId)}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const subtreeData = await subtreeRes.json();
    if (!subtreeRes.ok) return cors(new Response(JSON.stringify({ ok: false, error: 'getCategorySubtree failed: ' + JSON.stringify(subtreeData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const node = subtreeData.categorySubtreeNode;
    const isLeaf = !!(node && node.leafCategoryTreeNode);
    const childCategories = (node && node.childCategoryTreeNodes || []).map(c => ({ categoryId: c.category.categoryId, categoryName: c.category.categoryName }));

    return cors(new Response(JSON.stringify({
      ok: true, categoryId,
      categoryName: node && node.category ? node.category.categoryName : null,
      isLeaf,
      childCategories: isLeaf ? [] : childCategories, // if NOT a leaf, these are candidates to use instead
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /ebay/category-check-variations?categoryId=... — confirmed via live
// testing that not every category supports multi-variation listings
// (createOrReplaceInventoryItemGroup can succeed while the eventual
// publish still fails with "does not support multi-variation listings").
// The only reliable way to check this ahead of time is the OLDER, XML-
// based Trading API's GetCategoryFeatures call — the newer REST Taxonomy
// API doesn't expose this. Uses the same OAuth token via the
// X-EBAY-API-IAF-TOKEN header rather than a separate legacy auth flow.
// HONESTY NOTE: the X-EBAY-API-COMPATIBILITY-LEVEL value below is a
// reasonably current one, not something confirmed against a live call —
// if eBay rejects it as outdated, the error will say so explicitly and
// the fix is just bumping this number.
async function ebayCategoryVariationsCheck(url, env) {
  try {
    const categoryId = url.searchParams.get('categoryId');
    if (!categoryId) return cors(new Response(JSON.stringify({ ok: false, error: 'categoryId parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getEbayToken(env);

    const xmlBody = `<?xml version="1.0" encoding="utf-8"?>
<GetCategoryFeaturesRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <CategoryID>${categoryId}</CategoryID>
  <DetailLevel>ReturnAll</DetailLevel>
</GetCategoryFeaturesRequest>`;

    const res = await fetch('https://api.ebay.com/ws/api.dll', {
      method: 'POST',
      headers: {
        'X-EBAY-API-IAF-TOKEN': token,
        'X-EBAY-API-CALL-NAME': 'GetCategoryFeatures',
        'X-EBAY-API-SITEID': '0',
        'X-EBAY-API-COMPATIBILITY-LEVEL': '1157',
        'Content-Type': 'text/xml',
      },
      body: xmlBody,
    });
    const xmlText = await res.text();
    if (!res.ok) return cors(new Response(JSON.stringify({ ok: false, error: 'GetCategoryFeatures HTTP ' + res.status, rawSnippet: xmlText.slice(0, 500) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    // VariationsEnabled is returned as a present-but-empty element when
    // the feature applies (per eBay's own docs) — a simple substring
    // check is enough, no need for full XML parsing for one boolean flag.
    const variationsSupported = /<VariationsEnabled\s*\/?>/i.test(xmlText);
    const ackMatch = xmlText.match(/<Ack>([^<]+)<\/Ack>/i);
    const errorMatch = xmlText.match(/<LongMessage>([^<]+)<\/LongMessage>/i);

    return cors(new Response(JSON.stringify({
      ok: true, categoryId, variationsSupported,
      ack: ackMatch ? ackMatch[1] : null,
      error: errorMatch ? errorMatch[1] : null,
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /ebay/category-check-aspects?categoryId=... — surfaces a
// category's required/recommended item specifics upfront, via the
// Taxonomy API's getItemAspectsForCategory. Built after hitting three
// separate "item specific X is missing" publish failures in a row
// (Type, Brand, ...) — each only discoverable one at a time by actually
// attempting a real publish. This lets a category be checked once before
// staging, rather than continuing to play whack-a-mole per field.
async function ebayCategoryAspectsCheck(url, env) {
  try {
    const categoryId = url.searchParams.get('categoryId');
    if (!categoryId) return cors(new Response(JSON.stringify({ ok: false, error: 'categoryId parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getEbayToken(env);

    const treeRes = await fetch('https://api.ebay.com/commerce/taxonomy/v1/get_default_category_tree_id?marketplace_id=EBAY_US', {
      headers: { Authorization: `Bearer ${token}` },
    });
    const treeData = await treeRes.json();
    if (!treeData.categoryTreeId) return cors(new Response(JSON.stringify({ ok: false, error: 'Could not get category tree: ' + JSON.stringify(treeData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const aspectsRes = await fetch(`https://api.ebay.com/commerce/taxonomy/v1/category_tree/${treeData.categoryTreeId}/get_item_aspects_for_category?category_id=${encodeURIComponent(categoryId)}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const aspectsData = await aspectsRes.json();
    if (!aspectsRes.ok) return cors(new Response(JSON.stringify({ ok: false, error: 'getItemAspectsForCategory failed: ' + JSON.stringify(aspectsData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const aspects = (aspectsData.aspects || []).map(a => ({
      name: a.localizedAspectName,
      required: a.aspectConstraint ? a.aspectConstraint.aspectRequired === true : false,
      usableForVariations: a.aspectConstraint ? a.aspectConstraint.aspectEnabledForVariations === true : null,
      mode: a.aspectConstraint ? a.aspectConstraint.aspectMode : null,
      allowedValues: (a.aspectValues || []).map(v => v.localizedValue).slice(0, 20), // capped — some categories have hundreds
    }));
    const required = aspects.filter(a => a.required);

    return cors(new Response(JSON.stringify({
      ok: true, categoryId, requiredCount: required.length, required, allAspects: aspects,
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

async function ebayLocationCreate(request, env) {
  try {
    const body = await request.json().catch(() => ({}));
    const dryRun = body.dryRun === true;
    const merchantLocationKey = 'XFITTING_WAREHOUSE';

    const locationPayload = {
      location: {
        address: {
          addressLine1: '499 Bridgeton Pike',
          city: 'Mullica Hill',
          stateOrProvince: 'NJ',
          postalCode: '08062',
          country: 'US',
        },
      },
      locationTypes: ['WAREHOUSE'],
      name: 'XFitting Warehouse',
      merchantLocationStatus: 'ENABLED',
    };

    if (dryRun) {
      return cors(new Response(JSON.stringify({ ok: true, dryRun: true, merchantLocationKey, preview: locationPayload }), { headers: { 'Content-Type': 'application/json' } }));
    }

    const token = await getEbayToken(env);
    const res = await fetch(`https://api.ebay.com/sell/inventory/v1/location/${encodeURIComponent(merchantLocationKey)}`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(locationPayload),
    });
    if (res.status !== 204 && !res.ok) {
      const errData = await res.json().catch(() => ({}));
      return cors(new Response(JSON.stringify({ ok: false, error: 'Location creation failed: ' + JSON.stringify(errData) }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
    }

    return cors(new Response(JSON.stringify({ ok: true, merchantLocationKey, message: 'Inventory location created' }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

// GET /walmart/test-connection — read-only connectivity check, same
// pattern as ebayAccountDiscover: prove the credentials actually work
// before building anything that writes/creates listings.
// GET /walmart/check-version?version=... — safe, read-only check of
// whether this account's item spec accepts a given version, using the
// taxonomy endpoint (which requires a valid feedType+version to return
// anything useful). Built after repeated rounds of guessing item-field
// structure blind — lets the actual version be confirmed without
// risking another real feed submission each time.
// GET /walmart/catalog-search?upc=... — the actual missing step: checks
// whether this UPC already exists somewhere in Walmart's broader catalog
// (sold by another seller), which determines whether MP_ITEM (full new
// item setup — what's been submitted this whole time) or MP_ITEM_MATCH
// (link an offer to an existing catalog item) is actually correct.
// responseFormat=SPEC additionally returns the exact itemSpecPayload
// structure to use for whichever path applies — read-only, safe to call
// before submitting another real feed.
// POST /walmart/spreadsheet-data — Body: { baseSkus: [...] }
// Maps product_catalog rows to Walmart's exact field structure, confirmed
// directly from the real spec spreadsheet (omni-marketplace-en-external-
// 5_0_20260608-18_15_07.xlsx) — the frontend turns this JSON into an
// actual downloadable .xlsx matching that template exactly, for upload
// through Seller Center's UI (the path proven to work for this account,
// unlike the API route). One row per pack size, matching the same
// individual-listing convention as Amazon/eBay.
async function walmartSpreadsheetData(request, env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const body = await request.json().catch(() => ({}));
    const baseSkus = Array.isArray(body.baseSkus) ? body.baseSkus : [];
    if (!baseSkus.length) return cors(new Response(JSON.stringify({ ok: false, error: 'baseSkus array required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const rows = [];
    const skipped = [];
    for (const baseSku of baseSkus) {
      const catalogRows = await d1All(env, 'SELECT * FROM product_catalog WHERE base_sku=? ORDER BY pack_qty ASC', [baseSku.toUpperCase()]);
      if (!catalogRows.length) { skipped.push({ baseSku, reason: 'Not found in product_catalog' }); continue; }

      for (const row of catalogRows) {
        if (!row.upc) { skipped.push({ baseSku, sku: row.sku, reason: 'No UPC' }); continue; }
        // BUGFIX: confirmed via a real user report — this combined-OR
        // message required a follow-up round trip to find out which
        // specific field was actually missing. Checks each one
        // individually now and names exactly what's missing.
        const missing = [];
        if (!row.title_short) missing.push('title_short');
        if (!row.starting_price) missing.push('starting_price');
        if (!row.weight_lbs) missing.push('weight_lbs');
        if (!row.walmart_product_type) missing.push('walmart_product_type');
        if (missing.length) {
          skipped.push({ baseSku, sku: row.sku, reason: 'Missing: ' + missing.join(', ') });
          continue;
        }
        const bullets = [row.bullet_1, row.bullet_2, row.bullet_3, row.bullet_4].filter(Boolean); // template has 4 keyFeatures columns, not 5

        // MAJOR BUGFIX: confirmed via a real pasted-result cross-checked
        // against the actual template file — my very first reading of
        // this template (many messages ago) miscounted the column
        // offset. Data genuinely starts at column D (index 4, 1-indexed),
        // and previous versions only included ~21 of the real 93
        // columns, silently skipping required fields (Material, Has
        // Written Warranty, Net Content Unit/Measure) that sat BETWEEN
        // fields that were included — shifting everything after them
        // into the wrong column when pasted. Also reverted the GTIN-14
        // padding — the user confirmed this account's Product ID field
        // wants the plain 12-digit UPC, not a padded 14-digit GTIN.
        //
        // Uses an explicit column-number -> value map, placed into a
        // fixed 93-element array programmatically, rather than manually
        // counting blank placeholder strings — a first attempt at that
        // manual approach came out to 86 elements instead of 93,
        // exactly the kind of counting error this avoids entirely.
        function buildWalmartRow(fields) {
          const arr = new Array(93).fill('');
          for (const col in fields) arr[Number(col) - 4] = fields[col]; // column 4 in the real template = array index 0
          return arr;
        }
        const orderedRow = buildWalmartRow({
          4: row.sku, 5: row.walmart_product_type, 6: 'UPC', 7: row.upc, 8: row.title_short, 9: row.manufacturer || 'XFITTING',
          10: row.starting_price, 11: row.weight_lbs, 12: WALMART_DEFAULTS.countryOfOrigin, 13: 'New',
          14: WALMART_DEFAULTS.fulfillmentCenterID, 15: WALMART_DEFAULTS.quantity,
          17: row.description || '', 18: bullets[0] || '', 19: bullets[1] || '', 20: bullets[2] || '', 21: bullets[3] || '',
          // BUGFIX: confirmed via a real pasted result cross-checked
          // against the real template — the true order is Unit (Y),
          // Measure (Z), Material (AA). Previous version had Material
          // first, then Unit, then Measure — reversed from reality,
          // which is exactly why "Lead-Free Brass" showed up in the
          // Unit column, "Count" in Measure, and "1" in Material.
          22: row.image_url_1 || '', 23: 'No', 24: 'No', 25: 'Count', 26: 1, 27: row.material || '',
          61: row.walmart_product_type === 'Valves' ? (row.fitting_type || '') : '',
        });
        rows.push(orderedRow);
      }
    }

    if (!rows.length) return cors(new Response(JSON.stringify({ ok: false, error: 'No rows ready — check UPC, title_short, starting_price, weight_lbs, and walmart_product_type are all set', skipped }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    return cors(new Response(JSON.stringify({ ok: true, rowCount: rows.length, skipped, rows }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

async function walmartCatalogSearch(url, env) {
  try {
    const upc = url.searchParams.get('upc');
    if (!upc) return cors(new Response(JSON.stringify({ ok: false, error: 'upc parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getWalmartToken(env);

    const res = await fetch(`https://marketplace.walmartapis.com/v3/items/walmart/search?upc=${encodeURIComponent(upc)}&responseFormat=SPEC`, {
      headers: {
        'WM_SEC.ACCESS_TOKEN': token,
        'WM_QOS.CORRELATION_ID': crypto.randomUUID(),
        'WM_SVC.NAME': 'Walmart Marketplace',
        'Accept': 'application/json',
      },
    });
    const data = await res.json();
    if (!res.ok) return cors(new Response(JSON.stringify({ ok: false, error: 'Catalog search failed: HTTP ' + res.status, detail: data }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const item = (data.items || [])[0] || null;
    return cors(new Response(JSON.stringify({
      ok: true, upc,
      foundInWalmartCatalog: !!item,
      feedTypeToUse: item && item.itemSpecPayload ? item.itemSpecPayload.MPItemFeedHeader?.feedType || 'MP_ITEM_MATCH (found)' : 'MP_ITEM (not found)',
      rawResponse: data,
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

