async function ebayDebugOrders(env) {
  const ebayToken = await getEbayToken(env);
  const from = new Date(Date.now() - 30 * 86400000).toISOString();
  const to   = new Date().toISOString();
  const filter = `creationdate:[${from}..${to}]`;
  const r = await fetch(
    `https://api.ebay.com/sell/fulfillment/v1/order?filter=${encodeURIComponent(filter)}&limit=2`,
    { headers: { Authorization: `Bearer ${ebayToken}` } }
  );
  const data = await r.json().catch(() => ({}));
  const firstOrder = data.orders?.[0];
  const firstLine  = firstOrder?.lineItems?.[0];
  return cors(new Response(JSON.stringify({
    totalOrders: data.total || 0,
    sampleLine:  firstLine ? { keys: Object.keys(firstLine), legacyItemId: firstLine.legacyItemId, sku: firstLine.sku, title: firstLine.title, quantity: firstLine.quantity } : null,
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// ══════════════════════════════════════════════════════════════════════════════
// REPRICER WRITE FUNCTIONS
// ══════════════════════════════════════════════════════════════════════════════

// ── AI price verdict ────────────────────────────────────────────────────
async function aiPriceVerdict(env, ctx) {
  // ctx: { sku, itemId, packQty, cog1pc, floor, target, oldPrice, newPrice, pct,
  //        sales90, lowestComp, notes }
  const FLOOR_GRACE = 0.05; // allow up to 5% below floor
  const { cog1pc, floor, oldPrice, newPrice, pct, sales90, lowestComp } = ctx;

  // Hard block — more than 5% below floor
  const hardFloor = floor * (1 - FLOOR_GRACE);
  if (newPrice < hardFloor) {
    return { verdict: 'block', reason: `Price $${newPrice.toFixed(2)} is more than 5% below floor ($${floor.toFixed(2)}). Hard block — cannot proceed.` };
  }

  // Auto-approve <10% changes (handled before AI is called, but safety net)
  if (pct <= 0.10) {
    return { verdict: 'approve', reason: 'Change is within 10% auto-approve threshold.' };
  }

  // Build rules context for AI
  const isSlow      = sales90 < 3;
  const belowFloor  = newPrice < floor;
  const aboveTarget = newPrice >= ctx.target;
  const compJustified = lowestComp > 0 && newPrice <= lowestComp;
  const bigDrop     = pct > 0.25;
  const isPriceRise = ctx.newPrice > ctx.oldPrice;

  // Rule-based fast paths before calling AI
  if (isPriceRise && pct > 0.10) {
    // Always queue price increases >10% — AI shouldn't auto-raise
    return { verdict: 'queue', reason: `Price increase of ${(pct*100).toFixed(1)}% requires management review.` };
  }
  if (bigDrop && !isSlow) {
    return { verdict: 'queue', reason: `Drop of ${(pct*100).toFixed(1)}% on a fast-moving item (${sales90} sales/90d) requires management review.` };
  }
  if (!lowestComp && belowFloor) {
    return { verdict: 'queue', reason: `No competitor data provided and price is below floor. Management review required.` };
  }

  // Call Claude for nuanced cases
  const prompt = `You are a pricing analyst for an eBay reseller. Evaluate this price change request and respond with ONLY a JSON object.

Item context:
- SKU: ${ctx.sku}
- Pack qty: ${ctx.packQty}
- Cost per piece: $${cog1pc.toFixed(2)}
- Floor price (40% margin + shipping): $${floor.toFixed(2)}
- Target price (75% margin + shipping): $${ctx.target.toFixed(2)}
- Current price: $${oldPrice.toFixed(2)}
- Proposed price: $${newPrice.toFixed(2)}
- Change: ${(pct*100).toFixed(1)}% ${isPriceRise ? 'increase' : 'decrease'}
- Sales last 90 days: ${sales90} units
- Lowest competitor price: ${lowestComp ? '$'+lowestComp.toFixed(2) : 'not provided'}
- Below floor: ${belowFloor ? 'YES (within 5% grace)' : 'no'}
- Notes from employee: ${ctx.notes || 'none'}

Business rules:
- Slow mover = fewer than 3 sales in 90 days. Slow movers get more pricing flexibility.
- If competitor is lower than us and item is slow, dropping price is generally justified.
- Never auto-approve if competitor data is missing and price drops below floor.
- Never auto-approve price increases >10%.
- Never auto-approve drops >25% on fast movers.
- Price in floor-5% band (competitive window) is allowed but needs justification.

Respond ONLY with this JSON (no markdown, no explanation outside JSON):
{"verdict":"approve|queue","reason":"one sentence plain English explanation","confidence":0.0-1.0}`;

  try {
    const aiResp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': env.ANTHROPIC_KEY || env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 200,
        messages: [{ role: 'user', content: prompt }]
      })
    });
    const aiData = await aiResp.json();
    const text   = aiData.content?.[0]?.text || '';
    const parsed = JSON.parse(text.replace(/```json|```/g, '').trim());
    return { verdict: parsed.verdict, reason: parsed.reason, confidence: parsed.confidence, ai: true };
  } catch(e) {
    // AI failed — default to queue for safety
    return { verdict: 'queue', reason: 'AI analysis unavailable — queued for manual review.', ai: false };
  }
}

async function repricerPriceChange(request, env) {
  const SHIPPING = 5.25;
  const body = await request.json();
  const { sku, itemId, packQty, cog1pc, floor, target, oldPrice, newPrice, lowestComp, notes, user } = body;

  // Price-change PIN step-up check removed - the request is already
  // authenticated via the shared credential session gate, confirmed
  // sufficient by the user rather than keeping a redundant second factor.

  const old_  = parseFloat(oldPrice) || 0;
  const new_  = parseFloat(newPrice) || 0;
  const pct   = old_ > 0 ? Math.abs((new_ - old_) / old_) : 1;
  const stamp = new Date().toISOString().slice(0, 10);
  const ts    = new Date().toISOString().replace('T',' ').slice(0,19);
  let status = 'Pending', result = '', verdict = 'queue', reason = '';

  // ── <10%: auto-approve, apply immediately ───────────────────────────
  if (pct <= 0.10) {
    try {
      const r   = await ebayUpdatePrice({ json: async () => ({ itemId, newPrice: new_ }) }, env);
      const res = await r.clone().json();
      status = res.success ? 'Applied' : 'Failed';
      result = res.error || 'OK';
      verdict = 'approve';
      reason  = 'Within 10% auto-approve threshold.';
    } catch(e) { status = 'Failed'; result = e.message; }

  } else {
    // ── >10%: get sales velocity then AI verdict ─────────────────────
    let sales90 = 0;
    try {
      // Inline velocity lookup — resolve SKU then read eBay_Sales_90d
      let targetBase = (sku||'').includes('=') ? sku.split('=')[0].trim() : (sku||'').trim();
      if (!targetBase && itemId) {
        const cache = await rSheetGet(env, 'eBay_Listings!A2:B2000').catch(() => ({ values: [] }));
        const row   = (cache.values || []).find(r => String(r[0]).trim() === String(itemId));
        if (row?.[1]) { const s = row[1]; targetBase = s.includes('=') ? s.split('=')[0].trim() : s.trim(); }
      }
      if (targetBase) {
        const r90 = await rSheetGet(env, 'eBay_Sales_90d!A2:G3000').catch(() => ({ values: [] }));
        for (const row of (r90.values || [])) {
          if (String(row[0]).trim() === String(itemId) || String(row[1]).trim() === targetBase) {
            sales90 = parseInt(row[3]) || parseInt(row[2]) || 0;
            break;
          }
        }
      }
    } catch(_) {}

    const floorNum  = parseFloat(floor)  || 0;
    const targetNum = parseFloat(target) || 0;
    const compNum   = parseFloat(lowestComp) || 0;

    const ai = await aiPriceVerdict(env, {
      sku, itemId, packQty: parseInt(packQty)||1,
      cog1pc: parseFloat(cog1pc)||0,
      floor: floorNum, target: targetNum,
      oldPrice: old_, newPrice: new_, pct,
      sales90, lowestComp: compNum, notes
    });

    verdict = ai.verdict;
    reason  = ai.reason;

    if (verdict === 'approve') {
      // AI approved — apply to eBay
      try {
        const r   = await ebayUpdatePrice({ json: async () => ({ itemId, newPrice: new_ }) }, env);
        const res = await r.clone().json();
        status = res.success ? 'Applied' : 'Failed';
        result = res.error || 'OK';
      } catch(e) { status = 'Failed'; result = e.message; }
    } else if (verdict === 'block') {
      status = 'Blocked';
      result = reason;
    } else {
      // Queue for management approval
      status = 'Queued';
      result = reason;
      await rSheetAppend(env, 'Approval_Queue!A:L', [[
        ts, itemId||'', sku||'', parseInt(packQty)||1,
        old_, new_, +( pct*100).toFixed(1)+'%',
        sales90, compNum||'', reason, user||'', 'Pending'
      ]]);
    }
  }

  // Audit log — every attempt
  await rSheetAppend(env, 'Price_History!A:K', [[stamp, user||'', sku||'', itemId||'', packQty||'', old_, new_, +( pct*100).toFixed(1)+'%', status, result, notes||'']]);

  // Clean log — applied only
  if (status === 'Applied') {
    await rSheetAppend(env, 'Price_Changes!A:E', [[ts, itemId||'', old_, new_, user||'']]);
  }

  return cors(new Response(JSON.stringify({
    success: true, status, verdict, reason,
    pct: +(pct*100).toFixed(1), result
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── Queue GET — read pending approvals ───────────────────────────────────
async function repricerQueueGet(url, env) {
  const data = await rSheetGet(env, 'Approval_Queue!A2:L500');
  const rows = (data.values || []).filter(r => r[0]);
  const items = rows.map((r, i) => ({
    rowIndex: i + 2,
    timestamp: r[0],  itemId:   r[1],  sku:      r[2],
    packQty:   r[3],  oldPrice: parseFloat(r[4])||0,
    newPrice:  parseFloat(r[5])||0,  pct: r[6],
    sales90:   r[7],  lowestComp: r[8], reason: r[9],
    user:      r[10], status: r[11] || 'Pending'
  })).filter(r => r.status === 'Pending');
  return cors(new Response(JSON.stringify({ queue: items, total: items.length }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── Queue action — approve or deny ───────────────────────────────────────
async function repricerQueueAction(request, env) {
  const body = await request.json();
  const { rowIndex, action, itemId, newPrice, user } = body; // action: 'approve'|'deny'
  if (!['approve','deny'].includes(action)) {
    return cors(new Response(JSON.stringify({ error: 'Invalid action' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }

  let applied = false, errorMsg = '';
  if (action === 'approve') {
    try {
      const r   = await ebayUpdatePrice({ json: async () => ({ itemId, newPrice: parseFloat(newPrice) }) }, env);
      const res = await r.clone().json();
      applied   = res.success;
      errorMsg  = res.error || '';
    } catch(e) { errorMsg = e.message; }
  }

  // Update status in sheet — column L (index 12) = status, col M = actioned by
  const newStatus = action === 'approve' ? (applied ? 'Approved+Applied' : 'Approve-Failed') : 'Denied';
  const ts = new Date().toISOString().replace('T',' ').slice(0,19);
  await rSheetUpdate(env, 'Approval_Queue!L' + rowIndex + ':N' + rowIndex, [[newStatus, user||'mgmt', ts]]);

  // Log to Price_Changes if applied
  if (applied) {
    await rSheetAppend(env, 'Price_Changes!A:E', [[ts, itemId||'', '', parseFloat(newPrice), user||'mgmt']]);
  }

  return cors(new Response(JSON.stringify({ success: true, status: newStatus, applied }), { headers: { 'Content-Type': 'application/json' } }));
}


// ── Auto-reprice: correct a chunk of listings to floor × 1.02 ────────────
// Caller passes an explicit list of {itemId, offerId, sku, price, packQty, cog1pc}
// Worker just processes that list — no sheet scan needed (app already filtered)
async function repricerAutoReprice(request, env) {
  const body = await request.json();
  const { user, listings } = body;

  // Price-change PIN step-up check removed - same reasoning as
  // repricerPriceChange above.

  if (!Array.isArray(listings) || !listings.length) {
    return cors(new Response(JSON.stringify({ error: 'No listings provided' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }

  const SHIPPING    = 5.25;
  const ABOVE_FLOOR = 1.02;
  const results     = { applied: [], skipped: [], failed: [] };
  const ts          = new Date().toISOString().replace('T', ' ').slice(0, 19);
  const stamp       = ts.slice(0, 10);

  // Process up to 20 listings — run 5 in parallel for speed
  const chunk = listings.slice(0, 20);

  async function processOne(l) {
    const { itemId, offerId, sku, price, packQty, cog1pc } = l;
    if (!cog1pc || !price) {
      results.skipped.push({ itemId, sku, reason: 'Missing COGS or price' });
      return;
    }
    const floor    = (cog1pc * packQty * 1.40) + SHIPPING;
    const newPrice = +(floor * ABOVE_FLOOR).toFixed(2);
    const pct      = Math.abs((newPrice - price) / price);

    if (price >= floor) {
      results.skipped.push({ itemId, sku, reason: 'Already at or above floor' });
      return;
    }
    if (pct > 0.10) {
      results.skipped.push({ itemId, sku, price, newPrice, reason: `Correction ${(pct*100).toFixed(1)}% exceeds 10% auto limit` });
      return;
    }

    try {
      const r   = await ebayUpdatePrice({ json: async () => ({ itemId: offerId || itemId, newPrice }) }, env);
      const res = await r.clone().json();
      if (res.success) {
        results.applied.push({ itemId, sku, oldPrice: price, newPrice, pct: +(pct*100).toFixed(1) });
        await rSheetAppend(env, 'Price_History!A:K', [[stamp, user||'AUTO', sku, itemId, packQty, price, newPrice, +(pct*100).toFixed(1)+'%', 'Applied', 'Auto-reprice', '']]);
        await rSheetAppend(env, 'Price_Changes!A:E',  [[ts, itemId, price, newPrice, user||'AUTO']]);
      } else {
        results.failed.push({ itemId, sku, reason: res.error || 'eBay update failed' });
      }
    } catch(e) {
      results.failed.push({ itemId, sku, reason: e.message });
    }
  }

  // Process in batches of 5 concurrent
  for (let i = 0; i < chunk.length; i += 5) {
    await Promise.all(chunk.slice(i, i + 5).map(processOne));
  }

  return cors(new Response(JSON.stringify({
    success: true,
    applied: results.applied.length,
    skipped: results.skipped.length,
    failed:  results.failed.length,
    details: results
  }), { headers: { 'Content-Type': 'application/json' } }));
}


async function repricerPriceHistory(url, env) {
  const sku    = url.searchParams.get('sku');
  const itemId = url.searchParams.get('itemId');
  const limit  = parseInt(url.searchParams.get('limit') || '100');
  const data   = await rSheetGet(env, 'Price_Changes!A2:E500');
  let rows     = (data.values || []).filter(r => r[0]);
  if (sku)    rows = rows.filter(r => r[2] === sku);
  if (itemId) rows = rows.filter(r => String(r[3]).includes(itemId));
  const parsed = rows.slice(-limit).reverse().map(r => ({
    date: r[0], itemId: r[1],
    oldPrice: parseFloat(r[2])||0, newPrice: parseFloat(r[3])||0,
    user: r[4],
  }));
  return cors(new Response(JSON.stringify({ history: parsed, total: parsed.length }), { headers: { 'Content-Type': 'application/json' } }));
}

async function repricerSaveResearch(request, env) {
  const body = await request.json();
  const { itemId, sku, packQty, ourPrice, ourRank, lowestComp, competitors=[], trend, s30, s90, s6m, s1y, notes, initials } = body;
  const stamp     = new Date().toISOString().slice(0, 10);
  const baseSku   = (sku||'').includes('=') ? sku.split('=')[0].trim() : (sku||'').trim();
  const ourUnit   = packQty > 1 ? +(ourPrice / packQty).toFixed(2) : ourPrice;
  const compPrice = lowestComp || (competitors[0]?.price) || 0;
  const compPack  = competitors[0]?.packQty || packQty;
  const compUnit  = compPack > 1 ? +(compPrice / compPack).toFixed(2) : compPrice;
  const compStr   = competitors.map(c => `${c.title||''}: $${c.price} [${c.url||''}]`).join(' | ');

  // Write summary row to MARKET_RESEARCH
  const summaryRow = [stamp, itemId||'', baseSku, packQty||1, ourPrice||0, ourUnit, compPack, compPrice, compUnit, ourRank||'', trend||'', s30||0, s90||0, s6m||0, s1y||0, '', '', compStr, notes||'', initials||''];
  await rSheetAppend(env, 'MARKET_RESEARCH!A:T', [summaryRow]);

  // Write detail rows to Price_Research_Log (one row per competitor)
  if (competitors.length) {
    const detailRows = competitors.map(c => [stamp, itemId||'', baseSku, packQty||1, ourPrice||0, ourRank||'', c.rank||'', c.title||'', c.price||0, c.packQty||1, c.unitPrice||0, c.seller||'', c.url||'', notes||'', initials||'']);
    await rSheetAppend(env, 'Price_Research_Log!A:O', detailRows);
  }

  return cors(new Response(JSON.stringify({ success: true }), { headers: { 'Content-Type': 'application/json' } }));
}

