// ── POST /inventory/pull-batch/claim (whole batch) ───────────────────────
async function inventoryPullBatchClaim(request, env) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const { id, claimedBy } = b;
  if (!id) return cors(new Response(JSON.stringify({ ok: false, error: 'id required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  const row = await d1First(env, `SELECT * FROM inventory_pull_batch WHERE id = ?`, [id]);
  if (!row) return cors(new Response(JSON.stringify({ ok: false, error: 'Batch not found' }), { status: 404, headers: { 'Content-Type': 'application/json' } }));
  if (row.status !== 'open') return cors(new Response(JSON.stringify({ ok: false, error: 'Already ' + row.status }), { status: 409, headers: { 'Content-Type': 'application/json' } }));
  const ts = new Date().toISOString();
  await env.DB.prepare(`UPDATE inventory_pull_batch SET status='claimed', claimed_by=?, claimed_at=? WHERE id=?`)
    .bind(claimedBy || '', ts, id).run();
  let items = [];
  try { items = JSON.parse(row.items || '[]'); } catch (e) {}
  items = items.map(it => Object.assign({}, it, { _batchSavedBy: row.saved_by || '', _batchSavedAt: row.saved_at || '' }));
  return cors(new Response(JSON.stringify({ ok: true, items, savedBy: row.saved_by || '', savedAt: row.saved_at || '' }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── POST /inventory/pull-batch/remove (whole batch) ───────────────────────
async function inventoryPullBatchRemove(request, env) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const { id, removedBy } = b;
  if (!id) return cors(new Response(JSON.stringify({ ok: false, error: 'id required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  const row = await d1First(env, `SELECT * FROM inventory_pull_batch WHERE id = ?`, [id]);
  if (!row) return cors(new Response(JSON.stringify({ ok: false, error: 'Batch not found' }), { status: 404, headers: { 'Content-Type': 'application/json' } }));
  if (row.status !== 'open') return cors(new Response(JSON.stringify({ ok: false, error: 'Already ' + row.status }), { status: 409, headers: { 'Content-Type': 'application/json' } }));
  const ts = new Date().toISOString();
  await env.DB.prepare(`UPDATE inventory_pull_batch SET status='removed', removed_by=?, removed_at=? WHERE id=?`)
    .bind(removedBy || '', ts, id).run();
  return cors(new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } }));
}

// Shared by claim-items and remove-items below — both just pull specific
// {batchId, key} picks out of whichever open batches they belong to (a
// picker may only want SOME items out of a batch that spans several SKUs),
// grouped by batch so each batch touched needs only one read + one write
// even when multiple of its items were picked at once. They differ only in
// what happens to the picked items afterward (handed back to the caller vs
// simply discarded) and which status/actor a batch gets once fully emptied
// — passed in as emptyStatus/actorBy rather than duplicating this loop
// twice. A batchId that's already claimed/removed/gone by the time this
// runs is silently skipped (not an error for the whole request) — someone
// else on another device may have just resumed or discarded it first.
async function _invPullBatchExtractItems(env, picks, emptyStatus, actorBy) {
  const ts = new Date().toISOString();
  const byField = emptyStatus === 'claimed' ? 'claimed_by' : 'removed_by';
  const atField  = emptyStatus === 'claimed' ? 'claimed_at' : 'removed_at';
  const byBatch = {};
  for (const p of picks) {
    const bid = parseInt(p && p.batchId, 10);
    if (!bid) continue;
    if (!byBatch[bid]) byBatch[bid] = new Set();
    byBatch[bid].add(String(p.key));
  }
  const extracted = [];
  for (const bidStr of Object.keys(byBatch)) {
    const bid = parseInt(bidStr, 10);
    const row = await d1First(env, `SELECT * FROM inventory_pull_batch WHERE id = ? AND status = 'open'`, [bid]);
    if (!row) continue;
    let items = [];
    try { items = JSON.parse(row.items || '[]'); } catch (e) {}
    const wantKeys = byBatch[bid];
    const keep = [];
    items.forEach(it => {
      if (wantKeys.has(String(it.key))) {
        extracted.push(Object.assign({}, it, { _batchSavedBy: row.saved_by || '', _batchSavedAt: row.saved_at || '' }));
      } else {
        keep.push(it);
      }
    });
    if (keep.length === items.length) continue; // none of this batch's items actually matched — nothing to write
    if (keep.length === 0) {
      await env.DB.prepare(`UPDATE inventory_pull_batch SET status=?, items=?, item_count=0, ${byField}=?, ${atField}=? WHERE id=?`)
        .bind(emptyStatus, JSON.stringify(keep), actorBy || '', ts, bid).run();
    } else {
      await env.DB.prepare(`UPDATE inventory_pull_batch SET items=?, item_count=? WHERE id=?`)
        .bind(JSON.stringify(keep), keep.length, bid).run();
    }
  }
  return extracted;
}

// ── POST /inventory/pull-batch/claim-items (item-level resume) ───────────
async function inventoryPullBatchClaimItems(request, env) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const picks = Array.isArray(b.items) ? b.items : [];
  if (!picks.length) return cors(new Response(JSON.stringify({ ok: false, error: 'items required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  const items = await _invPullBatchExtractItems(env, picks, 'claimed', b.claimedBy);
  return cors(new Response(JSON.stringify({ ok: true, items }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── POST /inventory/pull-batch/remove-items (item-level discard) ─────────
async function inventoryPullBatchRemoveItems(request, env) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const picks = Array.isArray(b.items) ? b.items : [];
  if (!picks.length) return cors(new Response(JSON.stringify({ ok: false, error: 'items required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  const items = await _invPullBatchExtractItems(env, picks, 'removed', b.removedBy);
  return cors(new Response(JSON.stringify({ ok: true, removedCount: items.length }), { headers: { 'Content-Type': 'application/json' } }));
}

