// ── USPS drop-off runs ────────────────────────────────────────────────────────
// POST /ship/usps-run/start  { name }               -> { ok, id, leftAt }
// POST /ship/usps-run/end    { id }                 -> { ok, returnedAt }
// GET  /ship/usps-run/open                          -> { ok, open: [{id,name,leftAt}] }
// Writable by anyone with a valid Pack & Ship session (same access as
// scanning/batch-close) — the reporting/admin restriction the person
// asked for applies to VIEWING the full log, not to logging a run, since
// whoever's at the packing station in the moment is who presses this.

async function shipUspsRunStart(request, env, session) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const name = (b.name || '').trim();
  if (!name) return cors(new Response(JSON.stringify({ ok: false, error: 'Name required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  const date = shipTodayKey();
  const ts   = new Date().toISOString();
  const loggedInBy = (session && session.userId) ? String(session.userId) : '';
  const inserted = await env.DB.prepare(
    `INSERT INTO ship_usps_run_log (date, name, left_at, returned_at, logged_in_by) VALUES (?, ?, ?, NULL, ?)`
  ).bind(date, name, ts, loggedInBy).run();
  return cors(new Response(JSON.stringify({ ok: true, id: inserted.meta.last_row_id, name, leftAt: ts }), { headers: { 'Content-Type': 'application/json' } }));
}

async function shipUspsRunEnd(request, env) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const id = parseInt(b.id);
  if (!id) return cors(new Response(JSON.stringify({ ok: false, error: 'id required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  const row = await env.DB.prepare(`SELECT * FROM ship_usps_run_log WHERE id = ?`).bind(id).first();
  if (!row) return cors(new Response(JSON.stringify({ ok: false, error: 'Run not found' }), { status: 404, headers: { 'Content-Type': 'application/json' } }));
  if (row.returned_at) return cors(new Response(JSON.stringify({ ok: true, returnedAt: row.returned_at }), { headers: { 'Content-Type': 'application/json' } }));
  const ts = new Date().toISOString();
  await env.DB.prepare(`UPDATE ship_usps_run_log SET returned_at = ? WHERE id = ?`).bind(ts, id).run();
  return cors(new Response(JSON.stringify({ ok: true, returnedAt: ts }), { headers: { 'Content-Type': 'application/json' } }));
}

async function shipUspsRunOpen(env) {
  await ensureShipD1Tables(env);
  // Not date-scoped on purpose — a run that started before midnight and
  // hasn't been closed out yet should still show as open, rather than
  // silently vanishing off "today"'s list.
  const rows = (await env.DB.prepare(
    `SELECT id, name, left_at FROM ship_usps_run_log WHERE returned_at IS NULL ORDER BY left_at ASC`
  ).all()).results || [];
  return cors(new Response(JSON.stringify({
    ok: true, open: rows.map(r => ({ id: r.id, name: r.name, leftAt: r.left_at }))
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// GET /ship/usps-runs?days=30 — same paired-trip report as adminGetUspsRuns
// below, but reachable from Pack & Ship directly (behind its own in-app
// admin-role gate) instead of routing through the separate Admin app. Gated
// here explicitly with session.roles, since this sits under /ship/* rather
// than /admin/* — it doesn't get the dispatcher's built-in admin-only check.
async function shipUspsRunsReport(url, env, session) {
  if (!session || !session.roles || !session.roles.includes('admin')) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Admin access required' }), {
      status: 403, headers: { 'Content-Type': 'application/json' }
    }));
  }
  await ensureShipD1Tables(env);
  const days  = parseInt(url.searchParams.get('days')) || 30;
  const since = new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);
  const rows = (await env.DB.prepare(
    `SELECT * FROM ship_usps_run_log WHERE date >= ? ORDER BY left_at DESC LIMIT 500`
  ).bind(since).all()).results || [];
  const runs = rows.map(r => {
    const leftMs = new Date(r.left_at).getTime();
    const retMs  = r.returned_at ? new Date(r.returned_at).getTime() : null;
    return {
      id: r.id, date: r.date, name: r.name,
      leftAt: r.left_at, returnedAt: r.returned_at || null,
      durationMin: retMs ? Math.round((retMs - leftMs) / 60000) : null,
      loggedInBy: r.logged_in_by || '',
    };
  });
  return cors(new Response(JSON.stringify({ ok: true, runs }), { headers: { 'Content-Type': 'application/json' } }));
}

// GET /admin/usps-runs?days=30 — full log for the Admin app's report,
// paired into one row per trip (left + returned + duration) rather than
// the raw generic activity feed, since that's a much more useful shape
// for "who dropped off, when did they leave, when were they back".
async function adminGetUspsRuns(url, env) {
  await ensureShipD1Tables(env);
  const days  = parseInt(url.searchParams.get('days')) || 30;
  const since = new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);
  const rows = (await env.DB.prepare(
    `SELECT * FROM ship_usps_run_log WHERE date >= ? ORDER BY left_at DESC LIMIT 500`
  ).bind(since).all()).results || [];
  const runs = rows.map(r => {
    const leftMs = new Date(r.left_at).getTime();
    const retMs  = r.returned_at ? new Date(r.returned_at).getTime() : null;
    return {
      id: r.id, date: r.date, name: r.name,
      leftAt: r.left_at, returnedAt: r.returned_at || null,
      durationMin: retMs ? Math.round((retMs - leftMs) / 60000) : null,
      loggedInBy: r.logged_in_by || '',
    };
  });
  return cors(new Response(JSON.stringify({ ok: true, runs }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── POST /ship/batch-close ────────────────────────────────────────────────────

async function shipBatchClose(request, env) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const { carrier, initials, date: reqDate } = b;
  const date = reqDate || shipTodayKey();
  const ts   = new Date().toISOString();

  if (!carrier) return cors(new Response(JSON.stringify({ error: 'carrier required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

  const result = await env.DB.prepare(
    `UPDATE ship_scan_log SET batch_closed_at = ? WHERE date = ? AND carrier = ? AND (batch_closed_at = '' OR batch_closed_at IS NULL)`
  ).bind(ts, date, carrier).run();

  return cors(new Response(JSON.stringify({
    ok: true, carrier, date, closedAt: ts, updated: result.meta.changes || 0,
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── POST /ship/manifest ───────────────────────────────────────────────────────

async function shipUploadManifest(request, env) {
  await ensureShipD1Tables(env);
  const b = await request.json().catch(() => ({}));
  const { rows, uploadedBy, date: reqDate } = b;
  const date = reqDate || shipTodayKey();

  if (!Array.isArray(rows) || rows.length === 0) {
    return cors(new Response(JSON.stringify({ error: 'rows array required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }

  // Overwrite behavior: delete today's existing rows first, matching the
  // prior Sheets implementation's replace semantics. Genuinely simpler in
  // D1 than the old clear-then-rewrite-whole-sheet approach.
  const existingCount = (await env.DB.prepare(`SELECT COUNT(*) as c FROM ship_manifest_log WHERE date = ?`).bind(date).first()).c;
  if (existingCount > 0) {
    await env.DB.prepare(`DELETE FROM ship_manifest_log WHERE date = ?`).bind(date).run();
  }

  const stmts = rows.map(r => env.DB.prepare(
    `INSERT INTO ship_manifest_log (date, tracking, order_num, channel, carrier, service, ship_to_state, uploaded_by, reconcile_status)
     VALUES (?,?,?,?,?,?,?,?,'Pending')`
  ).bind(
    date, (r.tracking || '').trim().toUpperCase(), (r.orderNum || '').trim(),
    (r.channel || '').trim(), detectShipCarrier(r.tracking), (r.service || '').trim(),
    (r.shipToState || '').trim(), (uploadedBy || '').trim().toUpperCase()
  ));
  for (let i = 0; i < stmts.length; i += 100) { await env.DB.batch(stmts.slice(i, i+100)); }

  return cors(new Response(JSON.stringify({
    ok: true, date, uploaded: stmts.length,
    replaced: existingCount > 0
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── GET /ship/manifest?date= ──────────────────────────────────────────────────

async function shipGetManifest(url, env) {
  await ensureShipD1Tables(env);
  const date = url.searchParams.get('date') || shipTodayKey();
  const result = await env.DB.prepare(`SELECT * FROM ship_manifest_log WHERE date = ? ORDER BY id ASC`).bind(date).all();
  const rows = (result.results || []).map(r => ({
    date: r.date||'', tracking: r.tracking||'', orderNum: r.order_num||'',
    channel: r.channel||'', carrier: r.carrier||'', service: r.service||'',
    shipToState: r.ship_to_state||'', uploadedBy: r.uploaded_by||'', reconcileStatus: r.reconcile_status||'',
  }));
  return cors(new Response(JSON.stringify({ date, manifest: rows, count: rows.length }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── POST /ship/reconcile ──────────────────────────────────────────────────────

async function shipReconcile(request, env) {
  await ensureShipD1Tables(env);
  const b    = await request.json().catch(() => ({}));
  const date = b.date || shipTodayKey();

  const [scanRows, manifestRows] = await Promise.all([
    env.DB.prepare(`SELECT tracking FROM ship_scan_log WHERE date = ? AND tracking != ''`).bind(date).all(),
    env.DB.prepare(`SELECT * FROM ship_manifest_log WHERE date = ?`).bind(date).all(),
  ]);

  const scannedSet = new Set((scanRows.results || []).map(r => (r.tracking || '').trim().toUpperCase()));

  const results = { scanned: 0, gap: 0, total: 0 };
  const updates = [];

  for (const r of (manifestRows.results || [])) {
    results.total++;
    const tracking  = (r.tracking || '').trim().toUpperCase();
    const isScanned = scannedSet.has(tracking);
    const newStatus = isScanned ? 'Scanned' : 'Gap';
    if (isScanned) results.scanned++; else results.gap++;
    if ((r.reconcile_status || '') !== newStatus) {
      updates.push(env.DB.prepare(`UPDATE ship_manifest_log SET reconcile_status = ? WHERE id = ?`).bind(newStatus, r.id));
    }
  }
  if (updates.length > 0) { for (let i = 0; i < updates.length; i += 100) { await env.DB.batch(updates.slice(i, i+100)); } }

  const gapList = (manifestRows.results || [])
    .filter(r => !scannedSet.has((r.tracking || '').trim().toUpperCase()))
    .map(r => ({
      tracking: (r.tracking || '').trim().toUpperCase(),
      orderNum: r.order_num || '', channel: r.channel || '',
      carrier:  r.carrier   || '', service: r.service || '', shipToState: r.ship_to_state || '',
    }));

  return cors(new Response(JSON.stringify({
    ok: true, date, results, gaps: gapList, updated: updates.length,
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── GET /ship/label-gap-report?date= ──────────────────────────────────────────
// Confirmed with the user: every label should ideally hit all three logs
// (Manifest, Print, Scan). Manifest+Scan without Print is explicitly OK -
// print logging can legitimately miss a real print. The real, flagged
// gap is Manifest+Print with NO Scan - a label got printed but the
// package was never actually confirmed shipped. Manifest-only (never
// printed or scanned) is also flagged - never even attempted. Scan
// without Manifest is a rare edge case (only possible if the Veeqo
// lookup failed during that scan, since a successful scan always
// upserts a manifest row) - surfaced separately since it points at a
// different kind of problem than a shipping gap.
async function shipLabelGapReport(url, env) {
  await ensureShipD1Tables(env);
  const date = url.searchParams.get('date') || shipTodayKey();

  const [manifestRes, printRes, scanRes] = await Promise.all([
    env.DB.prepare(`SELECT * FROM ship_manifest_log WHERE date = ?`).bind(date).all(),
    env.DB.prepare(`SELECT DISTINCT UPPER(tracking) as t FROM ship_print_log WHERE date = ?`).bind(date).all(),
    env.DB.prepare(`SELECT DISTINCT UPPER(tracking) as t FROM ship_scan_log WHERE date = ?`).bind(date).all(),
  ]);

  const manifestRows = manifestRes.results || [];
  const printedSet   = new Set((printRes.results || []).map(r => r.t));
  const scannedSet   = new Set((scanRes.results   || []).map(r => r.t));
  const manifestSet  = new Set(manifestRows.map(r => (r.tracking||'').trim().toUpperCase()));

  const summary = { complete: 0, okNoPrint: 0, flaggedPrintNoScan: 0, flaggedManifestOnly: 0 };
  const flagged = [];
  const allRows = [];

  for (const r of manifestRows) {
    const t = (r.tracking || '').trim().toUpperCase();
    const inPrint = printedSet.has(t);
    const inScan  = scannedSet.has(t);
    let status;
    if (inPrint && inScan)       { status = 'complete';              summary.complete++; }
    else if (!inPrint && inScan) { status = 'ok_no_print';            summary.okNoPrint++; }
    else if (inPrint && !inScan) { status = 'flagged_print_no_scan';  summary.flaggedPrintNoScan++; }
    else                         { status = 'flagged_manifest_only';  summary.flaggedManifestOnly++; }

    const row = {
      tracking: t, orderNum: r.order_num||'', customerName: r.customer_name||'',
      channel: r.channel||'', carrier: r.carrier||'',
      inManifest: true, inPrint, inScan, status,
    };
    allRows.push(row);
    if (status === 'flagged_print_no_scan' || status === 'flagged_manifest_only') flagged.push(row);
  }

  // Scanned but never in Manifest at all - only possible if the Veeqo
  // lookup failed during that scan (a successful scan always upserts a
  // manifest row). Different problem than a shipping gap, worth its
  // own bucket rather than mixing into the flagged list above.
  const scanWithoutManifest = [...scannedSet].filter(t => !manifestSet.has(t));

  return cors(new Response(JSON.stringify({
    ok: true, date, summary,
    totalManifested: manifestRows.length,
    flagged,
    scanWithoutManifest,
    all: allRows,
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── GET /veeqo/debug-tracking?tracking= ───────────────────────────────────────
// Diagnostic only - shows exactly what the undelivered report sees for one
// specific tracking number: which shipment_id it resolves (and from where -
// cached in Scan_Log, or a live order lookup), then the RAW, unprocessed
// Veeqo tracking-events response. Built specifically because the
// undelivered report can show 0 lookup failures yet still report
// something as undelivered that shouldn't be - this shows the real data
// so that can actually be diagnosed instead of guessed at again.
async function veeqoDebugTracking(url, env) {
  if (!env.VEEQO_API_KEY) return cors(new Response(JSON.stringify({ ok: false, error: 'VEEQO_API_KEY not set' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  await ensureShipD1Tables(env);
  const tracking = (url.searchParams.get('tracking') || '').trim().toUpperCase();
  if (!tracking) return cors(new Response(JSON.stringify({ ok: false, error: 'tracking required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

  const result = { tracking };

  // Step 1: is there a cached shipment_id from Scan_Log?
  const scanRow = await env.DB.prepare(`SELECT shipment_id, carrier FROM ship_scan_log WHERE UPPER(tracking) = ? AND shipment_id != '' LIMIT 1`).bind(tracking).first();
  result.cachedShipmentId = scanRow ? scanRow.shipment_id : null;
  result.cachedCarrier = scanRow ? scanRow.carrier : null;

  let shipmentId = result.cachedShipmentId;
  result.shipmentIdSource = shipmentId ? 'scan_log_cache' : null;

  // Step 2: if no cache, do a live lookup - same as the report does
  if (!shipmentId) {
    const lookup = await veeqoLookupByTrackingSafe(env, tracking);
    result.liveLookupError = lookup.error;
    result.liveLookupFoundOrder = !!lookup.order;
    if (lookup.order) {
      result.rawOrderAllocations = lookup.order.allocations || [];
      shipmentId = veeqoExtractShipmentId(lookup.order);
      result.shipmentIdSource = 'live_order_lookup';
    }
  }

  result.finalShipmentId = shipmentId;

  if (!shipmentId) {
    result.note = 'No shipment_id could be resolved at all - this is why it would show as undelivered with no error.';
    return cors(new Response(JSON.stringify(result), { headers: { 'Content-Type': 'application/json' } }));
  }

  // Step 3: the RAW, unprocessed Veeqo response - no parsing, no filtering
  try {
    const raw = await veeqoFetch(env, `/shipping/tracking_events/${shipmentId}`);
    result.rawTrackingEventsResponse = raw;
    result.isArray = Array.isArray(raw);
    result.eventCount = Array.isArray(raw) ? raw.length : null;
  } catch (e) {
    result.rawFetchError = e.message;
  }

  return cors(new Response(JSON.stringify(result), { headers: { 'Content-Type': 'application/json' } }));
}

// ── GET /ship/lookup?tracking= ────────────────────────────────────────────────

async function shipLookup(url, env) {
  await ensureShipD1Tables(env);
  const tracking = (url.searchParams.get('tracking') || '').trim().toUpperCase();
  if (!tracking) return cors(new Response(JSON.stringify({ error: 'tracking required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

  const [sm, mm] = await Promise.all([
    env.DB.prepare(`SELECT * FROM ship_scan_log WHERE UPPER(tracking) = ? LIMIT 1`).bind(tracking).first(),
    env.DB.prepare(`SELECT * FROM ship_manifest_log WHERE UPPER(tracking) = ? LIMIT 1`).bind(tracking).first(),
  ]);

  const scan     = sm ? { date:sm.date||'', timestamp:sm.timestamp||'', tracking:sm.tracking||'', carrier:sm.carrier||'', initials:sm.initials||'', batchClosedAt:sm.batch_closed_at||'', status:sm.status||'' } : null;
  const manifest = mm ? { date:mm.date||'', tracking:mm.tracking||'', orderNum:mm.order_num||'', channel:mm.channel||'', carrier:mm.carrier||'', service:mm.service||'', shipToState:mm.ship_to_state||'', uploadedBy:mm.uploaded_by||'', reconcileStatus:mm.reconcile_status||'' } : null;

  const verdict = scan && manifest ? 'scanned_in_manifest'
                : scan             ? 'scanned_not_in_manifest'
                : manifest         ? 'gap'
                :                    'not_found';

  return cors(new Response(JSON.stringify({ tracking, verdict, scan, manifest }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── POST /ship/status-upload ──────────────────────────────────────────────────
// Replaces entire Tracking_Status tab with new rows from the app.
// Body: { rows: [[header...], [data...], ...] }
// Any valid session — mgmt signs in for this tab anyway.

async function shipStatusUpload(request, env) {
  try {
    const b = await request.json().catch(() => ({}));
    const { rows } = b;

    if (!Array.isArray(rows) || rows.length < 2) {
      return cors(new Response(JSON.stringify({ error: 'rows array with header + data required' }), {
        status: 400, headers: { 'Content-Type': 'application/json' }
      }));
    }

    const token = await getToken(env);

    // 1. Clear the tab first
    await fetch(
      `${SHEETS_URL}/${env.SHIP_SHEET_ID}/values/${encodeURIComponent('Tracking_Status')}:clear`,
      { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' } }
    );

    // 2. Write all rows starting at A1
    const writeRes = await fetch(
      `${SHEETS_URL}/${env.SHIP_SHEET_ID}/values/${encodeURIComponent('Tracking_Status!A1')}?valueInputOption=USER_ENTERED`,
      {
        method: 'PUT',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ values: rows })
      }
    );
    const writeData = await writeRes.json();
    if (writeData.error) throw new Error('Sheet write: ' + writeData.error.message);

    return cors(new Response(JSON.stringify({
      ok: true, rowsWritten: rows.length - 1
    }), { headers: { 'Content-Type': 'application/json' } }));

  } catch(e) {
    return cors(new Response(JSON.stringify({ error: e.message }), {
      status: 500, headers: { 'Content-Type': 'application/json' }
    }));
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// WAREHOUSE MESSENGER  —  /msg/*
// Sheet: MSG_SHEET_ID env var
// Tab:   Messages  (cols: A=ID, B=Timestamp, C=Initials, D=Category,
//                         E=Priority, F=Body, G=Status, H=Reply, I=ReplyAt)
// Routes:
//   GET  /msg/list          — list messages (query: initials= for own; all=1 for mgmt)
//   POST /msg/send          — send a new message (any session or no session)
//   POST /msg/reply         — mgmt reply (mgmt session required)
//   POST /msg/status        — mgmt set status (mgmt session required)
// ═══════════════════════════════════════════════════════════════════════════

async function handleMsgRoute(url, method, request, env, session) {
  const path = url.pathname;
  try {
    if (path === '/msg/send'   && method === 'POST') return await msgSend(request, env);
    if (path === '/msg/list'   && method === 'GET')  return await msgList(url, env, session);
    if (path === '/msg/reply'  && method === 'POST') return await msgReply(request, env, session);
    if (path === '/msg/status' && method === 'POST') return await msgSetStatus(request, env, session);
    return cors(new Response(JSON.stringify({ error: 'Msg route not found' }), {
      status: 404, headers: { 'Content-Type': 'application/json' }
    }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ error: e.message }), {
      status: 500, headers: { 'Content-Type': 'application/json' }
    }));
  }
}

// ── Sheet helpers ─────────────────────────────────────────────────────────────

async function msgSheetGet(env, range) {
  const token = await getToken(env);
  const r = await fetch(`${SHEETS_URL}/${env.MSG_SHEET_ID}/values/${encodeURIComponent(range)}`, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const data = await r.json();
  if (data.error) throw new Error('Msg sheet read: ' + data.error.message);
  return data;
}

async function msgSheetAppend(env, range, values) {
  const token = await getToken(env);
  const r = await fetch(
    `${SHEETS_URL}/${env.MSG_SHEET_ID}/values/${encodeURIComponent(range)}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,
    {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ values })
    }
  );
  const data = await r.json();
  if (data.error) throw new Error('Msg sheet append: ' + data.error.message);
  return data;
}

async function msgSheetBatchUpdate(env, updates) {
  const token = await getToken(env);
  const r = await fetch(
    `${SHEETS_URL}/${env.MSG_SHEET_ID}/values:batchUpdate`,
    {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ valueInputOption: 'USER_ENTERED', data: updates })
    }
  );
  const data = await r.json();
  if (data.error) throw new Error('Msg batch update: ' + data.error.message);
  return data;
}

// ── Ensure header row exists ──────────────────────────────────────────────────

async function msgEnsureSheet(env) {
  // Try reading the header row. If the tab doesn't exist the Sheets API returns
  // an error like "Unable to parse range: Messages!A1:I1" — we catch that and
  // create the tab first, then write the header row.
  let headerExists = false;
  try {
    const check = await msgSheetGet(env, 'Messages!A1:I1');
    const row = (check.values || [])[0] || [];
    if (row[0] === 'ID') headerExists = true;
  } catch(e) {
    // Tab missing — create it
    const token = await getToken(env);
    await fetch(`${SHEETS_URL}/${env.MSG_SHEET_ID}:batchUpdate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ requests: [{ addSheet: { properties: { title: 'Messages' } } }] })
    });
    // Ignore response — tab may already exist from a prior partial run
  }
  if (!headerExists) {
    await msgSheetAppend(env, 'Messages!A1', [
      ['ID', 'Timestamp', 'Initials', 'Category', 'Priority', 'Body', 'Status', 'Reply', 'ReplyAt']
    ]);
  }
}

// ── Row parser ────────────────────────────────────────────────────────────────

function msgParseRow(row, rowIndex) {
  if (!row || row.length < 2) return null;
  return {
    id:        row[0] || '',
    timestamp: row[1] || '',
    initials:  row[2] || '',
    category:  row[3] || '',
    priority:  row[4] || 'Normal',
    body:      row[5] || '',
    status:    row[6] || 'open',
    reply:     row[7] || '',
    replyAt:   row[8] || '',
    _row:      rowIndex   // 1-based sheet row (data starts at row 2)
  };
}

// ── POST /msg/send ────────────────────────────────────────────────────────────
// Body: { initials, category, priority, body }
// No auth required — any warehouse worker can send

async function msgSend(request, env) {
  const body = await request.json();
  const { initials, category, priority, body: msgBody } = body;

  if (!initials || !category || !msgBody) {
    return cors(new Response(JSON.stringify({ error: 'initials, category and body are required' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const allowed_cats = ['Resources', 'Materials', 'Alert', 'Question', 'Safety', 'Other'];
  const allowed_pri  = ['Normal', 'Urgent', 'Critical'];
  if (!allowed_cats.includes(category)) {
    return cors(new Response(JSON.stringify({ error: 'Invalid category' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  await msgEnsureSheet(env);

  const id        = 'MSG-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
  const timestamp = new Date().toISOString();
  const pri       = allowed_pri.includes(priority) ? priority : 'Normal';

  await msgSheetAppend(env, 'Messages!A:I', [[
    id, timestamp,
    String(initials).toUpperCase().slice(0, 4),
    category, pri,
    String(msgBody).slice(0, 500),
    'open', '', ''
  ]]);

  return cors(new Response(JSON.stringify({ ok: true, id }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── GET /msg/list ─────────────────────────────────────────────────────────────
// ?initials=JD      — returns only messages from that person (any session)
// ?all=1            — returns all messages (any session — mgmt reads via X-Session but
//                     badge poll also works unauthenticated; filter sensitive on frontend)
// ?limit=N          — max rows to return (default 200)

async function msgList(url, env, session) {
  await msgEnsureSheet(env);

  const initials = (url.searchParams.get('initials') || '').toUpperCase().trim();
  const all      = url.searchParams.get('all') === '1';
  const limit    = Math.min(parseInt(url.searchParams.get('limit') || '200', 10), 500);

  const data = await msgSheetGet(env, 'Messages!A2:I1001');
  const rows = data.values || [];

  let messages = rows
    .map((r, i) => msgParseRow(r, i + 2))
    .filter(Boolean)
    .filter(m => m.id && m.body); // skip blank rows

  if (initials && !all) {
    messages = messages.filter(m => m.initials === initials);
  }

  // Sort newest first, cap at limit
  messages = messages.reverse().slice(0, limit);

  return cors(new Response(JSON.stringify({ ok: true, messages }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── POST /msg/reply ───────────────────────────────────────────────────────────
// Body: { id, reply }
// Requires mgmt session

async function msgReply(request, env, session) {
  if (!session || session.pin_level !== 'mgmt') {
    return cors(new Response(JSON.stringify({ error: 'Management access required' }), {
      status: 403, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const body = await request.json();
  const { id, reply } = body;
  if (!id || !reply) {
    return cors(new Response(JSON.stringify({ error: 'id and reply required' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const rowIndex = await msgFindRowById(env, id);
  if (!rowIndex) {
    return cors(new Response(JSON.stringify({ error: 'Message not found' }), {
      status: 404, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const replyAt = new Date().toISOString();
  await msgSheetBatchUpdate(env, [
    { range: `Messages!G${rowIndex}`, values: [['replied']] },
    { range: `Messages!H${rowIndex}`, values: [[String(reply).slice(0, 400)]] },
    { range: `Messages!I${rowIndex}`, values: [[replyAt]] }
  ]);

  return cors(new Response(JSON.stringify({ ok: true }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── POST /msg/status ──────────────────────────────────────────────────────────
// Body: { id, status }   status: 'open' | 'archived'
// Requires mgmt session

async function msgSetStatus(request, env, session) {
  if (!session || session.pin_level !== 'mgmt') {
    return cors(new Response(JSON.stringify({ error: 'Management access required' }), {
      status: 403, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const body = await request.json();
  const { id, status } = body;
  const allowed = ['open', 'archived', 'replied'];
  if (!id || !allowed.includes(status)) {
    return cors(new Response(JSON.stringify({ error: 'id and valid status required' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const rowIndex = await msgFindRowById(env, id);
  if (!rowIndex) {
    return cors(new Response(JSON.stringify({ error: 'Message not found' }), {
      status: 404, headers: { 'Content-Type': 'application/json' }
    }));
  }

  await msgSheetBatchUpdate(env, [
    { range: `Messages!G${rowIndex}`, values: [[status]] }
  ]);

  return cors(new Response(JSON.stringify({ ok: true }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── Find row number by message ID ─────────────────────────────────────────────

async function msgFindRowById(env, id) {
  const data = await msgSheetGet(env, 'Messages!A2:A1001');
  const rows = data.values || [];
  for (let i = 0; i < rows.length; i++) {
    if ((rows[i][0] || '') === id) return i + 2; // +2: 1-based + header row
  }
  return null;
}

// ═════════════════════════════════════════════════════════════════════════════
// EBAY AI MESSAGES  —  v15 addition
// Routes: GET  /ebay-msg/list     — fetch unanswered eBay buyer messages
//         POST /ebay-msg/ai-draft — generate AI draft replies for a batch
//         POST /ebay-msg/send     — send a reply via Trading API AddMemberMessageRTQ
//                                   or AddMemberMessageAAQToPartner
//         GET  /ebay-msg/log      — fetch reply log from eBay_MsgLog sheet
// All routes require mgmt session (enforced in router above).
// eBay token: reuses getEbayToken(env) — same OAuth refresh token as repricer.
// Anthropic: uses ANTHROPIC_KEY env var, model claude-haiku-4-5-20251001.
// Google Sheet log: stored in repricer sheet (SHEET_ID_REPRICER) tab eBay_MsgLog
//   cols: A=ID, B=Timestamp, C=MessageID, D=ItemID, E=BuyerID, F=Subject,
//         G=Question (truncated), H=AIDraft, I=FinalReply, J=Status, K=SentAt
// ═════════════════════════════════════════════════════════════════════════════

// ── Route dispatcher ──────────────────────────────────────────────────────────
async function handleEbayMsgRoute(url, method, request, env) {
  const path = url.pathname;
  try {
    if (path === '/ebay-msg/list'          && method === 'GET')  return await ebayMsgList(url, env);
    if (path === '/ebay-msg/ai-draft'      && method === 'POST') return await ebayMsgAiDraft(request, env);
    if (path === '/ebay-msg/send'          && method === 'POST') return await ebayMsgSend(request, env);
    if (path === '/ebay-msg/log'           && method === 'GET')  return await ebayMsgLog(url, env);
    if (path === '/ebay-msg/analytics'     && method === 'GET')  return await ebayMsgAnalytics(url, env);
    if (path === '/ebay-msg/threads'       && method === 'GET')  return await ebayThreadsGet(url, env);
    if (path === '/ebay-msg/threads/save'  && method === 'POST') return await ebayThreadsSave(request, env);
    if (path === '/ebay-msg/cleanup'       && method === 'POST') return await ebayThreadsCleanup(env);
    return cors(new Response(JSON.stringify({ error: 'eBay message route not found' }), {
      status: 404, headers: { 'Content-Type': 'application/json' }
    }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ error: e.message }), {
      status: 500, headers: { 'Content-Type': 'application/json' }
    }));
  }
}

// ── GET /ebay-msg/list ────────────────────────────────────────────────────────
// Fetches ALL buyer messages by running two Trading API calls in parallel:
//   1. GetMemberMessages  — pre-sale listing questions (AskSellerQuestion)
//   2. GetMyMessages      — full inbox including post-purchase order messages
// Results are merged, deduplicated by messageId, and sorted newest first.
// Each message includes replyType: 'RTQ' (pre-sale) | 'AAQ' (post-order)
// so the send route knows which eBay API call to use.
// ?days=N  — look back N days (default 7, max 30)
// ?status=Unanswered|All  — filter (default Unanswered)
async function ebayMsgList(url, env) {
  const days   = Math.min(parseInt(url.searchParams.get('days') || '7'), 30);
  const status = url.searchParams.get('status') === 'All' ? 'All' : 'Unanswered';

  const ebayToken = await getEbayToken(env);
  const now       = new Date();
  const start     = new Date(now.getTime() - days * 86400000);

  function toEbayDate(d) {
    // eBay Trading API requires ISO 8601 UTC: 2026-03-19T20:00:00.000Z
    return d.toISOString().replace(/\.\d{3}Z$/, '.000Z');
  }

  // ── 1. GetMemberMessages — pre-sale listing questions ──────────────────────
  // eBay only accepts MessageStatus = 'Unanswered' or 'Answered' (not 'All').
  // When status='All', we run both in parallel and merge.
  async function fetchMemberMessages() {
    async function fetchWithStatus(msgStatus) {
      const xmlBody = `<?xml version="1.0" encoding="utf-8"?>
<GetMemberMessagesRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <MailMessageType>AskSellerQuestion</MailMessageType>
  <MessageStatus>${msgStatus}</MessageStatus>
  <StartCreationTime>${toEbayDate(start)}</StartCreationTime>
  <EndCreationTime>${toEbayDate(now)}</EndCreationTime>
  <Pagination><EntriesPerPage>100</EntriesPerPage><PageNumber>1</PageNumber></Pagination>
</GetMemberMessagesRequest>`;
      const r = await fetch('https://api.ebay.com/ws/api.dll', {
        method: 'POST',
        headers: {
          'X-EBAY-API-CALL-NAME': 'GetMemberMessages', 'X-EBAY-API-SITEID': '0',
          'X-EBAY-API-COMPATIBILITY-LEVEL': '967', 'X-EBAY-API-IAF-TOKEN': ebayToken,
          'Content-Type': 'text/xml',
        },
        body: xmlBody
      });
      const xml = await r.text();
      if (xml.includes('<Ack>Failure</Ack>')) {
        const errMsg  = parseXmlError(xml);
        const longMsg = xml.match(/<LongMessage>([^<]+)<\/LongMessage>/)?.[1] || '';
        return { messages: [], error: errMsg + (longMsg ? ' | ' + longMsg : '') };
      }
      const exchanges = xml.match(/<MemberMessageExchange>([\s\S]*?)<\/MemberMessageExchange>/g) || [];
      const messages  = [];
      for (const ex of exchanges) {
        const m = parseMemberMessageBlock(ex);
        if (m) { m.replyType = 'RTQ'; m.source = 'listing'; messages.push(m); }
      }
      return { messages };
    }

    if (status === 'All') {
      // Run both Unanswered + Answered in parallel, merge
      const [unans, ans] = await Promise.all([
        fetchWithStatus('Unanswered').catch(e => ({ messages: [], error: e.message })),
        fetchWithStatus('Answered').catch(e => ({ messages: [], error: e.message }))
      ]);
      const combined = [...unans.messages, ...ans.messages];
      const error    = unans.error || ans.error || undefined;
      return { messages: combined, error };
    } else {
      return fetchWithStatus('Unanswered');
    }
  }

  // ── 2. GetMyMessages — full inbox including post-purchase order messages ───
  // eBay requires two-step approach:
  //   Step A: ReturnSummary to get unread count (optional but good practice)
  //   Step B: ReturnHeaders with date range to get MessageIDs
  //   Step C: ReturnMessages with explicit MessageIDs to get bodies
  // This avoids the "Missing required parameter" error from passing date range with ReturnMessages.
  async function fetchMyMessages() {

    // Step 1: Get message headers (IDs) for the date range
    const headersXml = `<?xml version="1.0" encoding="utf-8"?>
<GetMyMessagesRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <DetailLevel>ReturnHeaders</DetailLevel>
  <StartTime>${toEbayDate(start)}</StartTime>
  <EndTime>${toEbayDate(now)}</EndTime>
  <Pagination><EntriesPerPage>100</EntriesPerPage><PageNumber>1</PageNumber></Pagination>
</GetMyMessagesRequest>`;

    const rh = await fetch('https://api.ebay.com/ws/api.dll', {
      method: 'POST',
      headers: {
        'X-EBAY-API-CALL-NAME': 'GetMyMessages',
        'X-EBAY-API-SITEID': '0',
        'X-EBAY-API-COMPATIBILITY-LEVEL': '967',
        'X-EBAY-API-IAF-TOKEN': ebayToken,
        'Content-Type': 'text/xml',
      },
      body: headersXml
    });
    const headXml = await rh.text();
    if (headXml.includes('<Ack>Failure</Ack>')) return { messages: [], error: parseXmlError(headXml) };

    // Extract MessageIDs from headers response
    const allMsgIds = (headXml.match(/<MessageID>([^<]+)<\/MessageID>/g) || [])
      .map(m => m.replace(/<\/?MessageID>/g, '').trim())
      .filter(Boolean)
      .slice(0, 50); // cap at 50 to avoid oversized request

    // Surface how many IDs we found for diagnostics
    if (!allMsgIds.length) {
      // Try to get a snippet of what eBay returned so we can debug
      const summaryMatch = headXml.match(/<Summary>([\s\S]*?)<\/Summary>/);
      const totalCount   = summaryMatch ? (summaryMatch[0].match(/<TotalMessageCount>(\d+)<\/TotalMessageCount>/) || [])[1] : null;
      const debugNote    = totalCount !== null ? 'eBay reports ' + totalCount + ' total messages but 0 IDs in date range' : 'ReturnHeaders returned 0 MessageIDs';
      return { messages: [], error: debugNote };
    }

    // Step 2: Fetch full message bodies by explicit MessageIDs
    const msgIdTags = allMsgIds.map(id => `  <MessageIDs><MessageID>${escXml(id)}</MessageID></MessageIDs>`).join('\n');
    const bodiesXml = `<?xml version="1.0" encoding="utf-8"?>
<GetMyMessagesRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <DetailLevel>ReturnMessages</DetailLevel>
${msgIdTags}
</GetMyMessagesRequest>`;

    const rb = await fetch('https://api.ebay.com/ws/api.dll', {
      method: 'POST',
      headers: {
        'X-EBAY-API-CALL-NAME': 'GetMyMessages',
        'X-EBAY-API-SITEID': '0',
        'X-EBAY-API-COMPATIBILITY-LEVEL': '967',
        'X-EBAY-API-IAF-TOKEN': ebayToken,
        'Content-Type': 'text/xml',
      },
      body: bodiesXml
    });
    const bodyXml = await rb.text();
    if (bodyXml.includes('<Ack>Failure</Ack>')) return { messages: [], error: parseXmlError(bodyXml) };

    // Parse <Message> blocks from bodies response
    const msgBlocks = bodyXml.match(/<Message>([\s\S]*?)<\/Message>/g) || [];
    const messages  = [];
    for (const blk of msgBlocks) {
      const m = parseMyMessageBlock(blk);
      if (!m) continue;
      // Skip eBay system/automated messages — only real buyer messages
      const sender = (m.senderId || '').toLowerCase();
      if (sender === 'ebay' || sender.startsWith('cs-')) continue;
      if (!m.body && !m.subject) continue; // skip truly empty
      // Filter unread only if status=Unanswered
      if (status === 'Unanswered' && m.read === 'true') continue;
      m.replyType = 'AAQ';
      m.source    = 'inbox';
      messages.push(m);
    }
    return { messages };
  }

  // ── Run both in parallel ───────────────────────────────────────────────────
  // NOTE: GetMyMessages (inbox) temporarily disabled pending OAuth refresh token fix
  // Only listing questions (GetMemberMessages) active until token is resolved
  const [memberResult, myMsgResult] = await Promise.all([
    fetchMemberMessages().catch(e => ({ messages: [], error: e.message })),
    Promise.resolve({ messages: [], error: null }) // inbox disabled temporarily
  ]);

  // Merge and deduplicate by messageId
  const seen     = new Set();
  const combined = [];
  for (const m of [...memberResult.messages, ...myMsgResult.messages]) {
    const key = m.messageId || (m.senderId + '|' + m.body.slice(0, 40));
    if (seen.has(key)) continue;
    seen.add(key);
    combined.push(m);
  }

  // Sort newest first
  combined.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  const errors = [];
  if (memberResult.error) errors.push('GetMemberMessages: ' + memberResult.error);
  if (myMsgResult.error)  errors.push('GetMyMessages: '     + myMsgResult.error);

  return cors(new Response(JSON.stringify({
    ok: true,
    messages: combined,
    count: combined.length,
    days, status,
    sourceBreakdown: {
      listing: memberResult.messages.length,
      inbox:   myMsgResult.messages.length
    },
    warnings: errors.length ? errors : undefined,
    debug: {
      memberError: memberResult.error || null,
      inboxError:  myMsgResult.error  || null,
    }
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// ── XML parsing helpers ───────────────────────────────────────────────────────

function parseXmlError(xml) {
  const m = xml.match(/<ShortMessage>([^<]+)<\/ShortMessage>/);
  return m ? m[1] : 'eBay API error';
}

function parseMemberMessageBlock(ex) {
  const msgIdMatch  = ex.match(/<MessageID>([^<]+)<\/MessageID>/);
  if (!msgIdMatch) return null;
  const itemIdMatch = ex.match(/<ItemID>([^<]+)<\/ItemID>/);
  const titleMatch  = ex.match(/<Title>([^<]+)<\/Title>/);
  const senderMatch = ex.match(/<SenderID>([^<]+)<\/SenderID>/);
  const bodyMatch   = ex.match(/<Body>([\s\S]*?)<\/Body>/);
  const subjectMatch= ex.match(/<Subject>([^<]+)<\/Subject>/);
  const createdMatch= ex.match(/<CreationDate>([^<]+)<\/CreationDate>/);
  const statusMatch = ex.match(/<MessageStatus>([^<]+)<\/MessageStatus>/);
  const typeMatch   = ex.match(/<MessageType>([^<]+)<\/MessageType>/);
  const priceMatch  = ex.match(/<CurrentPrice[^>]*>([\d.]+)<\/CurrentPrice>/);
  return {
    messageId:    (msgIdMatch[1]    || '').trim(),
    itemId:       (itemIdMatch?.[1] || '').trim(),
    title:        (titleMatch?.[1]  || '').trim(),
    senderId:     (senderMatch?.[1] || '').trim(),
    body:         (bodyMatch?.[1]   || '').replace(/<[^>]+>/g, '').trim(),
    subject:      (subjectMatch?.[1]|| '').trim(),
    createdAt:    (createdMatch?.[1]|| '').trim(),
    status:       (statusMatch?.[1] || '').trim(),
    type:         (typeMatch?.[1]   || '').trim(),
    currentPrice: priceMatch ? parseFloat(priceMatch[1]) : null,
    read:         'false',
  };
}

function parseMyMessageBlock(blk) {
  const msgIdMatch   = blk.match(/<MessageID>([^<]+)<\/MessageID>/);
  if (!msgIdMatch) return null;
  const senderMatch  = blk.match(/<Sender>([^<]+)<\/Sender>/);
  const subjectMatch = blk.match(/<Subject>([^<]+)<\/Subject>/);
  const textMatch    = blk.match(/<Text>([\s\S]*?)<\/Text>/);
  const createdMatch = blk.match(/<ReceiveDate>([^<]+)<\/ReceiveDate>/);
  const readMatch    = blk.match(/<Read>(true|false)<\/Read>/);
  const itemIdMatch  = blk.match(/<ItemID>([^<]+)<\/ItemID>/);
  const extIdMatch   = blk.match(/<ExternalMessageID>([^<]+)<\/ExternalMessageID>/);
  // Strip HTML from body text
  const rawBody = (textMatch?.[1] || '').replace(/<[^>]+>/g, '').replace(/&nbsp;/g,' ').trim();
  return {
    messageId:      (msgIdMatch[1]   || '').trim(),
    externalMsgId:  (extIdMatch?.[1] || '').trim(), // thread ID for AAQ replies
    itemId:         (itemIdMatch?.[1]|| '').trim(),
    title:          '',   // GetMyMessages doesn't include listing title
    senderId:       (senderMatch?.[1]|| '').trim(),
    body:           rawBody,
    subject:        (subjectMatch?.[1]|| '').trim(),
    createdAt:      (createdMatch?.[1]|| '').trim(),
    status:         (readMatch?.[1] === 'true') ? 'Answered' : 'Unanswered',
    type:           'OrderInquiry',
    currentPrice:   null,
    read:           (readMatch?.[1] || 'false'),
  };
}

// ── POST /ebay-msg/ai-draft ───────────────────────────────────────────────────
// Body: { messages: [{ messageId, itemId, title, senderId, body, currentPrice }] }
// Returns same array with aiDraft added to each item.
// Calls Claude Haiku once per message (parallel, max 5 at a time).
async function ebayMsgAiDraft(request, env) {
  const body = await request.json().catch(() => ({}));
  const msgs      = Array.isArray(body.messages) ? body.messages.slice(0, 20) : [];
  const agentName = (body.agentName || '').trim(); // e.g. "Danny"

  if (!msgs.length) {
    return cors(new Response(JSON.stringify({ error: 'No messages provided' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  // Sign-off line — personalised if agentName provided
  const signOff = agentName
    ? `Best,\n${agentName} | XFITTING Team Support`
    : `Best,\nXFITTING Team Support`;

  async function draftOne(msg) {
    const prompt = `You are a customer support assistant for XFITTING, an eCommerce brand that sells PEX plumbing fittings and valves on eBay.
Your job is to respond to customer messages in a clear, professional, and efficient way, matching the tone and style of XFITTING support.

-------------------------
TONE & STYLE GUIDELINES
-------------------------
- Always start with: "Hi,"
- Always end with EXACTLY this sign-off on its own line: "${signOff}"
- Keep responses concise, direct, and helpful (no fluff)
- Use simple, clear language (assume DIY-level understanding unless customer shows expertise)
- Be polite but not overly apologetic
- Be confident and solution-oriented
- Avoid long paragraphs; keep it easy to read

-------------------------
CORE PRINCIPLES
-------------------------
1. Always guide the customer toward the correct next step
2. Protect the business from unnecessary loss (do not offer refunds/replacements unless justified)
3. Keep everything documented through eBay (returns, refunds, etc.)
4. Never blame the customer or sound defensive
5. Assume good intent, but stay cautious of scams or abuse
6. If something is unclear, ask a short clarifying question

-------------------------
PRODUCT KNOWLEDGE
-------------------------
- XFITTING sells PEX B (crimp/barb), PEX A (expansion), Push Fit, CPVC, and brass fittings
- Compatibility rules:
  - PEX B = crimp/barb system
  - PEX A = expansion system (NOT interchangeable with PEX B)
  - Push Fit = works with PEX, copper, CPVC (no tools required)
- Never guess compatibility — if unsure, ask for pipe type/system clarification

-------------------------
RETURNS & REFUNDS POLICY
-------------------------
- Always direct customers to open a return through eBay
- Do NOT offer off-platform refunds
- Wrong item / defective: apologize briefly, instruct to open return under "wrong item received" or "defective"
- Buyer remorse: still direct to eBay return process
- Do NOT promise prepaid labels unless policy clearly requires it
- Emphasize eBay keeps everything documented and protects both sides

-------------------------
COMMON SCENARIOS
-------------------------
1. Return request: "Please open a return request through eBay by going to your order and selecting 'Return this item.'"
2. Wrong item: Acknowledge, direct to open return under "wrong item received", do NOT send replacement without process
3. Late delivery: Acknowledge delay, reference carrier (USPS etc.), no compensation unless necessary
4. Technical/compatibility question: Answer clearly if known; if unclear, ask what pipe/type/system they are using
5. Suspicious behavior: Stay neutral, do not accuse, stick strictly to eBay process

-------------------------
WHAT NOT TO DO
-------------------------
- Do NOT give long explanations unless necessary
- Do NOT go off-topic
- Do NOT offer partial refunds casually
- Do NOT bypass eBay processes
- Do NOT sound robotic
- Do NOT include a subject line
- Do NOT repeat the buyer's question back to them

-------------------------
LISTING CONTEXT
-------------------------
Listing: "${msg.title || 'PEX Fitting'}"${msg.currentPrice ? ` — Price: $${msg.currentPrice.toFixed(2)}` : ''}
Item ID: ${msg.itemId || 'N/A'}

Buyer message from ${msg.senderId || 'buyer'}:
"${(msg.body || '').slice(0, 800)}"
${msg._note ? `
-------------------------
AGENT NOTE (important context — factor this into your reply):
${msg._note.slice(0, 300)}
-------------------------` : ''}
Now write the reply. Start with "Hi," and end with "${signOff}". Keep it short and professional.
After your sign-off, on a new line add ONLY: [CONFIDENCE:X.XX] where X.XX is 0.00-1.00.
1.00=clear question/certain answer | 0.70=standard | 0.50=some ambiguity | 0.30=unclear/complex`;

    try {
      const aiResp = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': env.ANTHROPIC_KEY || env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01'
        },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 300,
          messages: [{ role: 'user', content: prompt }]
        })
      });
      const aiData = await aiResp.json();
      // Surface API-level errors (wrong key, model not found, quota, etc.)
      if (aiData.error) {
        return { ...msg, aiDraft: '', draftOk: false, draftError: aiData.error.message || JSON.stringify(aiData.error) };
      }
      const draft = (aiData.content?.[0]?.text || '').trim();
      if (!draft) {
        return { ...msg, aiDraft: '', draftOk: false, draftError: 'Empty AI response — raw: ' + JSON.stringify(aiData).slice(0, 300) };
      }
      // Parse confidence tag from end of draft
      let confidence = 0.8;
      let cleanDraft = draft;
      const confMatch = draft.match(/\[CONFIDENCE:([\d.]+)\]\s*$/);
      if (confMatch) {
        confidence = Math.min(1, Math.max(0, parseFloat(confMatch[1]) || 0.8));
        cleanDraft = draft.replace(/\[CONFIDENCE:[\d.]+\]\s*$/, '').trim();
      }
      return { ...msg, aiDraft: cleanDraft, draftOk: true, confidence };
    } catch(e) {
      return { ...msg, aiDraft: '', draftOk: false, draftError: e.message };
    }
  }

  // Process in batches of 5 parallel
  const results = [];
  for (let i = 0; i < msgs.length; i += 5) {
    const batch = msgs.slice(i, i + 5);
    const done  = await Promise.all(batch.map(draftOne));
    results.push(...done);
  }

  return cors(new Response(JSON.stringify({ ok: true, messages: results }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── POST /ebay-msg/send ───────────────────────────────────────────────────────
// Body: { messageId, itemId, senderId, reply, replyType, subject, originalBody, externalMsgId }
// replyType: 'RTQ' → AddMemberMessageRTQ  (pre-sale listing questions)
//            'AAQ' → AddMemberMessageAAQToPartner  (post-purchase order messages)
// Logs the sent reply to eBay_MsgLog sheet.
async function ebayMsgSend(request, env) {
  const body = await request.json().catch(() => ({}));
  const { messageId, itemId, senderId, reply, replyType, subject, originalBody, externalMsgId } = body;

  if (!messageId || !reply) {
    return cors(new Response(JSON.stringify({ error: 'messageId and reply are required' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const ebayToken = await getEbayToken(env);
  const useAAQ    = replyType === 'AAQ'; // post-purchase order messages

  let xmlBody, callName;

  if (useAAQ) {
    // AddMemberMessageAAQToPartner — for post-purchase order messages
    // Requires ItemID + ParentMessageID (the original message ID)
    callName = 'AddMemberMessageAAQToPartner';
    xmlBody  = `<?xml version="1.0" encoding="utf-8"?>
<AddMemberMessageAAQToPartnerRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <ItemID>${escXml(itemId || '')}</ItemID>
  <MemberMessage>
    <Body>${escXml(reply)}</Body>
    <ParentMessageID>${escXml(messageId)}</ParentMessageID>
    <RecipientID>${escXml(senderId || '')}</RecipientID>
  </MemberMessage>
</AddMemberMessageAAQToPartnerRequest>`;
  } else {
    // AddMemberMessageRTQ — for pre-sale Ask Seller a Question messages
    callName = 'AddMemberMessageRTQ';
    xmlBody  = `<?xml version="1.0" encoding="utf-8"?>
<AddMemberMessageRTQRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <ItemID>${escXml(itemId || '')}</ItemID>
  <MemberMessage>
    <Body>${escXml(reply)}</Body>
    <DisplayToPublic>false</DisplayToPublic>
    <EmailCopyToSender>false</EmailCopyToSender>
    <ParentMessageID>${escXml(messageId)}</ParentMessageID>
    <RecipientID>${escXml(senderId || '')}</RecipientID>
  </MemberMessage>
</AddMemberMessageRTQRequest>`;
  }

  const r = await fetch('https://api.ebay.com/ws/api.dll', {
    method: 'POST',
    headers: {
      'X-EBAY-API-CALL-NAME': callName,
      'X-EBAY-API-SITEID': '0',
      'X-EBAY-API-COMPATIBILITY-LEVEL': '967',
      'X-EBAY-API-IAF-TOKEN': ebayToken,
      'Content-Type': 'text/xml',
    },
    body: xmlBody
  });

  const xml  = await r.text();
  const ok   = xml.includes('<Ack>Success</Ack>') || xml.includes('<Ack>Warning</Ack>');
  const errM = xml.match(/<ShortMessage>([^<]+)<\/ShortMessage>/);
  const errMsg = errM ? errM[1] : '';

  // Log to sheet regardless of success/failure
  const ts = new Date().toISOString();
  const logId = 'EMSG-' + Date.now() + '-' + Math.random().toString(36).slice(2, 5).toUpperCase();
  await ebayMsgLogAppend(env, [[
    logId, ts,
    messageId || '',
    itemId    || '',
    senderId  || '',
    subject   || '',
    (originalBody || '').slice(0, 300),
    '',  // AIDraft col (not stored here — set in ai-draft)
    reply.slice(0, 500),
    ok ? 'Sent' : 'Failed',
    ok ? ts : '',
    ok ? '' : errMsg
  ]]);

  if (!ok) {
    return cors(new Response(JSON.stringify({ ok: false, error: errMsg || 'eBay API error', xml: xml.slice(0, 800) }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  // Save seller reply to thread history (fire-and-forget — don't block response)
  if (ok) {
    const threadId = externalMsgId || messageId || '';
    ebayThreadsSave({ json: async () => ({ messages: [{
      threadId,
      messageId: 'REPLY-' + logId,
      timestamp: ts,
      itemId:    itemId    || '',
      buyerId:   senderId  || '',
      subject:   subject   || '',
      direction: 'SELLER',
      body:      reply,
      replyType: useAAQ ? 'AAQ' : 'RTQ',
      sentAt:    ts,
    }]}) }, env).catch(() => {});
  }

  return cors(new Response(JSON.stringify({ ok: true, logId }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── GET /ebay-msg/log ─────────────────────────────────────────────────────────
// Returns last 100 log entries from eBay_MsgLog sheet.
async function ebayMsgLog(url, env) {
  await ebayMsgEnsureSheet(env);
  const limit = Math.min(parseInt(url.searchParams.get('limit') || '100'), 500);
  const data = await rSheetGet(env, 'eBay_MsgLog!A2:L1001').catch(() => ({ values: [] }));
  const rows = (data.values || []).map(r => ({
    id:           r[0]  || '',
    timestamp:    r[1]  || '',
    messageId:    r[2]  || '',
    itemId:       r[3]  || '',
    buyerId:      r[4]  || '',
    subject:      r[5]  || '',
    question:     r[6]  || '',
    aiDraft:      r[7]  || '',
    finalReply:   r[8]  || '',
    status:       r[9]  || '',
    sentAt:       r[10] || '',
    error:        r[11] || '',
  })).reverse().slice(0, limit);

  return cors(new Response(JSON.stringify({ ok: true, log: rows }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── Sheet helpers ─────────────────────────────────────────────────────────────

async function ebayMsgEnsureSheet(env) {
  try {
    const check = await rSheetGet(env, 'eBay_MsgLog!A1:L1');
    const row   = (check.values || [])[0] || [];
    if (row[0] === 'ID') return; // already exists
  } catch(e) {
    // Tab missing — create it
    const token = await getToken(env);
    const sid   = repricerSheetId(env);
    await fetch(`${SHEETS_URL}/${sid}:batchUpdate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ requests: [{ addSheet: { properties: { title: 'eBay_MsgLog' } } }] })
    }).catch(() => {});
  }
  // Write header row
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  await fetch(`${SHEETS_URL}/${sid}/values/${encodeURIComponent('eBay_MsgLog!A1:L1')}?valueInputOption=RAW`, {
    method: 'PUT',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values: [['ID','Timestamp','MessageID','ItemID','BuyerID','Subject','Question','AIDraft','FinalReply','Status','SentAt','Error']] })
  }).catch(() => {});
}

async function ebayMsgLogAppend(env, rows) {
  await ebayMsgEnsureSheet(env);
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  const url   = `${SHEETS_URL}/${sid}/values/${encodeURIComponent('eBay_MsgLog!A:L')}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`;
  await fetch(url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values: rows })
  });
}

// ── XML escape helper (reuse if already defined, else define here) ────────────
function escXml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

// ═════════════════════════════════════════════════════════════════════════════
// EBAY THREAD HISTORY  —  v15 addition (thread storage + 30-day cleanup)
// Sheet tab: eBay_Threads (auto-created in SHEET_ID_REPRICER)
// Cols A–J: ThreadID, MessageID, Timestamp, ItemID, BuyerID, Subject,
//           Direction, Body, ReplyType, SentAt
// Routes added:
//   GET  /ebay-msg/threads?threadId=X   — fetch thread history for one conversation
//   POST /ebay-msg/threads/save          — save one or more messages to sheet
//   POST /ebay-msg/cleanup               — delete rows older than 30 days (called silently)
// ═════════════════════════════════════════════════════════════════════════════

// ── Sheet name ────────────────────────────────────────────────────────────────
const THREAD_TAB = 'eBay_Threads';
const THREAD_HEADERS = ['ThreadID','MessageID','Timestamp','ItemID','BuyerID','Subject','Direction','Body','ReplyType','SentAt'];

// ── Ensure eBay_Threads tab exists with correct headers ──────────────────────
async function ebayThreadsEnsureSheet(env) {
  try {
    const check = await rSheetGet(env, `${THREAD_TAB}!A1:J1`);
    const row   = (check.values || [])[0] || [];
    if (row[0] === 'ThreadID') return; // already set up
  } catch(e) {
    // Tab missing — create it
    const token = await getToken(env);
    const sid   = repricerSheetId(env);
    await fetch(`${SHEETS_URL}/${sid}:batchUpdate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ requests: [{ addSheet: { properties: { title: THREAD_TAB } } }] })
    }).catch(() => {});
  }
  // Write header row
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  await fetch(`${SHEETS_URL}/${sid}/values/${encodeURIComponent(THREAD_TAB + '!A1:J1')}?valueInputOption=RAW`, {
    method: 'PUT',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values: [THREAD_HEADERS] })
  }).catch(() => {});
}

// ── Append rows to eBay_Threads ───────────────────────────────────────────────
async function ebayThreadsAppend(env, rows) {
  await ebayThreadsEnsureSheet(env);
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  const url   = `${SHEETS_URL}/${sid}/values/${encodeURIComponent(THREAD_TAB + '!A:J')}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`;
  await fetch(url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values: rows })
  });
}

// ── GET /ebay-msg/threads?threadId=X ─────────────────────────────────────────
// Returns all messages for a given threadId, sorted oldest first.
// threadId = ExternalMessageID for AAQ threads, or MessageID for RTQ threads.
async function ebayThreadsGet(url, env) {
  const threadId = (url.searchParams.get('threadId') || '').trim();
  if (!threadId) {
    return cors(new Response(JSON.stringify({ error: 'threadId required' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }
  await ebayThreadsEnsureSheet(env);
  const data = await rSheetGet(env, `${THREAD_TAB}!A2:J5000`).catch(() => ({ values: [] }));
  const rows = (data.values || [])
    .filter(r => (r[0] || '') === threadId)
    .map(r => ({
      threadId:   r[0] || '',
      messageId:  r[1] || '',
      timestamp:  r[2] || '',
      itemId:     r[3] || '',
      buyerId:    r[4] || '',
      subject:    r[5] || '',
      direction:  r[6] || '',   // BUYER | SELLER
      body:       r[7] || '',
      replyType:  r[8] || '',
      sentAt:     r[9] || '',
    }))
    .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp)); // oldest first

  return cors(new Response(JSON.stringify({ ok: true, thread: rows, count: rows.length }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── POST /ebay-msg/threads/save ───────────────────────────────────────────────
// Body: { messages: [{ threadId, messageId, timestamp, itemId, buyerId, subject, direction, body, replyType, sentAt }] }
// Saves one or more messages. Deduplicates by messageId to avoid double-writes.
async function ebayThreadsSave(request, env) {
  const body = await request.json().catch(() => ({}));
  const msgs = Array.isArray(body.messages) ? body.messages : [];
  if (!msgs.length) {
    return cors(new Response(JSON.stringify({ ok: true, saved: 0 }), {
      headers: { 'Content-Type': 'application/json' }
    }));
  }

  await ebayThreadsEnsureSheet(env);

  // Read existing messageIds to deduplicate
  const existing = await rSheetGet(env, `${THREAD_TAB}!B2:B5000`).catch(() => ({ values: [] }));
  const existingIds = new Set((existing.values || []).map(r => (r[0] || '').trim()).filter(Boolean));

  const toWrite = msgs
    .filter(m => m.messageId && !existingIds.has(m.messageId))
    .map(m => [
      (m.threadId  || '').slice(0, 200),
      (m.messageId || '').slice(0, 200),
      m.timestamp  || new Date().toISOString(),
      (m.itemId    || '').slice(0, 50),
      (m.buyerId   || '').slice(0, 100),
      (m.subject   || '').slice(0, 200),
      m.direction  === 'SELLER' ? 'SELLER' : 'BUYER',
      (m.body      || '').slice(0, 1000),
      (m.replyType || 'RTQ'),
      m.sentAt     || '',
    ]);

  if (toWrite.length) {
    await ebayThreadsAppend(env, toWrite);
  }

  return cors(new Response(JSON.stringify({ ok: true, saved: toWrite.length, skipped: msgs.length - toWrite.length }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ── POST /ebay-msg/cleanup ────────────────────────────────────────────────────
// Deletes rows from eBay_Threads where Timestamp < 30 days ago.
// Called silently by the frontend on app open — no UI feedback.
// Uses batchUpdate deleteRows (working bottom-up to preserve row indices).
async function ebayThreadsCleanup(env) {
  await ebayThreadsEnsureSheet(env);
  const cutoff = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

  const data = await rSheetGet(env, `${THREAD_TAB}!A2:C5000`).catch(() => ({ values: [] }));
  const rows = data.values || [];

  // Collect 0-based sheet row indices (add 1 for header, add 1 for 0-based = +2) of rows to delete
  // We process bottom-up so deletions don't shift indices
  const toDelete = [];
  for (let i = rows.length - 1; i >= 0; i--) {
    const ts = rows[i][2] || rows[i][0] || ''; // col C = Timestamp, fallback col A
    if (ts && ts < cutoff) {
      toDelete.push(i + 1); // +1 for header row (sheet row index is 1-based data, but API uses 0-based)
    }
  }

  if (!toDelete.length) {
    return cors(new Response(JSON.stringify({ ok: true, deleted: 0 }), {
      headers: { 'Content-Type': 'application/json' }
    }));
  }

  // Get sheetId for eBay_Threads tab
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  const metaR = await fetch(`${SHEETS_URL}/${sid}?fields=sheets.properties`, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const meta    = await metaR.json();
  const sheetId = ((meta.sheets || []).find(s => s.properties?.title === THREAD_TAB) || {}).properties?.sheetId;
  if (sheetId === undefined) {
    return cors(new Response(JSON.stringify({ ok: true, deleted: 0, note: 'Sheet not found' }), {
      headers: { 'Content-Type': 'application/json' }
    }));
  }

  // Build deleteRange requests (bottom-up, already sorted descending above)
  const requests = toDelete.map(rowIdx => ({
    deleteDimension: {
      range: {
        sheetId,
        dimension: 'ROWS',
        startIndex: rowIdx + 1,  // +1 = skip header (0-based: row 0=header, row 1=first data)
        endIndex:   rowIdx + 2
      }
    }
  }));

  // Batch in chunks of 100 to stay under Sheets API limits
  let deleted = 0;
  for (let i = 0; i < requests.length; i += 100) {
    const chunk = requests.slice(i, i + 100);
    await fetch(`${SHEETS_URL}/${sid}:batchUpdate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ requests: chunk })
    });
    deleted += chunk.length;
  }

  return cors(new Response(JSON.stringify({ ok: true, deleted }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ═════════════════════════════════════════════════════════════════════════════
// CRON AUTO-FETCH  —  runs every 30 min via scheduled handler
// Also callable manually: GET /cron/fetch-messages (mgmt session required)
// ═════════════════════════════════════════════════════════════════════════════
async function cronFetchEbayMessages(env) {
  try {
    const ebayToken = await getEbayToken(env);
    const now   = new Date();
    const start = new Date(now.getTime() - 7 * 86400000);
    const toEbayDate = d => d.toISOString().replace(/\.\d{3}Z$/, '.000Z');
    const messages = [];

    // GetMemberMessages — listing questions
    try {
      const r1 = await fetch('https://api.ebay.com/ws/api.dll', {
        method: 'POST',
        headers: { 'X-EBAY-API-CALL-NAME':'GetMemberMessages','X-EBAY-API-SITEID':'0','X-EBAY-API-COMPATIBILITY-LEVEL':'967','X-EBAY-API-IAF-TOKEN':ebayToken,'Content-Type':'text/xml' },
        body: `<?xml version="1.0" encoding="utf-8"?>
<GetMemberMessagesRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <MailMessageType>AskSellerQuestion</MailMessageType>
  <MessageStatus>Unanswered</MessageStatus>
  <StartCreationTime>${toEbayDate(start)}</StartCreationTime>
  <EndCreationTime>${toEbayDate(now)}</EndCreationTime>
  <Pagination><EntriesPerPage>100</EntriesPerPage><PageNumber>1</PageNumber></Pagination>
</GetMemberMessagesRequest>`
      });
      const xml1 = await r1.text();
      for (const ex of (xml1.match(/<MemberMessageExchange>([\s\S]*?)<\/MemberMessageExchange>/g) || [])) {
        const m = parseMemberMessageBlock(ex);
        if (m) { m.replyType='RTQ'; m.source='listing'; messages.push(m); }
      }
    } catch(e) { console.error('[cron-msg] GetMemberMessages:', e.message); }

    // GetMyMessages — inbox/order messages (two-step)
    try {
      const rh = await fetch('https://api.ebay.com/ws/api.dll', {
        method: 'POST',
        headers: { 'X-EBAY-API-CALL-NAME':'GetMyMessages','X-EBAY-API-SITEID':'0','X-EBAY-API-COMPATIBILITY-LEVEL':'967','X-EBAY-API-IAF-TOKEN':ebayToken,'Content-Type':'text/xml' },
        body: `<?xml version="1.0" encoding="utf-8"?>
<GetMyMessagesRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <DetailLevel>ReturnHeaders</DetailLevel>
  <StartTime>${toEbayDate(start)}</StartTime>
  <EndTime>${toEbayDate(now)}</EndTime>
  <Pagination><EntriesPerPage>50</EntriesPerPage><PageNumber>1</PageNumber></Pagination>
</GetMyMessagesRequest>`
      });
      const headXml = await rh.text();
      const msgIds = (headXml.match(/<MessageID>([^<]+)<\/MessageID>/g)||[])
        .map(m=>m.replace(/<\/?MessageID>/g,'').trim()).filter(Boolean).slice(0,30);
      if (msgIds.length) {
        const rb = await fetch('https://api.ebay.com/ws/api.dll', {
          method: 'POST',
          headers: { 'X-EBAY-API-CALL-NAME':'GetMyMessages','X-EBAY-API-SITEID':'0','X-EBAY-API-COMPATIBILITY-LEVEL':'967','X-EBAY-API-IAF-TOKEN':ebayToken,'Content-Type':'text/xml' },
          body: `<?xml version="1.0" encoding="utf-8"?>
<GetMyMessagesRequest xmlns="urn:ebay:apis:eBLBaseComponents">
  <RequesterCredentials><eBayAuthToken>${ebayToken}</eBayAuthToken></RequesterCredentials>
  <DetailLevel>ReturnMessages</DetailLevel>
${msgIds.map(id=>`  <MessageIDs><MessageID>${escXml(id)}</MessageID></MessageIDs>`).join('\n')}
</GetMyMessagesRequest>`
        });
        const bodyXml = await rb.text();
        for (const blk of (bodyXml.match(/<Message>([\s\S]*?)<\/Message>/g)||[])) {
          const m = parseMyMessageBlock(blk);
          if (!m||!m.body) continue;
          const s=(m.senderId||'').toLowerCase();
          if (s==='ebay'||s.startsWith('cs-')) continue;
          if (m.read==='true') continue;
          m.replyType='AAQ'; m.source='inbox'; messages.push(m);
        }
      }
    } catch(e) { console.error('[cron-msg] GetMyMessages:', e.message); }

    // Save to eBay_Threads (deduplication built in)
    if (messages.length) {
      const toSave = messages.map(m=>({
        threadId: m.externalMsgId||m.messageId||'', messageId: m.messageId||'',
        timestamp: m.createdAt||new Date().toISOString(), itemId: m.itemId||'',
        buyerId: m.senderId||'', subject: m.subject||'', direction:'BUYER',
        body: m.body||'', replyType: m.replyType||'RTQ', sentAt:'',
      })).filter(m=>m.messageId||m.body);
      await ebayThreadsSave({ json: async ()=>({ messages: toSave }) }, env);
    }
    console.log(`[cron-msg] Fetched ${messages.length} messages`);
    return cors(new Response(JSON.stringify({ ok:true, fetched:messages.length }), { headers:{'Content-Type':'application/json'} }));
  } catch(e) {
    console.error('[cron-msg]', e.message);
    return cors(new Response(JSON.stringify({ ok:false, error:e.message }), { status:500, headers:{'Content-Type':'application/json'} }));
  }
}

// ═════════════════════════════════════════════════════════════════════════════
// ANALYTICS  —  GET /ebay-msg/analytics?days=30
// ═════════════════════════════════════════════════════════════════════════════
async function ebayMsgAnalytics(url, env) {
  await ebayThreadsEnsureSheet(env);
  const days   = Math.min(parseInt(url.searchParams.get('days')||'30'), 90);
  const cutoff = new Date(Date.now() - days*86400000).toISOString();
  const data   = await rSheetGet(env, `${THREAD_TAB}!A2:J5000`).catch(()=>({values:[]}));
  const rows   = (data.values||[]).filter(r=>r[2]&&r[2]>=cutoff);
  const buyerRows  = rows.filter(r=>r[6]==='BUYER');
  const sellerRows = rows.filter(r=>r[6]==='SELLER');

  // Messages by day (last 14)
  const byDay = {};
  buyerRows.forEach(r=>{ const d=(r[2]||'').slice(0,10); if(d) byDay[d]=(byDay[d]||0)+1; });
  const byDaySorted = Object.entries(byDay).sort((a,b)=>a[0].localeCompare(b[0])).slice(-14);

  // Unique threads
  const threads = new Set(rows.map(r=>r[0]).filter(Boolean));

  // Avg response time
  const threadMap = {};
  rows.forEach(r=>{ const tid=r[0]; if(!tid) return; if(!threadMap[tid]) threadMap[tid]={buyer:null,seller:null}; if(r[6]==='BUYER'&&!threadMap[tid].buyer) threadMap[tid].buyer=r[2]; if(r[6]==='SELLER'&&!threadMap[tid].seller) threadMap[tid].seller=r[2]; });
  const times = Object.values(threadMap).filter(t=>t.buyer&&t.seller&&t.seller>t.buyer).map(t=>(new Date(t.seller)-new Date(t.buyer))/60000);
  const avgMin = times.length ? Math.round(times.reduce((a,b)=>a+b,0)/times.length) : null;
  const unanswered = Object.values(threadMap).filter(t=>t.buyer&&!t.seller).length;

  // Busiest day
  const dow=[0,0,0,0,0,0,0];
  buyerRows.forEach(r=>{ if(r[2]) dow[new Date(r[2]).getUTCDay()]++; });
  const dowNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const busiestDay = dowNames[dow.indexOf(Math.max(...dow))];

  return cors(new Response(JSON.stringify({
    ok:true, days,
    totalMessages:buyerRows.length, totalReplies:sellerRows.length,
    totalThreads:threads.size, unanswered,
    listingQuestions:buyerRows.filter(r=>r[8]==='RTQ').length,
    orderMessages:buyerRows.filter(r=>r[8]==='AAQ').length,
    avgResponseMin:avgMin, busiestDay,
    byDay:byDaySorted,
  }), { headers:{'Content-Type':'application/json'} }));
}

// ═════════════════════════════════════════════════════════════════════════════
// CS TOOL  —  POST /cs-tool/draft
// Body: { platform, orderNumber, productTitle, sku, buyerMessage, agentNote, agentName }
// ═════════════════════════════════════════════════════════════════════════════
async function csToolDraft(request, env) {
  const body = await request.json().catch(()=>({}));
  const { platform='Unknown', orderNumber='', productTitle='', sku='', buyerMessage='', agentNote='', agentName='' } = body;
  if (!buyerMessage) return cors(new Response(JSON.stringify({ error:'buyerMessage is required' }), { status:400, headers:{'Content-Type':'application/json'} }));

  const signOff = agentName ? `Best,\n${agentName} | XFITTING Team Support` : `Best,\nXFITTING Team Support`;
  const platformNotes = {
    Amazon:  'This is an Amazon order. Do NOT mention eBay. Returns go through Amazon A-to-Z guarantee. Follow Amazon communication policy — no external links.',
    Walmart: 'This is a Walmart Marketplace order. Direct customer to Walmart returns portal. Professional and solution-focused.',
    Shopify: 'This is a direct website order. More flexible — direct email communication is fine. Offer to resolve directly.',
    Email:   'This is a direct email inquiry. Warm and professional. Handle returns and questions directly without routing through a marketplace.',
    Other:   'Handle professionally and guide customer to the correct next step.',
  };
  const platformNote = platformNotes[platform] || platformNotes['Other'];

  const prompt = `You are a customer support assistant for XFITTING, an eCommerce brand that sells PEX plumbing fittings and valves.

TONE & STYLE:
- Always start with: "Hi,"
- Always end with: "${signOff}"
- Concise, direct, helpful — no fluff. Simple language (DIY-level).
- Polite but not overly apologetic. Confident and solution-oriented.

PRODUCT KNOWLEDGE:
- XFITTING sells PEX B (crimp/barb), PEX A (expansion), Push Fit, CPVC, and brass fittings
- PEX B = crimp/barb | PEX A = expansion (NOT interchangeable with PEX B) | Push Fit = works with PEX/copper/CPVC
- Never guess compatibility — ask for pipe type/system if unclear

RETURNS & REFUNDS:
- Direct customers to open a return through the platform they purchased on
- Do NOT offer off-platform refunds or promise prepaid labels unless required
- Wrong item/defective: apologize briefly, guide to return process

PLATFORM: ${platform}
${platformNote}

ORDER DETAILS:
${orderNumber  ? 'Order: ' + orderNumber : ''}
${productTitle ? 'Product: ' + productTitle : ''}
${sku          ? 'SKU/ASIN: ' + sku : ''}

CUSTOMER MESSAGE:
"${buyerMessage.slice(0, 1000)}"
${agentNote ? '\nAGENT NOTE (factor this in): ' + agentNote.slice(0, 300) : ''}

Write the reply. Start with "Hi," end with "${signOff}".
After sign-off add ONLY on a new line: [CONFIDENCE:X.XX] (0.00-1.00)
1.00=clear | 0.70=standard | 0.50=ambiguous | 0.30=unclear/complex`;

  try {
    const aiResp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type':'application/json', 'x-api-key': env.ANTHROPIC_KEY||env.ANTHROPIC_API_KEY, 'anthropic-version':'2023-06-01' },
      body: JSON.stringify({ model:'claude-haiku-4-5-20251001', max_tokens:400, messages:[{ role:'user', content:prompt }] })
    });
    const aiData = await aiResp.json();
    if (aiData.error) return cors(new Response(JSON.stringify({ ok:false, error:aiData.error.message }), { status:400, headers:{'Content-Type':'application/json'} }));
    let draft = (aiData.content?.[0]?.text||'').trim();
    let confidence = 0.8;
    const cm = draft.match(/\[CONFIDENCE:([\d.]+)\]\s*$/);
    if (cm) { confidence = Math.min(1,Math.max(0,parseFloat(cm[1])||0.8)); draft = draft.replace(/\[CONFIDENCE:[\d.]+\]\s*$/,'').trim(); }
    return cors(new Response(JSON.stringify({ ok:true, draft, confidence }), { headers:{'Content-Type':'application/json'} }));
  } catch(e) {
    return cors(new Response(JSON.stringify({ ok:false, error:e.message }), { status:500, headers:{'Content-Type':'application/json'} }));
  }
}

// ═════════════════════════════════════════════════════════════════════════════
// CS MSG LOG  —  multi-platform message log (Amazon, Walmart, Shopify, Email)
// Sheet tab: CS_MsgLog (auto-created in SHEET_ID_REPRICER)
// Cols A–I: ID, Timestamp, Platform, OrderNumber, SKU, CustomerMessage,
//           AIDraft, AgentNote, AgentName
// Routes:
//   POST /cs-tool/log-save  — save a CS message + draft to CS_MsgLog
//   GET  /cs-tool/log       — fetch CS_MsgLog entries (last N rows)
//   POST /cs-tool/log-clean — delete rows older than 30 days
// ═════════════════════════════════════════════════════════════════════════════

const CS_LOG_TAB     = 'CS_MsgLog';
const CS_LOG_HEADERS = ['ID','Timestamp','Platform','OrderNumber','SKU','ProductTitle','CustomerMessage','AIDraft','AgentNote','AgentName'];

async function csMsgLogEnsureSheet(env) {
  try {
    const check = await rSheetGet(env, `${CS_LOG_TAB}!A1:J1`);
    const row   = (check.values || [])[0] || [];
    if (row[0] === 'ID') return;
  } catch(e) {
    const token = await getToken(env);
    const sid   = repricerSheetId(env);
    await fetch(`${SHEETS_URL}/${sid}:batchUpdate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ requests: [{ addSheet: { properties: { title: CS_LOG_TAB } } }] })
    }).catch(() => {});
  }
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  await fetch(`${SHEETS_URL}/${sid}/values/${encodeURIComponent(CS_LOG_TAB + '!A1:J1')}?valueInputOption=RAW`, {
    method: 'PUT',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values: [CS_LOG_HEADERS] })
  }).catch(() => {});
}

// POST /cs-tool/log-save
async function csMsgLogSave(request, env) {
  const body = await request.json().catch(() => ({}));
  const { platform='', orderNumber='', sku='', productTitle='', customerMessage='', aiDraft='', agentNote='', agentName='' } = body;
  if (!customerMessage) {
    return cors(new Response(JSON.stringify({ error: 'customerMessage required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  await csMsgLogEnsureSheet(env);
  const id  = 'CS-' + Date.now() + '-' + Math.random().toString(36).slice(2, 5).toUpperCase();
  const ts  = new Date().toISOString();
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  const url   = `${SHEETS_URL}/${sid}/values/${encodeURIComponent(CS_LOG_TAB + '!A:J')}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`;
  await fetch(url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ values: [[
      id, ts,
      platform.slice(0, 50),
      orderNumber.slice(0, 100),
      sku.slice(0, 100),
      productTitle.slice(0, 200),
      customerMessage.slice(0, 1000),
      aiDraft.slice(0, 1000),
      agentNote.slice(0, 300),
      agentName.slice(0, 50),
    ]] })
  });
  return cors(new Response(JSON.stringify({ ok: true, id }), { headers: { 'Content-Type': 'application/json' } }));
}

// GET /cs-tool/log?limit=N&platform=X
async function csMsgLogGet(url, env) {
  await csMsgLogEnsureSheet(env);
  const limit    = Math.min(parseInt(url.searchParams.get('limit') || '100'), 500);
  const platform = (url.searchParams.get('platform') || '').trim();
  const data = await rSheetGet(env, `${CS_LOG_TAB}!A2:J2001`).catch(() => ({ values: [] }));
  let rows = (data.values || []).map(r => ({
    id:              r[0] || '',
    timestamp:       r[1] || '',
    platform:        r[2] || '',
    orderNumber:     r[3] || '',
    sku:             r[4] || '',
    productTitle:    r[5] || '',
    customerMessage: r[6] || '',
    aiDraft:         r[7] || '',
    agentNote:       r[8] || '',
    agentName:       r[9] || '',
  })).filter(r => r.id);
  if (platform) rows = rows.filter(r => r.platform.toLowerCase() === platform.toLowerCase());
  rows = rows.reverse().slice(0, limit);
  return cors(new Response(JSON.stringify({ ok: true, log: rows, total: rows.length }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /cs-tool/log-clean — delete rows older than 30 days
async function csMsgLogClean(env) {
  await csMsgLogEnsureSheet(env);
  const cutoff = new Date(Date.now() - 30 * 86400000).toISOString();
  const data   = await rSheetGet(env, `${CS_LOG_TAB}!A2:B2001`).catch(() => ({ values: [] }));
  const rows   = data.values || [];
  const toDelete = [];
  for (let i = rows.length - 1; i >= 0; i--) {
    const ts = rows[i][1] || '';
    if (ts && ts < cutoff) toDelete.push(i + 1);
  }
  if (!toDelete.length) return cors(new Response(JSON.stringify({ ok: true, deleted: 0 }), { headers: { 'Content-Type': 'application/json' } }));
  const token = await getToken(env);
  const sid   = repricerSheetId(env);
  const metaR = await fetch(`${SHEETS_URL}/${sid}?fields=sheets.properties`, { headers: { Authorization: `Bearer ${token}` } });
  const meta  = await metaR.json();
  const sheetId = ((meta.sheets || []).find(s => s.properties?.title === CS_LOG_TAB) || {}).properties?.sheetId;
  if (sheetId === undefined) return cors(new Response(JSON.stringify({ ok: true, deleted: 0 }), { headers: { 'Content-Type': 'application/json' } }));
  const requests = toDelete.map(i => ({ deleteDimension: { range: { sheetId, dimension: 'ROWS', startIndex: i + 1, endIndex: i + 2 } } }));
  for (let i = 0; i < requests.length; i += 100) {
    await fetch(`${SHEETS_URL}/${sid}:batchUpdate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ requests: requests.slice(i, i + 100) })
    });
  }
  return cors(new Response(JSON.stringify({ ok: true, deleted: toDelete.length }), { headers: { 'Content-Type': 'application/json' } }));
}

// ═══════════════════════════════════════════════════════════════════════════════
// ── VEEQO INTEGRATION (v16) ───────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════

const VEEQO_BASE         = 'https://api.veeqo.com';
const VEEQO_LOOKBACK_DAYS = 14; // 14 days covers real issues; Status Check handles longer audit
const VEEQO_STUCK_DAYS    = 7;
const VEEQO_NOSCAND_DAYS  = 2;

// ── Veeqo API helper ──────────────────────────────────────────────────────────

async function veeqoFetch(env, path, options = {}) {
  const key = (env.VEEQO_API_KEY || '').trim();
  if (!key) throw new Error('VEEQO_API_KEY not configured');
  const res = await fetch(VEEQO_BASE + path, {
    ...options,
    headers: {
      'x-api-key': key,
      'Accept': 'application/json',
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  if (!res.ok) {
    const txt = await res.text().catch(() => '');
    throw new Error(`Veeqo ${path} → HTTP ${res.status}: ${txt.slice(0, 200)}`);
  }
  const data = await res.json().catch(() => null);
  if (!data) throw new Error(`Veeqo ${path} → invalid JSON response`);
  return data;
}

// Converts a UTC ISO timestamp (as Veeqo returns on shipped_at/created_at)
// into the warehouse's local calendar day, same convention as shipTodayKey().
// A plain `.split('T')[0]` on one of these reads the UTC calendar day
// instead — which runs 4-5 hours AHEAD of Eastern (UTC-4 in EDT, UTC-5 in
// EST), so anything that shipped in roughly the last few hours of the
// Eastern business day (after ~7-8pm ET) gets its UTC date already rolled
// over to "tomorrow" while shipTodayKey() still correctly says "today" —
// making those late-day shipments invisible to any "=== today" match until
// after Eastern midnight, at which point they'd wrongly count as the NEXT
// day's shipments instead. This is the exact same class of bug shipTodayKey()
// itself was built to fix, just re-introduced anywhere a raw Veeqo
// timestamp gets sliced directly instead of going through this helper.
function veeqoDateKey(isoTs) {
  if (!isoTs) return '';
  const d = new Date(isoTs);
  if (isNaN(d.getTime())) return '';
  return d.toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
}

// ── FBA / excluded channel detection ─────────────────────────────────────────
// Excludes Amazon FBA orders — these are fulfilled by Amazon, not us,
// and have massive order volume that would blow Cloudflare subrequest limits.
// Exclusion is by channel name match (case-insensitive) OR fulfillment_type.

// Exclude Amazon FBA orders — fulfilled by Amazon, not our warehouse.
// Uses the official 'fulfilled_by_amazon' field from Veeqo's order object,
// plus channel name fallback for any edge cases.
function veeqoIsFBA(order) {
  // Primary: official Veeqo field — most reliable
  if (order.fulfilled_by_amazon === true) return true;
  const ch = ((order.channel && order.channel.name) || '').toLowerCase();
  // Channel name contains 'fba' — catches "Amazon Channel FBA" and variants
  if (ch.includes('fba')) return true;
  return false;
}

// ── Extract tracking / carrier / channel from a Veeqo order ──────────────────

// Veeqo list response uses alloc.shipment (singular object), NOT alloc.shipments (array)
function veeqoExtractTracking(order) {
  // tracking_number is an OBJECT: { tracking_number: "9334610...", status: "created", ... }
  for (const alloc of (order.allocations || [])) {
    const s = alloc.shipment;
    if (s && s.tracking_number) {
      // It's an object with a nested tracking_number string field
      const tn = s.tracking_number;
      const raw = typeof tn === 'object' ? (tn.tracking_number || '') : String(tn);
      const t = String(raw).trim().toUpperCase();
      if (t && t.length > 5) return t;
    }
  }
  return null;
}

function veeqoExtractTrackingStatus(order) {
  // tracking_number object also contains status field: created, in_transit, delivered, etc.
  for (const alloc of (order.allocations || [])) {
    const s = alloc.shipment;
    if (s && s.tracking_number && typeof s.tracking_number === 'object') {
      return s.tracking_number.status || null;
    }
  }
  return null;
}

function veeqoExtractCarrier(order) {
  for (const alloc of (order.allocations || [])) {
    const s = alloc.shipment;
    if (s) {
      // carrier is an object: { name: "Buy Shipping", slug: "buy-shipping", ... }
      // sub_carrier_id and service_carrier_name are the actual carrier strings
      const sub = String(s.sub_carrier_id || '').toUpperCase();
      if (sub.includes('UPS'))  return 'UPS';
      if (sub.includes('USPS')) return 'USPS';
      const svc = String(s.service_carrier_name || '').toUpperCase();
      if (svc.includes('UPS'))  return 'UPS';
      if (svc.includes('USPS')) return 'USPS';
      const sn = String(s.service_name || s.short_service_name || '').toUpperCase();
      if (sn.includes('UPS'))   return 'UPS';
      if (sn.includes('USPS'))  return 'USPS';
    }
  }
  // Fallback: delivery_method name on the order
  const dm = String((order.delivery_method && order.delivery_method.name) || '').toUpperCase();
  if (dm.includes('UPS'))  return 'UPS';
  if (dm.includes('USPS') || dm.includes('FIRST CLASS') || dm.includes('PRIORITY MAIL')) return 'USPS';
  return 'Unknown';
}

function veeqoExtractChannel(order) {
  return (order.channel && order.channel.name) || 'Unknown';
}

// Pulls the tracking number string off one allocation's shipment, same
// unwrap veeqoExtractTracking uses (shipment.tracking_number is an OBJECT:
// { tracking_number: "933...", status: "created", ... }, not a plain string).
function _psAllocTrackingNumber(alloc) {
  const s = alloc && alloc.shipment;
  if (!s || !s.tracking_number) return null;
  const tn = s.tracking_number;
  const raw = typeof tn === 'object' ? (tn.tracking_number || '') : String(tn);
  const t = String(raw).trim().toUpperCase();
  return t || null;
}

// The ACTUAL package weight Veeqo recorded at the moment the label was
// purchased — as opposed to the estimate this app separately computes by
// summing each line item's catalog weight (products.weight, matched by
// bin) × quantity.
//
// CONFIRMED against this account's real data via /veeqo/weight-raw-debug
// on tracking 9334610990370309187224 (known-correct weight ~26 lb from
// the bin/qty estimate):
//   allocation.weight_unit = "oz", allocation.weight = null
//   shipment.weight = 5669.989673569375, shipment.weight_unit = null
// Two things were wrong with the old version of this function:
//   1. UNIT MIX-UP — allocation.weight_unit is paired with
//      allocation.weight (a DIFFERENT field), not with shipment.weight.
//      The old code fell back to allocation.weight_unit ("oz") whenever
//      shipment.weight_unit was blank, so it read shipment.weight as
//      ounces: 5669.99 / 16 = 354.37 lb — exactly the wrong number
//      reported in the app. Interpreting that same raw number as GRAMS
//      instead gives 5669.99 / 453.59237 ≈ 12.50 lb — and this order
//      actually had TWO allocations/shipments (a split shipment), each
//      showing this same raw weight, so ~25 lb total: a close match to
//      the ~26 lb catalog estimate. So: when shipment.weight_unit is
//      blank, assume GRAMS for shipment.weight (matches Veeqo's own
//      forum example too), never allocation.weight_unit.
//   2. WRONG SHIPMENT ON A SPLIT ORDER — this function used to just
//      return the first allocation with any weight, regardless of which
//      tracking number was actually being looked up. An order with more
//      than one shipment (like this one) could silently get one
//      package's weight applied to a DIFFERENT tracking's manifest row.
//      Now takes an optional trackingFilter and, when given, prefers the
//      allocation whose own shipment.tracking_number actually matches —
//      only falling back to "first allocation with a weight" when no
//      filter was given or none of the allocations matched it.
function veeqoExtractWeightLb(order, trackingFilter) {
  const wantTracking = trackingFilter ? String(trackingFilter).trim().toUpperCase() : null;
  const allocs = order.allocations || [];
  const ordered = wantTracking
    ? allocs.slice().sort((a, b) => {
        const aMatch = _psAllocTrackingNumber(a) === wantTracking ? 0 : 1;
        const bMatch = _psAllocTrackingNumber(b) === wantTracking ? 0 : 1;
        return aMatch - bMatch;
      })
    : allocs;
  for (const alloc of ordered) {
    const s = alloc.shipment;
    if (!s) continue;
    // shipment.weight/shipment.weight_unit are a matched pair; only fall
    // back to allocation.weight when the shipment itself has no weight at
    // all. Never borrow allocation.weight_unit for shipment.weight — see
    // comment above for why that pairing is wrong.
    const fromShipment = s.weight != null && s.weight !== '';
    const raw  = fromShipment ? s.weight : alloc.weight;
    if (raw == null || raw === '') continue;
    const num = parseFloat(raw);
    if (!isFinite(num) || num <= 0) continue;
    const declaredUnit = fromShipment ? s.weight_unit : alloc.weight_unit;
    // Default to GRAMS (not lb) when no unit is declared — that's Veeqo's
    // own documented default, and now confirmed correct for this account.
    const unit = String(declaredUnit || order.weight_unit || 'g').toLowerCase();
    let lb;
    if (unit.startsWith('kg'))      lb = num / 0.45359237; // "kg" -> lb (÷0.4536 == ×2.2046)
    else if (unit.startsWith('oz')) lb = num / 16;         // "oz" -> lb
    else if (unit.startsWith('lb')) lb = num;              // "lb"/"lbs" — already lb
    else                             lb = num / 453.59237;  // "g" or unrecognized — assume grams
    return Math.round(lb * 100) / 100;
  }
  return null;
}

// ── Customer name / address / line items ──────────────────────────────────────
// Based on Veeqo's standard order schema (deliver_to address object,
// line_items array). Verify against a real response via GET /veeqo/debug
// (now includes the raw deliver_to + line_items for exactly this purpose)
// and adjust field names below if your Veeqo account's shape differs.

// Verified against a prior working implementation — d.full_name and
// d.zip_code were incorrect guesses; Veeqo's deliver_to object uses
// first_name+last_name (no combined full_name field) and postcode as
// the zip fallback, not zip_code.
function veeqoExtractCustomerName(order) {
  const d = order.deliver_to || {};
  return [d.first_name || '', d.last_name || ''].filter(Boolean).join(' ').trim();
}

function veeqoExtractAddress(order) {
  const d = order.deliver_to || {};
  return {
    address1: (d.address1 || '').trim(),
    address2: (d.address2 || '').trim(),
    city:     (d.city || '').trim(),
    zip:      (d.zip || d.postcode || '').trim(),
  };
}

// Returns a compact array of { s, q, b, i } — SHORT keys are intentional
// and REQUIRED: packship.html's order-lookup card renderer reads exactly
// these (li.s=sku, li.q=qty, li.b=bin/location, li.i=image), stored as a
// JSON string in a single sheet cell, so longer key names silently render
// as blank even though the data technically loaded.
//   s/q (sku, qty) — from li.sellable.sku_code / li.quantity — verified
//     against a prior working implementation.
//   b (bin/location) — verified working prior implementation sourced this
//     from Veeqo's li.sellable.stock_entries[0].location, but that only
//     reflects Veeqo's OWN stock records, which may be stale/absent for
//     this warehouse's actual setup. Kept the live D1 master_list lookup
//     here instead (by SKU, highest-cases row) since that's the same
//     source of truth the rest of this app already trusts for location —
//     more likely to be accurate than trusting Veeqo's copy.
//   i (image) — sellable.image_url IS a real Veeqo field (confirmed via
//     prior working implementation) — restored, was previously dropped
//     under the mistaken assumption no source existed.
// Async because of the D1 bin lookup — every caller must await this now.
// `allocation` is optional — the SPECIFIC allocation (package/shipment)
// this call is being made for, e.g. the one whose shipment.tracking_number
// matched the tracking someone just scanned (see shipScan/shipPick, which
// already resolve this exact allocation for veeqoExtractWeightLb). When an
// order ships as more than one package, Veeqo records which line item +
// how much quantity went into EACH package on that package's own
// allocation, in allocation.line_items — a DIFFERENT array from the
// order-level order.line_items (same key name, allocation-scoped). Reading
// straight from order.line_items (the old behavior) showed all of an
// order's items on every single one of its tracking numbers instead of
// just what's physically in that box.
// When the given allocation has its own line_items, this uses ONLY those
// — falling back to the full order.line_items when it doesn't (a normal
// single-shipment order, or no allocation was passed at all), which keeps
// every existing single-tracking order working exactly as before.
//
// CONFIRMED against a real raw Veeqo order payload (order 25-15163-93289,
// a genuine 3-tracking split shipment) pasted back from this account via
// the /veeqo/line-items-debug "Show raw Veeqo data" tool: each
// allocation.line_items[] entry carries its own quantity (how many of this
// SKU are in THIS package, not the order total) plus a fully-embedded
// sellable object and a warehouse_sublocation (this package's specific
// pick location). Two earlier guesses at this field name — allocated_items,
// then allocation_items — were both wrong; Veeqo doesn't send those. A
// defensive id-based cross-reference into order.line_items is kept below
// for the unexpected case of an entry arriving without its own embedded
// sellable, but the normal path no longer needs it.
async function veeqoExtractLineItems(env, order, allocation) {
  // The per-package item breakdown for a split-shipment order lives on
  // allocation.line_items — a DIFFERENT array from order.line_items (same
  // key name, allocation-scoped instead of order-scoped). Confirmed from a
  // real raw Veeqo order dump: each allocation.line_items[] entry already
  // carries its own quantity (how many of this SKU are in THIS package —
  // not the order total) plus a fully-embedded sellable object, e.g.:
  //   { id, quantity, picked_quantity,
  //     sellable: { id, sku_code, stock_entries: [...], image_url, ... },
  //     warehouse_sublocation: { id, location } }
  // Earlier guesses at this field name (allocated_items, allocation_items)
  // were wrong — Veeqo doesn't send those. Keep a defensive id-based
  // cross-reference into order.line_items as a fallback for any entry that
  // (unexpectedly) arrives without its own embedded sellable.
  const allocatedRaw = allocation && Array.isArray(allocation.line_items) ? allocation.line_items : null;

  let items;
  if (allocatedRaw && allocatedRaw.length) {
    const byLineItemId = {};
    const bySellableId  = {};
    for (const li of (order.line_items || [])) {
      if (li.id != null) byLineItemId[li.id] = li;
      const sid = (li.sellable && li.sellable.id) || li.sellable_id;
      if (sid != null) bySellableId[sid] = li;
    }
    items = allocatedRaw.map(function(ai) {
      // Normal case: this allocation's own line item already carries its
      // own sellable object directly — no cross-referencing needed.
      // Defensive fallback: if it doesn't, look the matching order line
      // item up by id/sellable id to pull sellable details — but always
      // keep THIS allocation line item's own quantity (the whole point —
      // that's how many of this SKU are in THIS package, not the order
      // total).
      const embedded = ai.sellable || ai.product;
      const matchedLine = embedded ? null : (byLineItemId[ai.line_item_id] || bySellableId[ai.sellable_id] || null);
      const sellable = embedded || (matchedLine && (matchedLine.sellable || matchedLine.product)) || {};
      const qty = parseInt(ai.quantity) || ai.quantity_shipped || (matchedLine && (parseInt(matchedLine.quantity) || matchedLine.quantity_shipped)) || 1;
      return { sellable, quantity: qty, warehouseSublocation: ai.warehouse_sublocation };
    });
  } else {
    items = (order.line_items || []).map(function(li) {
      return { sellable: li.sellable || li.product || {}, quantity: parseInt(li.quantity) || li.quantity_shipped || 1 };
    });
  }

  const out = [];
  for (const entry of items) {
    const sellable = entry.sellable || {};
    const sku = sellable.sku_code || sellable.sku || '';
    const qty = entry.quantity;
    const img = (sellable.image_url || '').trim();
    if (!sku) continue;
    let bin = '';
    let binSrc = '';

    // Priority 1: this allocation's own warehouse_sublocation — the exact
    // sub-location this specific package's item was picked from. Only
    // present on allocation-scoped line items (split-shipment orders), so
    // it's the most specific bin source available when it exists.
    const sub = entry.warehouseSublocation;
    if (sub && sub.location) {
      bin = String(sub.location).trim();
      binSrc = 'veeqo_sublocation';
    }

    // Priority 2: Veeqo's own bin location — sellable.stock_entries[0].location.
    // This is what the proven-working reference implementation used, and
    // it's reliable here since all orders fulfill from a single Veeqo
    // location ("My Location") — no ambiguity about which stock_entries
    // index is the right one. A prior version of this function replaced
    // this with a D1 master_list lookup instead, on the theory that D1
    // would be more accurate — but that requires Veeqo's sku_code to
    // exactly match this app's part_num/base_sku convention, which isn't
    // guaranteed, and in practice returned blank far more often than
    // Veeqo's own field would have. Reverted to Veeqo-first.
    const stockEntries = sellable.stock_entries || [];
    if (!bin && stockEntries.length && stockEntries[0].location) {
      bin = String(stockEntries[0].location).trim();
      binSrc = 'veeqo';
    }

    // Priority 3 (fallback only): D1 master_list, in case a given item has
    // no stock_entries in Veeqo for some reason. Exact part_num, then
    // fuzzy base_sku.
    if (!bin && env && env.DB) {
      try {
        const row = await d1First(env,
          'SELECT location FROM master_list WHERE UPPER(part_num)=? AND cases > 0 ORDER BY cases DESC LIMIT 1',
          [sku.toUpperCase()]
        );
        if (row && row.location) { bin = row.location; binSrc = 'd1_exact_fallback'; }
        else {
          const baseSku = sku.split('=')[0].trim();
          if (baseSku) {
            const fuzzyRow = await d1First(env,
              'SELECT location FROM master_list WHERE UPPER(base_sku)=? AND cases > 0 ORDER BY cases DESC LIMIT 1',
              [baseSku.toUpperCase()]
            );
            if (fuzzyRow && fuzzyRow.location) { bin = fuzzyRow.location; binSrc = 'd1_base_sku_fallback'; }
          }
        }
      } catch(e) { console.error('[Veeqo] D1 bin fallback failed for', sku, e.message); }
    }

    out.push({ s: sku, q: qty, b: bin, i: img, _binSrc: binSrc || 'none_found' });
  }
  return out;
}


// ═══════════════════════════════════════════════════════════════════════════════
// ── TRACKING_MONITOR SHEET HELPERS ───────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
// Cols: A=Date B=Tracking C=Carrier D=OrderNum E=OrderID F=Channel
//       G=ScanDate H=DaysSince I=LastEvent J=LastEventDate K=LastLocation
//       L=AlertLevel M=Status

const VEEQO_MONITOR_TAB = 'Tracking_Monitor';
let _veeqoTabChecked = false;

async function veeqoEnsureMonitorTab(env) {
  if (_veeqoTabChecked) return;
  const token  = await getToken(env);
  const metaR  = await fetch(`${SHEETS_URL}/${env.SHIP_SHEET_ID}?fields=sheets.properties`, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const meta   = await metaR.json();
  const exists = (meta.sheets || []).some(s => s.properties?.title === VEEQO_MONITOR_TAB);
  if (!exists) {
    await fetch(`${SHEETS_URL}/${env.SHIP_SHEET_ID}:batchUpdate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ requests: [{ addSheet: { properties: { title: VEEQO_MONITOR_TAB } } }] }),
    });
    await fetch(
      `${SHEETS_URL}/${env.SHIP_SHEET_ID}/values/${encodeURIComponent(VEEQO_MONITOR_TAB + '!A1:M1')}?valueInputOption=USER_ENTERED`,
      {
        method: 'PUT',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ values: [['Date','Tracking','Carrier','OrderNum','OrderID','Channel','ScanDate','DaysSince','LastEvent','LastEventDate','LastLocation','AlertLevel','Status']] }),
      }
    );
  }
  _veeqoTabChecked = true;
}

async function veeqoMonitorWrite(env, rows) {
  const token = await getToken(env);
  await fetch(
    `${SHEETS_URL}/${env.SHIP_SHEET_ID}/values/${encodeURIComponent(VEEQO_MONITOR_TAB + '!A2:M10000')}:clear`,
    { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: '{}' }
  );
  if (!rows.length) return;
  await fetch(
    `${SHEETS_URL}/${env.SHIP_SHEET_ID}/values/${encodeURIComponent(VEEQO_MONITOR_TAB + '!A2')}?valueInputOption=USER_ENTERED`,
    {
      method: 'PUT',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ values: rows }),
    }
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
// ── VEEQO HELPER FUNCTIONS ────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════

// Look up one order by tracking number via Veeqo free-text query
async function veeqoLookupByTracking(env, tracking) {
  try {
    const qs  = `?query=${encodeURIComponent(tracking)}&status=shipped&page_size=5&page=1`;
    const res = await veeqoFetch(env, `/orders${qs}`);
    if (!Array.isArray(res) || res.length === 0) return null;
    // Prefer exact tracking match
    for (const order of res) {
      const t = veeqoExtractTracking(order);
      if (t && t === tracking.trim().toUpperCase()) return order;
    }
    return res[0];
  } catch (_) { return null; }
}

// Same reasoning as veeqoGetTrackingEventsSafe above - the original
// silently returns null on any failure, indistinguishable from a
// genuine "no matching order". For the undelivered report, that meant
// items needing this fallback could silently vanish from the report
// on an API failure with no indication anything went wrong.
async function veeqoLookupByTrackingSafe(env, tracking) {
  try {
    const qs  = `?query=${encodeURIComponent(tracking)}&status=shipped&page_size=5&page=1`;
    const res = await veeqoFetch(env, `/orders${qs}`);
    if (!Array.isArray(res) || res.length === 0) return { order: null, error: null };
    for (const order of res) {
      const t = veeqoExtractTracking(order);
      if (t && t === tracking.trim().toUpperCase()) return { order, error: null };
    }
    return { order: res[0], error: null };
  } catch (e) {
    return { order: null, error: e.message };
  }
}

// Get shipment_id from order allocation (needed for tracking events endpoint)
function veeqoExtractShipmentId(order) {
  for (const alloc of (order.allocations || [])) {
    const s = alloc.shipment;
    if (s && s.id) return s.id;
  }
  return null;
}

// Fetch real tracking events from Veeqo: GET /shipping/tracking_events/{shipment_id}
// Returns array of { timestamp, description, status, location } newest first
async function veeqoGetTrackingEvents(env, shipmentId) {
  try {
    const res = await veeqoFetch(env, `/shipping/tracking_events/${shipmentId}`);
    if (!Array.isArray(res)) return [];
    // Sort newest first
    return res.sort((a, b) => new Date(b.timestamp || 0) - new Date(a.timestamp || 0));
  } catch (_) { return []; }
}

// BUGFIX: the original veeqoGetTrackingEvents above silently swallows
// any error (rate limiting, timeout, bad shipment ID) and returns an
// empty array either way - indistinguishable from "genuinely no
// tracking events yet". For the undelivered report specifically, that
// meant an API failure looked identical to a real delivery gap, and
// with enough failures (e.g. from rate limiting on a long run) nearly
// everything got misreported as undelivered. This variant preserves
// the real error instead of discarding it. Kept separate from the
// original so veeqoTrackingSync's existing, working use is untouched.
async function veeqoGetTrackingEventsSafe(env, shipmentId) {
  try {
    const res = await veeqoFetch(env, `/shipping/tracking_events/${shipmentId}`);
    if (!Array.isArray(res)) return { events: [], error: null };
    return { events: res.sort((a, b) => new Date(b.timestamp || 0) - new Date(a.timestamp || 0)), error: null };
  } catch (e) {
    return { events: [], error: e.message };
  }
}

// Business days since a date (Mon-Fri only, skips weekends)
function veeqoBusinessDaysSince(dateStr) {
  const start = new Date(dateStr);
  const now   = new Date();
  let days = 0;
  const cur = new Date(start);
  while (cur < now) {
    cur.setDate(cur.getDate() + 1);
    const dow = cur.getUTCDay();
    if (dow !== 0 && dow !== 6) days++;
  }
  return days;
}

// For manifest sync — fetches page 1 only (today's orders are newest = first page)
async function veeqoGetOrdersSince(env, sinceDate) {
  const since = sinceDate.toISOString().split('T')[0];
  const batch = await veeqoFetch(env, `/orders?page_size=100&page=1&created_at_min=${since}&status=shipped`).catch(() => []);
  return Array.isArray(batch) ? batch : [];
}

// ═══════════════════════════════════════════════════════════════════════════════
// ── TARGETED TRACKING SYNC ────────────────────────────────────────════════════
// ═══════════════════════════════════════════════════════════════════════════════
// Reads Scan_Log for tracking numbers in two windows:
//   • 2-4 calendar days old  → 2-day no-carrier-scan check
//   • 10-20 business days old → 10-day delivery check
// For each: looks up order in Veeqo, then calls /shipping/tracking_events
// for rich event history. Stores OrderNum + OrderID in sheet.

// ═══════════════════════════════════════════════════════════════════════════════
// ── 50-DAY UNDELIVERED REPORT ─────────────────────────────════════════════════
// ═══════════════════════════════════════════════════════════════════════════════
// GET /veeqo/undelivered-report?page=1&days=50&excludeRecentDays=15
// Confirmed with the user: sources tracking numbers from D1's own
// Manifest_Log instead of a fresh, paginated Veeqo /orders API call -
// that data is already sitting in D1 (populated by the hourly manifest
// sync and by CSV uploads), so this skips an expensive external fetch
// entirely. For each tracking number, checks Scan_Log first for an
// already-cached shipment_id (populated at scan time) to skip an extra
// Veeqo lookup call - only falls back to a live lookup for orders that
// were manifested but never actually scanned.
// Window excludes the most recent N days (default 15) since those
// shipments are likely still legitimately in transit, not yet worth
// flagging - real window is [now-days, now-excludeRecentDays].
// Still paginated: even with D1 supplying the tracking-number list for
// free, checking each one's real delivery status is still one Veeqo API
// call per item, which remains the bottleneck and can't all fit in one
// 30-sec Worker invocation for a large window.
function veeqoTrackingUrl(carrier, tracking) {
  const c = (carrier || '').toUpperCase();
  if (c.includes('UPS'))  return `https://www.ups.com/track?tracknum=${encodeURIComponent(tracking)}`;
  if (c.includes('USPS')) return `https://tools.usps.com/go/TrackConfirmAction?tLabels=${encodeURIComponent(tracking)}`;
  if (c.includes('FEDEX')) return `https://www.fedex.com/fedextrack/?trknbr=${encodeURIComponent(tracking)}`;
  return null;
}

async function veeqoUndeliveredReport(url, env) {
  if (!env.VEEQO_API_KEY) return cors(new Response(JSON.stringify({ ok: false, error: 'VEEQO_API_KEY not set' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  await ensureShipD1Tables(env);

  const page   = parseInt(url.searchParams.get('page')) || 1;
  const days   = parseInt(url.searchParams.get('days')) || 50;
  const excludeRecentDays = parseInt(url.searchParams.get('excludeRecentDays')) || 15;
  const PAGE_SIZE = 100;

  const startDate = new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);
  const endDate   = new Date(Date.now() - excludeRecentDays * 86400000).toISOString().slice(0, 10);

  const manifestRes = await env.DB.prepare(
    `SELECT tracking, order_num, channel, carrier, date FROM ship_manifest_log
     WHERE date >= ? AND date <= ? ORDER BY date ASC LIMIT ? OFFSET ?`
  ).bind(startDate, endDate, PAGE_SIZE, (page - 1) * PAGE_SIZE).all();
  const manifestRows = manifestRes.results || [];

  if (manifestRows.length === 0) {
    return cors(new Response(JSON.stringify({ ok: true, page, hasMore: false, checked: 0, undelivered: [], failedLookups: [], windowStart: startDate, windowEnd: endDate }), { headers: { 'Content-Type': 'application/json' } }));
  }

  // Bulk-lookup any cached shipment_id from Scan_Log for this page's
  // tracking numbers, to skip a live Veeqo call for anything already scanned.
  // Chunked to stay under D1's bound-parameter limit per query (same fix as
  // shipAttachItemsAndWeight — PAGE_SIZE is 100 here, right at the edge of
  // where that limit has bitten us before, so this batches defensively
  // rather than waiting for a future page to trip it).
  const trackings = manifestRows.map(r => (r.tracking || '').trim().toUpperCase());
  const scanCacheResults = [];
  for (let i = 0; i < trackings.length; i += 50) {
    const chunk = trackings.slice(i, i + 50);
    const placeholders = chunk.map(() => '?').join(',');
    const res = await env.DB.prepare(`SELECT UPPER(tracking) as t, shipment_id FROM ship_scan_log WHERE UPPER(tracking) IN (${placeholders}) AND shipment_id != ''`).bind(...chunk).all();
    scanCacheResults.push(...(res.results || []));
  }
  const shipmentIdCache = new Map(scanCacheResults.map(r => [r.t, r.shipment_id]));

  // BUGFIX: previously any API failure (rate limit, timeout, bad ID) was
  // silently swallowed and treated identically to "confirmed not
  // delivered" - with enough failures on a long run, that meant the
  // report could show nearly everything as undelivered when most
  // failures were actually just failed lookups, not real gaps.
  // failedLookups is now tracked and returned separately so a spike in
  // failures (e.g. rate limiting) is visible instead of silently
  // corrupting the undelivered count.
  const undelivered = [];
  const failedLookups = [];
  for (let i = 0; i < manifestRows.length; i += 5) {
    const chunk = manifestRows.slice(i, i + 5);
    const results = await Promise.all(chunk.map(async (m) => {
      const tracking = (m.tracking || '').trim().toUpperCase();
      let shipmentId = shipmentIdCache.get(tracking);
      let channel = m.channel || '';

      if (!shipmentId) {
        const lookup = await veeqoLookupByTrackingSafe(env, tracking);
        if (lookup.error) { failedLookups.push({ tracking, stage: 'order-lookup', error: lookup.error }); return null; }
        if (!lookup.order) return null; // genuinely no matching order, not an error - skip silently
        shipmentId = veeqoExtractShipmentId(lookup.order);
        channel = channel || veeqoExtractChannel(lookup.order);
        if (!shipmentId) return null;
      }

      const { events, error } = await veeqoGetTrackingEventsSafe(env, shipmentId);
      if (error) { failedLookups.push({ tracking, stage: 'tracking-events', error }); return null; }

      // BUGFIX: confirmed against a real Veeqo response - tracking events
      // use a 'description' field ("Delivered", "Outfordelivery"), not
      // 'status'. Reading latest.status meant this was always undefined,
      // so the delivered-check compared against an empty string every
      // time regardless of what the real event said - a genuinely
      // delivered shipment with a "Delivered" event still showed up as
      // undelivered. Checking description first, falling back to status
      // defensively in case some responses do include it.
      const latest = events[0] || null;
      const status = latest ? (latest.description || latest.status || '').toLowerCase() : '';
      if (/delivered/.test(status)) return null; // confirmed delivered - exclude

      return {
        tracking, carrier: m.carrier || '', orderNum: m.order_num || '', channel,
        shippedAt: m.date || '',
        lastStatus: status || 'no tracking events yet',
        lastEventDate: latest ? (latest.timestamp || '').split('T')[0] : '',
        lastLocation: latest ? (latest.location || '') : '',
        trackingUrl: veeqoTrackingUrl(m.carrier, tracking),
      };
    }));
    for (const r of results) if (r) undelivered.push(r);
    // Small throttle between chunks - reduces the chance of hitting
    // Veeqo's own rate limits on a long, many-page run, which is the
    // most likely real cause of a spike in failedLookups.
    if (i + 5 < manifestRows.length) await new Promise(r => setTimeout(r, 150));
  }

  return cors(new Response(JSON.stringify({
    ok: true, page, hasMore: manifestRows.length === PAGE_SIZE,
    checked: manifestRows.length, undelivered,
    failedLookups: failedLookups.slice(0, 20), // sample - full count still accurate below
    failedLookupCount: failedLookups.length,
    windowStart: startDate, windowEnd: endDate,
  }), { headers: { 'Content-Type': 'application/json' } }));
}

async function veeqoTrackingSync(env) {
  if (!env.VEEQO_API_KEY) return { ok: false, error: 'VEEQO_API_KEY not set' };
  await veeqoEnsureMonitorTab(env);

  const today  = shipTodayKey();
  const now    = Date.now();
  const DAY_MS = 86400000;

  // Read Scan_Log — A=Date B=Timestamp C=Tracking D=Carrier E=Initials
  //                   F=BatchClosedAt G=Status H=ShipmentID I=OrderNum
  const scanData = await shipSheetGet(env, 'Scan_Log!A2:I50000');
  const scanRows = (scanData.values || []);

  const needNoScanCheck   = [];
  const needDeliveryCheck = [];
  const seen = new Set();

  for (const r of scanRows) {
    const dateStr   = (r[0] || '').trim();
    const tracking  = (r[2] || '').trim().toUpperCase();
    const carrier   = (r[3] || '').trim();
    const shipmentId = (r[7] || '').trim(); // col H — populated at scan time
    const orderNum   = (r[8] || '').trim(); // col I — populated at scan time
    if (!tracking || !dateStr || seen.has(tracking)) continue;
    const scanTime = new Date(dateStr).getTime();
    if (isNaN(scanTime)) continue;
    const calDays = Math.floor((now - scanTime) / DAY_MS);
    const bizDays = veeqoBusinessDaysSince(dateStr);
    if (calDays >= 2 && calDays <= 4) {
      needNoScanCheck.push({ tracking, carrier, scanDate: dateStr, calDays, shipmentId, orderNum });
      seen.add(tracking);
    } else if (bizDays >= 10 && bizDays <= 20) {
      needDeliveryCheck.push({ tracking, carrier, scanDate: dateStr, bizDays, shipmentId, orderNum });
      seen.add(tracking);
    }
  }

  const alertRows = [];

  // ── Helper: resolve shipment data for one item ────────────────────────────
  // If ShipmentID is stored in Scan_Log (col H) → use tracking events directly (1 call).
  // If not (older rows) → order lookup to get shipment ID, then tracking events (2 calls).
  // Either way: one call per item once ShipmentID is populated from scanning forward.

  async function resolveItem(item) {
    let shipmentId = item.shipmentId;
    let orderNum   = item.orderNum;
    let channel    = '';
    let events     = [];

    if (!shipmentId) {
      // Fallback: order lookup to get shipment ID
      const order = await veeqoLookupByTracking(env, item.tracking);
      if (order) {
        shipmentId = veeqoExtractShipmentId(order);
        orderNum   = orderNum || String(order.number || order.id || '');
        channel    = veeqoExtractChannel(order);
      }
    }

    if (shipmentId) {
      events = await veeqoGetTrackingEvents(env, shipmentId);
    }

    // BUGFIX: same real issue as veeqoUndeliveredReport - Veeqo's
    // tracking events use 'description' ("Delivered"), not 'status'.
    // This means the automated 2-day/10-day delivery alert system has
    // likely been treating every shipment as still "created" (never
    // scanned) rather than reading its real, current status.
    const latest       = events[0] || null;
    const latestStatus = latest ? (latest.description || latest.status || '').toLowerCase() : '';
    const tnStatus     = latestStatus || 'created';

    return { shipmentId, orderNum, channel, events, latest, tnStatus };
  }

  // Build alert row from resolved data
  // Cols: Date|Tracking|Carrier|OrderNum|OrderID|Channel|ScanDate|DaysSince|
  //       LastEvent|LastEventDate|LastLocation|AlertLevel|Status
  function makeRow(item, resolved, alertLevel, statusLabel, daysSince) {
    const latest = resolved.latest;
    return [
      today, item.tracking, item.carrier,
      resolved.orderNum || '', resolved.shipmentId || '', resolved.channel || '',
      item.scanDate, daysSince,
      latest ? (latest.description || latest.status || '') : '',
      latest ? (latest.timestamp || '').split('T')[0] : '',
      latest ? (latest.location || '') : '',
      alertLevel, statusLabel,
    ];
  }

  // ── 2-day no-scan check ───────────────────────────────────────────────────
  for (const item of needNoScanCheck) {
    const r = await resolveItem(item);
    if (/delivered|out_for_delivery|in_transit/.test(r.tnStatus)) continue;

    if (/returned_to_sender|recipient_refused/.test(r.tnStatus)) {
      alertRows.push(makeRow(item, r, 'RETURNED', 'Returned to Sender', item.calDays));
    } else if (/contact_support|exception|failed|damage/.test(r.tnStatus)) {
      alertRows.push(makeRow(item, r, 'EXCEPTION', 'Exception / Problem', item.calDays));
    } else {
      // created / awaiting_collection / no events = never scanned
      if (!r.latest) {
        const row = makeRow(item, r, 'NEVER_SCANNED_2D', 'Never Scanned by Carrier (2d+)', item.calDays);
        row[8] = 'Label created — no carrier scan after ' + item.calDays + ' days';
        alertRows.push(row);
      } else {
        alertRows.push(makeRow(item, r, 'NEVER_SCANNED_2D', 'Never Scanned by Carrier (2d+)', item.calDays));
      }
    }
  }

  // ── 10-day delivery check ─────────────────────────────────────────────────
  for (const item of needDeliveryCheck) {
    const r = await resolveItem(item);
    if (/delivered/.test(r.tnStatus)) continue;

    if (/returned_to_sender|recipient_refused/.test(r.tnStatus)) {
      alertRows.push(makeRow(item, r, 'RETURNED', 'Returned to Sender', item.bizDays));
    } else if (/contact_support|exception|failed|damage/.test(r.tnStatus)) {
      alertRows.push(makeRow(item, r, 'EXCEPTION', 'Exception / Problem', item.bizDays));
    } else {
      alertRows.push(makeRow(item, r, 'STUCK_10D', 'Not Delivered (10+ business days)', item.bizDays));
    }
  }

  // Sort: EXCEPTION → RETURNED → STUCK_10D → NEVER_SCANNED_2D
  const priority = { EXCEPTION:1, RETURNED:2, STUCK_10D:3, NEVER_SCANNED_2D:4 };
  alertRows.sort((a, b) => (priority[a[11]] || 9) - (priority[b[11]] || 9));
  await veeqoMonitorWrite(env, alertRows);

  return {
    ok:               true,
    checked_no_scan:  needNoScanCheck.length,
    checked_delivery: needDeliveryCheck.length,
    flagged:          alertRows.length,
    ts:               new Date().toISOString(),
  };
}

async function veeqoManifestSync(env) {
  if (!env.VEEQO_API_KEY) return { ok: false, error: 'VEEQO_API_KEY not set' };
  await ensureShipD1Tables(env);
  const today     = shipTodayKey();
  const sinceDate = new Date(Date.now() - 1 * 86400000);
  const allOrders = await veeqoGetOrdersSince(env, sinceDate);
  const todayOrders = allOrders.filter(o => {
    if (veeqoIsFBA(o) || !veeqoExtractTracking(o)) return false;
    return veeqoDateKey(o.shipped_at || o.created_at) === today;
  });
  if (todayOrders.length === 0) return { ok: true, added: 0, date: today };

  // Dedup on EITHER today's date OR already marked 'Scanned' (regardless
  // of date) - a scan-first upsert can create a row dated slightly
  // differently than this sync's "today" boundary right around midnight,
  // and without the Scanned check that edge case could duplicate an
  // order that a packer already scanned. Same rule as the prior Sheets
  // implementation, preserved exactly.
  const existingRows = (await env.DB.prepare(
    `SELECT tracking FROM ship_manifest_log WHERE date = ? OR reconcile_status = 'Scanned'`
  ).bind(today).all()).results;
  const existingToday = new Set(existingRows.map(r => (r.tracking || '').trim().toUpperCase()).filter(Boolean));

  const newRows = [];
  for (const o of todayOrders) {
    const tracking = veeqoExtractTracking(o);
    if (existingToday.has(tracking)) continue;
    const addr = veeqoExtractAddress(o);
    newRows.push({
      tracking, orderNum: String(o.number || o.id || ''),
      channel: veeqoExtractChannel(o), carrier: veeqoExtractCarrier(o),
      service: ((o.allocations || [])[0]?.delivery_method?.name || ''),
      shipToState: (o.deliver_to?.state || ''),
      customerName: veeqoExtractCustomerName(o), city: addr.city, zip: addr.zip,
      lineItems: JSON.stringify(await veeqoExtractLineItems(env, o)),
      address1: addr.address1, address2: addr.address2,
      weightLb: veeqoExtractWeightLb(o),
    });
  }

  if (newRows.length > 0) {
    const stmts = newRows.map(r => env.DB.prepare(
      `INSERT INTO ship_manifest_log (date, tracking, order_num, channel, carrier, service, ship_to_state, uploaded_by, reconcile_status, customer_name, city, zip, line_items, address1, address2, weight_lb)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(today, r.tracking, r.orderNum, r.channel, r.carrier, r.service, r.shipToState, 'veeqo-sync', 'Pending', r.customerName, r.city, r.zip, r.lineItems, r.address1, r.address2, r.weightLb));
    for (let i = 0; i < stmts.length; i += 100) { await env.DB.batch(stmts.slice(i, i+100)); }
  }
  return { ok: true, added: newRows.length, total: todayOrders.length, date: today };
}

// ── POST or GET /veeqo/backfill-weight ──────────────────────────────────────
// One-time catch-up: finds manifest rows for a given date that have no
// weight_lb yet, looks each one up in Veeqo directly by tracking number
// (same query shape shipScan already uses), and fills in the real weight —
// without needing a rescan/re-pick, which wouldn't reach this code anyway
// (a duplicate scan/pick returns early — see shipScan/shipPick). Capped at
// `limit` per call (default 50, max 150) to stay inside a single Worker
// invocation's subrequest/CPU budget; call again to pick up more rows if
// `remaining` in the response is still above 0.
//
// force / tracking (added after the veeqoExtractWeightLb unit-mix-up fix —
// see that function's comment): normally this only fills rows where
// weight_lb is still NULL, since a "real" weight already on file is assumed
// trustworthy. That assumption doesn't hold for rows that got a WRONG
// weight written before the fix (e.g. grams misread as ounces) — those
// already have a non-null weight_lb, so the normal pass skips them forever.
// `force: true` (or ?force=1) drops the "IS NULL" guard so every matching
// row gets recomputed and OVERWRITTEN with today's (correct) logic,
// regardless of what's already stored. `tracking` (or ?tracking=...) scopes
// either mode to one specific row, ignoring `date` — for fixing a single
// known-bad tracking on demand without touching anything else.
// Accepts GET (reading date/limit/force/tracking from the query string) as
// well as POST (JSON body) — GET makes this pasteable straight into a
// browser address bar (with ?cred_token=... for auth), no console needed.
async function veeqoBackfillWeight(request, env, url) {
  if (!env.VEEQO_API_KEY) return { ok: false, error: 'VEEQO_API_KEY not set' };
  await ensureShipD1Tables(env);
  const b    = request.method === 'POST' ? await request.json().catch(() => ({})) : {};
  const qp     = url ? url.searchParams : new URLSearchParams();
  const dateParam = b.date || qp.get('date') || shipTodayKey();
  const allDates  = String(dateParam).toLowerCase() === 'all';
  const date   = allDates ? null : dateParam;
  const limit  = Math.max(1, Math.min(parseInt(b.limit || qp.get('limit')) || 50, 150));
  const force  = b.force === true || qp.get('force') === '1' || qp.get('force') === 'true';
  const trackingOnly = String(b.tracking || qp.get('tracking') || '').trim().toUpperCase() || null;
  // Cursor for paging through a FORCE pass: force mode always overwrites
  // weight_lb (even when it's already non-null), so — unlike the normal
  // pass, which naturally shrinks its own "WHERE weight_lb IS NULL" result
  // set as it goes — nothing about the WHERE clause changes between calls.
  // Without a cursor, calling this again with the same params would just
  // reprocess the exact same first `limit` rows forever and never reach
  // the rest. afterId (id > afterId, ordered by id) is that cursor; the
  // response's nextAfterId is what to pass in as afterId on the next call.
  const afterId = Math.max(0, parseInt(b.afterId || qp.get('afterId')) || 0);

  // Reported even when checked=0, so "nothing to backfill" (everything on
  // this date already has weight) is distinguishable from "wrong date"
  // (no manifest rows for this date at all) without a separate D1 lookup.
  const totalRowsForDate = (trackingOnly || allDates) ? null : (await env.DB.prepare(
    `SELECT COUNT(*) as c FROM ship_manifest_log WHERE date = ?`
  ).bind(date).first()).c;

  const rows = trackingOnly
    ? (await env.DB.prepare(
        `SELECT id, tracking FROM ship_manifest_log WHERE UPPER(tracking) = ? ORDER BY id ASC LIMIT ?`
      ).bind(trackingOnly, limit + 1).all()).results || []
    : allDates
    ? (await env.DB.prepare(
        `SELECT id, tracking FROM ship_manifest_log WHERE tracking != '' AND id > ? ${force ? '' : 'AND weight_lb IS NULL'} ORDER BY id ASC LIMIT ?`
      ).bind(afterId, limit + 1).all()).results || []
    : (await env.DB.prepare(
        `SELECT id, tracking FROM ship_manifest_log WHERE date = ? AND tracking != '' AND id > ? ${force ? '' : 'AND weight_lb IS NULL'} ORDER BY id ASC LIMIT ?`
      ).bind(date, afterId, limit + 1).all()).results || [];
  const remaining = rows.length > limit ? 1 : 0; // just a "there's more" flag, not an exact count
  const toCheck   = rows.slice(0, limit);
  const nextAfterId = toCheck.length ? toCheck[toCheck.length - 1].id : afterId;

  let updated = 0, notFoundInVeeqo = 0, veeqoHadNoWeight = 0;
  const key = (env.VEEQO_API_KEY || '').trim();
  // First few rows get a raw-field dump attached, regardless of outcome —
  // this is the fastest way to see EXACTLY what Veeqo actually returns for
  // this account's orders (which field the weight sits in, if any, and
  // what unit) without needing curl/Postman with an auth header. Rendered
  // straight in the Veeqo Sync tab's result box.
  const debugSample = [];
  const DEBUG_SAMPLE_SIZE = 3;

  for (const row of toCheck) {
    const clean = (row.tracking || '').trim().toUpperCase();
    if (!clean) continue;
    const wantDebug = debugSample.length < DEBUG_SAMPLE_SIZE;
    try {
      const qs   = `?query=${encodeURIComponent(clean)}&status=shipped&page_size=3&page=1`;
      const vRes = await fetch('https://api.veeqo.com/orders' + qs, {
        headers: { 'x-api-key': key, 'Accept': 'application/json' }
      });
      if (!vRes.ok) {
        notFoundInVeeqo++;
        if (wantDebug) debugSample.push({ tracking: clean, httpStatus: vRes.status, note: 'Veeqo request itself failed' });
        continue;
      }
      const orders = await vRes.json().catch(() => []);
      let matchedOrder = null, matchedAlloc = null;
      if (Array.isArray(orders)) {
        for (const o of orders) {
          for (const alloc of (o.allocations || [])) {
            const s = alloc.shipment;
            const tn = s && s.tracking_number
              ? (typeof s.tracking_number === 'object' ? String(s.tracking_number.tracking_number || '') : String(s.tracking_number || ''))
              : '';
            if (tn.trim().toUpperCase() === clean) { matchedOrder = o; matchedAlloc = alloc; break; }
          }
          if (matchedOrder) break;
        }
      }
      if (!matchedOrder) {
        notFoundInVeeqo++;
        if (wantDebug) debugSample.push({ tracking: clean, note: 'No order in Veeqo matched this tracking number (query+status=shipped search)', ordersReturned: Array.isArray(orders) ? orders.length : 'not an array' });
        continue;
      }
      const weightLb = veeqoExtractWeightLb(matchedOrder, clean);
      if (wantDebug) {
        const s = matchedAlloc.shipment || {};
        debugSample.push({
          tracking: clean,
          orderFound: true,
          allocation_weight: matchedAlloc.weight != null ? matchedAlloc.weight : null,
          allocation_weight_unit: matchedAlloc.weight_unit || null,
          shipment_weight: s.weight != null ? s.weight : null,
          shipment_weight_unit: s.weight_unit || null,
          computedWeightLb: weightLb,
        });
      }
      if (weightLb == null) { veeqoHadNoWeight++; continue; }
      await env.DB.prepare(`UPDATE ship_manifest_log SET weight_lb = ? WHERE id = ?`).bind(weightLb, row.id).run();
      updated++;
    } catch (e) {
      notFoundInVeeqo++;
      if (wantDebug) debugSample.push({ tracking: clean, note: 'Threw an error: ' + e.message });
    }
  }

  return {
    ok: true, date: allDates ? 'all' : date, checked: toCheck.length, updated,
    notFoundInVeeqo, veeqoHadNoWeight, remaining, debugSample, totalRowsForDate,
    // Pass this back as ?afterId=... on the next call (along with the same
    // date/force/limit) to continue past this batch — see the afterId
    // comment above for why this is needed specifically in force mode.
    nextAfterId,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// NEW: GET /veeqo/print-status?date=YYYY-MM-DD — real live "printed today"
// and "not printed yet" counts, asked directly from Veeqo instead of read
// from our local D1 mirror tables (which lag behind: ship_manifest_log only
// gets new rows from the hourly sync job or from a scan, so anything Veeqo
// has added since the last sync tick — or hasn't been scanned — is invisible
// to /veeqo/labels-today and /ship/label-gap-report).
//
// WHY /veeqo/labels-today undercounts "printed": it only ever queries Veeqo
// with status=shipped. Per Veeqo's own docs (order_statuses) and developer
// forum, a shipping label/tracking number lands on
// order.allocations[].shipment the moment it's created — a SEPARATE event
// from the order's top-level status flipping to "shipped", which can happen
// later or not automatically at all. So "status=shipped" is checking the
// wrong flag. This route instead treats "has a real tracking number"
// (veeqoExtractTracking(order) !== null — the same helper already used
// everywhere else in this file) as the true "label printed" signal, checked
// across BOTH awaiting_fulfillment and shipped orders so a printed label
// counts even if Veeqo hasn't marked that order "shipped" yet.
//
// "Not printed yet" = orders in awaiting_fulfillment (ready to ship, stock
// available) that have NO tracking number yet at all.
//
// CAVEAT: Veeqo doesn't officially document a created_at/updated_at
// timestamp directly on the shipment object (only on the allocation). This
// uses allocations[].updated_at (falling back to created_at) as the best
// available stand-in for "when was this label made" — the same kind of
// reverse-engineering already done for veeqoExtractTracking/veeqoExtractCarrier
// below. Worth spot-checking "Printed Today" against the print-station log
// once this is live, and adjusting the timestamp field if it's off.
//
// PAGINATION: pages through the full awaiting_fulfillment + shipped lists
// (unlike labels-today, which is bounded by created_at_min so it only ever
// sees ~a day's worth) — MAX_PAGES caps that at 2,000 orders/status. Raise
// it if a single day's order volume can exceed that.
async function veeqoPrintStatus(env, date) {
  const PAGE_SIZE = 100;
  const MAX_PAGES = 20; // 2,000 orders/status ceiling — raise if needed

  async function fetchAllPages(status) {
    let page = 1, out = [];
    while (page <= MAX_PAGES) {
      const batch = await veeqoFetch(env, `/orders?page_size=${PAGE_SIZE}&page=${page}&status=${status}`).catch(() => []);
      const rows = Array.isArray(batch) ? batch : [];
      out = out.concat(rows);
      if (rows.length < PAGE_SIZE) break; // last page
      page++;
    }
    return out;
  }

  // Dedupe by order id — page-based pagination can return the same order
  // twice if the underlying list shifts between page fetches (a new order
  // coming in bumps everything down a slot), and that would otherwise
  // double-count it below.
  function dedupeById(orders) {
    const seen = new Set();
    return orders.filter(o => {
      const id = o && o.id;
      if (id == null || seen.has(id)) return false;
      seen.add(id);
      return true;
    });
  }

  const [awaitingOrdersRaw, shippedOrdersRaw] = await Promise.all([
    fetchAllPages('awaiting_fulfillment'),
    fetchAllPages('shipped'),
  ]);
  const awaitingOrders = dedupeById(awaitingOrdersRaw);
  const shippedOrders  = dedupeById(shippedOrdersRaw);

  const notFBA = o => !veeqoIsFBA(o);

  // ── "Printed Today" ──────────────────────────────────────────────────────
  // Date match mirrors the already-correct "Veeqo Sync" tab
  // (veeqoManifestSync() above): a real tracking number, and "today" read
  // off the ORDER's own shipped_at (falling back to created_at) — the
  // allocation-level timestamp the very first version of this function
  // used was the bug behind "Printed Today" showing 59 when the real count
  // was 158.
  //
  // But matching on carrier alone (via veeqoExtractCarrier(), which falls
  // back to order.delivery_method.name when the shipment's own fields
  // don't say UPS/USPS) turned out to overcount — 197 shown vs. an actual
  // 174 (150 USPS + 24 UPS) — because delivery_method reflects the
  // ORIGINALLY REQUESTED shipping method, which can say "USPS"/"UPS" even
  // for a label that was never bought through Veeqo's own Buy Shipping
  // feature (a different integration, a manually entered tracking number,
  // etc.).
  //
  // Requiring the shipment's carrier object to say "Buy Shipping" fixed
  // most of that, but the Veeqo report also has a THIRD bucket: labels
  // that just say "Buy Shipping" with no USPS/UPS qualifier at all (some
  // other carrier bought through the same feature). Those must NOT be
  // counted as either UPS or USPS. The risk was that even after confirming
  // "Buy Shipping", falling back to veeqoExtractCarrier() for the actual
  // USPS-vs-UPS call could still leak through delivery_method for exactly
  // these generic ones. So buyShippingCarrier() below does the whole
  // determination itself, using ONLY the matched shipment's own fields —
  // sub_carrier_id / service_carrier_name / service_name / the carrier
  // name/slug itself — and never order.delivery_method. If none of those
  // say UPS or USPS, it returns null and the order is excluded, exactly
  // like a plain "Buy Shipping" (no carrier) entry should be. Since a
  // "Printed Today" order always already HAS a shipment (it has tracking),
  // this doesn't run into the "no shipment yet" problem that ruled a
  // shipment-only check out for "Not Printed Yet" a few rounds back.
  // UPDATED: used to require the shipment's carrier.name/slug to literally
  // contain "Buy Shipping" before checking anything else — any allocation
  // that didn't say that got skipped outright (the `continue` below, now
  // removed). Real numbers confirmed that gate is why counts were off: UPS
  // matched Veeqo's own report exactly (every UPS label this account prints
  // apparently IS tagged "Buy Shipping"), but USPS undercounted by a double
  // digit margin (186 shown vs. 197 actual) — meaning a chunk of real USPS
  // labels are tagged some other way (a different USPS integration/import
  // path than however the UPS ones get purchased) and were being skipped
  // before their carrier fields were ever even looked at.
  //
  // Fix: check the shipment's own carrier-identifying fields directly
  // (sub_carrier_id / service_carrier_name / service_name / carrier
  // name-or-slug) regardless of whether "Buy Shipping" appears anywhere.
  // This still never falls back to order.delivery_method — that fallback
  // (via the old veeqoExtractCarrier() helper) was the actual cause of the
  // EARLIER overcounting bug (197 shown vs. an actual 174, a different
  // round than the undercount above), since delivery_method reflects the
  // originally requested method, not what the label actually shipped as.
  // Only trusting the shipment's own fields — just no longer requiring the
  // literal "Buy Shipping" substring first — should widen the match to
  // catch the missing USPS labels without reopening that older bug.
  function buyShippingCarrier(order) {
    for (const alloc of (order.allocations || [])) {
      const s = alloc.shipment;
      if (!s || !s.carrier) continue;
      const cn  = String(s.carrier.name || s.carrier.slug || '').toUpperCase();
      const sub = String(s.sub_carrier_id || '').toUpperCase();
      if (sub.includes('UPS'))  return 'UPS';
      if (sub.includes('USPS')) return 'USPS';
      const svc = String(s.service_carrier_name || '').toUpperCase();
      if (svc.includes('UPS'))  return 'UPS';
      if (svc.includes('USPS')) return 'USPS';
      const sn = String(s.service_name || s.short_service_name || '').toUpperCase();
      if (sn.includes('UPS'))   return 'UPS';
      if (sn.includes('USPS'))  return 'USPS';
      // Some accounts fold the carrier straight into the name, e.g.
      // "Buy Shipping - USPS" / "Buy Shipping - UPS" — check that too.
      if (cn.includes('USPS')) return 'USPS';
      if (cn.includes('UPS'))  return 'UPS';
      // This allocation's shipment doesn't say UPS or USPS anywhere on its
      // own fields (some other carrier, or a generic unlabeled one) — keep
      // checking any other allocations on the order before giving up.
    }
    return null;
  }
  function printedTodayFrom(orders) {
    return orders.filter(notFBA).filter(o => {
      if (!veeqoExtractTracking(o)) return false;
      const carrier = buyShippingCarrier(o);
      if (carrier !== 'UPS' && carrier !== 'USPS') return false;
      return veeqoDateKey(o.shipped_at || o.created_at) === date;
    });
  }
  // Combine, then dedupe by TRACKING NUMBER (not just order id) — since
  // awaiting_fulfillment and shipped are fetched separately, an order that
  // flips status in the moment between those two calls can land in BOTH
  // lists and would otherwise be counted twice for the same label.
  const printedTodayCombined = [
    ...printedTodayFrom(awaitingOrders),
    ...printedTodayFrom(shippedOrders),
  ];
  const printedSeenTracking = new Set();
  const printedToday = printedTodayCombined.filter(o => {
    const t = veeqoExtractTracking(o);
    if (!t || printedSeenTracking.has(t)) return false;
    printedSeenTracking.add(t);
    return true;
  });

  // ── "Not Printed Yet" ────────────────────────────────────────────────────
  // Ready to ship (awaiting_fulfillment) and no tracking number on it yet —
  // that alone is what "not printed" means, regardless of which carrier it's
  // eventually going out with.
  //
  // PREVIOUS BUG: this used to also require order.delivery_method.name to
  // literally contain the text "UPS" or "USPS" before counting an order at
  // all (buyShippingMethod() below, previously used as a filter). That was
  // meant as a stand-in carrier signal since there's no shipment/carrier
  // data yet pre-label, but it silently excluded every order whose
  // requested method is phrased some other way — "Ground Advantage",
  // "Priority Mail", "3 Day Select", a custom method name, etc. That's why
  // the tile showed 8 while the real count was 25: only the ~8 orders whose
  // delivery_method.name happened to literally say UPS/USPS were being
  // counted, and the other ~17 were invisible to this filter even though
  // they were just as unprinted. Fixed by counting every non-FBA
  // awaiting_fulfillment order with no tracking number, full stop.
  //
  // buyShippingMethod() is kept only to give the ups/usps split below a
  // best-effort guess — it will legitimately undercount that split (any
  // order phrased another way falls into neither bucket), so ups+usps can
  // be less than total. Fine since the Scan tab tile only shows the total
  // right now; revisit if the split ever needs to be exact.
  function buyShippingMethod(order) {
    const dm = String((order.delivery_method && order.delivery_method.name) || '').trim().toUpperCase();
    if (!dm) return null;
    if (dm.includes('USPS')) return 'USPS';
    if (dm.includes('UPS'))  return 'UPS';
    return null;
  }
  const notPrintedYet = awaitingOrders
    .filter(notFBA)
    .filter(o => !veeqoExtractTracking(o));

  return {
    ok: true,
    date,
    printedToday: {
      total: printedToday.length,
      ups:   printedToday.filter(o => buyShippingCarrier(o) === 'UPS').length,
      usps:  printedToday.filter(o => buyShippingCarrier(o) === 'USPS').length,
    },
    notPrintedYet: {
      total: notPrintedYet.length,
      ups:   notPrintedYet.filter(o => buyShippingMethod(o) === 'UPS').length,
      usps:  notPrintedYet.filter(o => buyShippingMethod(o) === 'USPS').length,
    },
  };
}

// ── Upsert scan into Manifest_Log ─────────────────────────────────────────────
// Called after a successful scan + Veeqo background lookup.
// If tracking already in today's manifest → mark Scanned.
// If not yet → add new row marked Scanned (packer scanned before hourly sync ran).
async function manifestUpsertScanned(env, today, tracking, orderData) {
  try {
    await ensureShipD1Tables(env);
    const existing = await env.DB.prepare(
      `SELECT * FROM ship_manifest_log WHERE date = ? AND UPPER(tracking) = ? LIMIT 1`
    ).bind(today, tracking).first();

    if (existing) {
      // Row exists — update reconcile_status to Scanned if not already, and
      // backfill customer/address/items in case the earlier sync-manifest
      // pass ran before this fix (or this is the first time we have it).
      if (existing.reconcile_status !== 'Scanned') {
        await env.DB.prepare(`UPDATE ship_manifest_log SET reconcile_status = 'Scanned' WHERE id = ?`).bind(existing.id).run();
      }
      // BUGFIX: this used to gate the WHOLE backfill (customer_name, city,
      // zip, line_items, address1/2) on "!existing.customer_name" alone. An
      // earlier Veeqo Sync pass almost always sets customer_name right away
      // (it's on the order regardless of item data), but can land with an
      // empty line_items array if the order's item data wasn't fully
      // settled on Veeqo's side yet at sync time. Once that happens, this
      // scan-time upsert — which just did its OWN fresh Veeqo lookup and
      // has real items in hand right now — saw customer_name already set
      // and silently skipped writing line_items too, permanently freezing
      // that order's manifest row at "no items". That's what was showing
      // up as missing item-count/weight badges on "Today's Scans" for
      // orders that scanned fine (the scan response itself always carried
      // the right items — see the race-condition fix in shipScan/shipPick
      // — it just never made it into the persisted manifest row that
      // shipGetScans/shipGetPicks read back from later). Fix: check
      // customer_name and line_items independently, so a real, non-empty
      // set of items always gets written even when customer_name was
      // already there from before.
      let existingItems = [];
      try { existingItems = JSON.parse(existing.line_items || '[]'); } catch (_) {}
      const newItems      = orderData.lineItems || [];
      const needsCustomer = !existing.customer_name && orderData.customerName;
      const needsItems    = existingItems.length === 0 && newItems.length > 0;
      // Same independent-backfill treatment for the real Veeqo weight
      // (weight_lb) as line_items above — a null on the existing row (never
      // captured, or captured before this column existed) gets filled in
      // the moment any scan/pick brings back a real number, regardless of
      // whether customer_name/items already backfilled.
      const needsWeight = existing.weight_lb == null && orderData.weightLb != null;
      if (needsCustomer || needsItems || needsWeight) {
        await env.DB.prepare(
          `UPDATE ship_manifest_log SET customer_name=?, city=?, zip=?, line_items=?, address1=?, address2=?, weight_lb=? WHERE id = ?`
        ).bind(
          orderData.customerName || existing.customer_name || '',
          orderData.city         || existing.city         || '',
          orderData.zip          || existing.zip          || '',
          JSON.stringify(needsItems ? newItems : existingItems),
          orderData.address1 || existing.address1 || '',
          orderData.address2 || existing.address2 || '',
          needsWeight ? orderData.weightLb : (existing.weight_lb != null ? existing.weight_lb : null),
          existing.id
        ).run();
      }
    } else {
      // Not in manifest yet — add row marked Scanned, full data
      await env.DB.prepare(
        `INSERT INTO ship_manifest_log (date, tracking, order_num, channel, carrier, service, ship_to_state, uploaded_by, reconcile_status, customer_name, city, zip, line_items, address1, address2, weight_lb)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
      ).bind(
        today, tracking,
        orderData.orderNum || '', orderData.channel || '', orderData.carrier || '',
        orderData.service || '', orderData.shipToState || '', 'scan-first', 'Scanned',
        orderData.customerName || '', orderData.city || '', orderData.zip || '',
        JSON.stringify(orderData.lineItems || []),
        orderData.address1 || '', orderData.address2 || '',
        orderData.weightLb != null ? orderData.weightLb : null
      ).run();
    }
  } catch (_) { /* non-critical */ }
}

// ── Route dispatcher ──────────────────────────────────────────────────────────
// Every path returns hardcoded CORS headers — never depends on cors() helper
// so a crash in cors() itself can never cause a no-CORS response.

function veeqoResp(body, status) {
  return new Response(JSON.stringify(body), {
    status: status || 200,
    headers: {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': _currentOrigin || '*',
      'Access-Control-Allow-Methods': 'GET,POST,PUT,OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type,X-API-Key,X-Session-Token,X-Session,X-Cred-Token',
    }
  });
}

async function handleVeeqoRoute(url, method, request, env, session) {
  const path = url.pathname;

  // Session check first — before any async work.
  // sync-manifest is opened to ANY valid session (ops/mobile included) —
  // it's called automatically by Pack & Ship's Close Batch flow, which
  // ordinary floor workers use via initials-only sign-in (a 'mobile'-level
  // session, not 'mgmt'). It's a read/pull operation (bringing today's
  // Veeqo orders into the Scan/Manifest log), not sensitive like pricing
  // or alerts, so this is safe to allow at ops level. Everything else
  // under /veeqo/* stays mgmt-only.
  if (!session) {
    return veeqoResp({ error: 'Session required' }, 401);
  }
  if (path !== '/veeqo/sync-manifest' && session.pin_level !== 'mgmt') {
    return veeqoResp({ error: 'Management session required' }, 401);
  }

  // Each route in its own try/catch — crash in one can't affect CORS headers
  if (path === '/veeqo/sync-manifest' && method === 'POST') {
    try {
      const result = await veeqoManifestSync(env);
      return veeqoResp(result);
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  if (path === '/veeqo/undelivered-report' && method === 'GET') {
    try {
      return await veeqoUndeliveredReport(url, env);
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  if (path === '/veeqo/debug-tracking' && method === 'GET') {
    try {
      return await veeqoDebugTracking(url, env);
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  // GET /veeqo/weight-raw-debug?tracking=... — TEMPORARY DEBUG ROUTE.
  // Looks up ONE order live in Veeqo by tracking (same proven
  // veeqoLookupByTrackingSafe used elsewhere for tracking-number lookups)
  // and returns the completely raw allocation/shipment weight fields
  // alongside what veeqoExtractWeightLb computes from them — built to
  // check a SPECIFIC tracking already known to be showing a wrong "real"
  // weight in the app (e.g. 9334610990370309187224 showing 354.37 lb when
  // the true weight, from products.weight x qty, is 26 lb) against this
  // account's actual field/unit values, instead of guessing at a
  // unit-conversion fix. /veeqo/print-status-debug (a random sample of 10
  // orders) already exists for the general case; this is the same idea
  // narrowed to one order on demand. Safe to delete once weight accuracy
  // is confirmed.
  if (path === '/veeqo/weight-raw-debug' && method === 'GET') {
    try {
      const tracking = (url.searchParams.get('tracking') || '').trim().toUpperCase();
      if (!tracking) return veeqoResp({ ok: false, error: 'tracking query param required, e.g. /veeqo/weight-raw-debug?tracking=9334610990370309187224' }, 400);
      const { order, error } = await veeqoLookupByTrackingSafe(env, tracking);
      if (error) return veeqoResp({ ok: false, tracking, error });
      if (!order) return veeqoResp({ ok: true, tracking, found: false, note: 'No shipped order in Veeqo matched this tracking number (same query+status=shipped search used elsewhere).' });
      return veeqoResp({
        ok: true, tracking, found: true,
        orderId: order.id,
        orderNumber: order.number,
        allocations: (order.allocations || []).map(a => ({
          weight_unit: a.weight_unit || null,
          weight:      a.weight != null ? a.weight : null,
          shipment: a.shipment ? {
            tracking_number: a.shipment.tracking_number || null,
            weight:          a.shipment.weight != null ? a.shipment.weight : null,
            weight_unit:     a.shipment.weight_unit || null,
          } : null,
        })),
        computedWeightLb: veeqoExtractWeightLb(order, tracking),
        note: 'computedWeightLb is exactly what veeqoExtractWeightLb produces (now matched to THIS tracking specifically, in case the order has more than one shipment/allocation), and (once synced) is what ends up in ship_manifest_log.weight_lb and shows in the app as weightSource "veeqo". Compare the raw weight/weight_unit values above against the known-correct weight for this order to see whether the unit is being misread.',
      });
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  // DEBUG ROUTE — read-only. Verifies the "each tracking on a split order
  // should only show ITS OWN items" fix (veeqoExtractLineItems taking the
  // matched allocation) against this account's real Veeqo data. Confirmed
  // working field: allocation.line_items (two earlier guesses,
  // allocated_items and allocation_items, were wrong). Pass ANY ONE of a
  // split order's tracking numbers and compare allocatedItemsFieldFound /
  // itemsForThisTracking against what's physically in that specific box —
  // if allocatedItemsFieldFound is false, this allocation didn't carry its
  // own line_items (e.g. a single-shipment order, or an unexpected Veeqo
  // payload shape), and itemsForThisTracking falls back to (and matches)
  // fullOrderLineItems instead. Left in place (not temporary) since it's a
  // useful ongoing self-serve check — the in-app "🔧 Check Split-Order
  // Items" tool on the Order Lookup tab calls this.
  if (path === '/veeqo/line-items-debug' && method === 'GET') {
    try {
      const tracking = (url.searchParams.get('tracking') || '').trim().toUpperCase();
      if (!tracking) return veeqoResp({ ok: false, error: 'tracking query param required, e.g. /veeqo/line-items-debug?tracking=9334610990370309573324' }, 400);
      const { order, error } = await veeqoLookupByTrackingSafe(env, tracking);
      if (error) return veeqoResp({ ok: false, tracking, error });
      if (!order) return veeqoResp({ ok: true, tracking, found: false, note: 'No shipped order in Veeqo matched this tracking number.' });

      // Same "find the allocation whose OWN shipment.tracking_number
      // matches" search shipScan/shipPick use — not just the order's first
      // allocation, in case this tracking is package 2 or 3 of a split order.
      let matchedAllocation = null;
      for (const alloc of (order.allocations || [])) {
        if (_psAllocTrackingNumber(alloc) === tracking) { matchedAllocation = alloc; break; }
      }

      const allocatedRaw = matchedAllocation && Array.isArray(matchedAllocation.line_items) ? matchedAllocation.line_items : null;

      const itemsForThisTracking = await veeqoExtractLineItems(env, order, matchedAllocation);
      const fullOrderLineItems   = await veeqoExtractLineItems(env, order, null);

      return veeqoResp({
        ok: true, tracking, found: true,
        orderId: order.id,
        orderNumber: order.number,
        totalAllocationsOnOrder: (order.allocations || []).length,
        matchedAllocationFound: !!matchedAllocation,
        allocatedItemsFieldFound: !!(allocatedRaw && allocatedRaw.length),
        allocatedItemsFieldName: (allocatedRaw && allocatedRaw.length) ? 'line_items' : null,
        rawMatchedAllocation: matchedAllocation || null,
        itemsForThisTracking,
        itemsForThisTrackingCount: itemsForThisTracking.reduce((n, it) => n + (parseInt(it.q) || 0), 0),
        fullOrderLineItems,
        fullOrderLineItemsCount: fullOrderLineItems.reduce((n, it) => n + (parseInt(it.q) || 0), 0),
        // Full, unfiltered order JSON exactly as Veeqo returned it — kept
        // available (the in-app tool's "Show raw Veeqo data" button) in
        // case a future account/order shape doesn't match what was
        // confirmed here, so it can be diagnosed the same way this one was.
        rawOrder: order,
        note: 'itemsForThisTracking is what the fix shows for THIS tracking specifically. If allocatedItemsFieldFound is true and itemsForThisTracking correctly lists only this package\'s items (fewer than fullOrderLineItems, for a split order), the fix is working. If allocatedItemsFieldFound is false, check rawOrder (the complete raw Veeqo response) for wherever this account\'s per-package item data actually lives.',
      });
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  if (path === '/veeqo/sync-tracking' && method === 'POST') {
    try {
      const result = await veeqoTrackingSync(env);
      return veeqoResp(result);
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  // POST or GET /veeqo/backfill-weight — { date?, limit?, force?, tracking? }
  // as a POST JSON body, or the same as ?date=&limit=&force=&tracking= on a
  // GET. One-time catch-up for orders that were scanned/picked/synced
  // BEFORE the real Veeqo weight (weight_lb) existed on this manifest
  // table, or where a scan/pick's own duplicate check short-circuited
  // before ever reaching the Veeqo lookup that would have captured it
  // (rescanning something already scanned today returns "duplicate"
  // immediately and never touches the manifest row — see
  // shipScan/shipPick). Looks each one up by tracking directly, independent
  // of any scan/pick event, so "already scanned today" orders can get
  // their real weight without needing a brand-new order.
  //
  // ?tracking=9334610990370309187224 fixes just that one row, regardless
  // of what weight_lb currently holds — e.g. after the veeqoExtractWeightLb
  // unit-mix-up fix, to correct a specific tracking already known to be
  // showing a wrong "real" weight (like 354.37 lb instead of 12.50 lb)
  // without waiting for/running a full-day recompute.
  // ?force=1 (with no tracking) does the same for every row on `date`,
  // even ones that already have a (possibly wrong) weight_lb — use this
  // once, after deploying the fix, to correct every already-scanned order
  // for a given day. ?date=all covers every date on file, not just one
  // day — for backfilling further back than today, since the same
  // grams-read-as-ounces bug would have affected every day before the fix
  // went live, not only today. If `remaining` comes back non-zero, call
  // again with the SAME date/force params plus ?afterId=<nextAfterId from
  // the last response> to continue where it left off (required in force
  // mode specifically — see afterId's comment in veeqoBackfillWeight for
  // why: force mode overwrites rows that already have a weight_lb, so
  // nothing about the query naturally excludes already-processed rows on
  // the next call without this cursor).
  if (path === '/veeqo/backfill-weight' && (method === 'POST' || method === 'GET')) {
    try {
      const result = await veeqoBackfillWeight(request, env, url);
      return veeqoResp(result);
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  if (path === '/veeqo/labels-today' && method === 'GET') {
    try {
      const today     = shipTodayKey();
      const sinceDate = new Date(Date.now() - 1 * 86400000);
      const orders    = await veeqoGetOrdersSince(env, sinceDate);
      const safe      = Array.isArray(orders) ? orders : [];
      const labels    = safe
        .filter(o => !veeqoIsFBA(o) && veeqoExtractTracking(o))
        .filter(o => veeqoDateKey(o.shipped_at || o.created_at) === today)
        .map(o => ({
          tracking: veeqoExtractTracking(o),
          carrier:  veeqoExtractCarrier(o),
          channel:  veeqoExtractChannel(o),
          orderNum: String(o.number || o.id || ''),
        }));
      return veeqoResp({
        date:  today,
        total: labels.length,
        ups:   labels.filter(l => l.carrier === 'UPS').length,
        usps:  labels.filter(l => l.carrier === 'USPS').length,
        labels,
      });
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  // NEW: real live Veeqo numbers for the Scan tab's "Printed Today" /
  // "Not Printed Yet" tiles — see veeqoPrintStatus() above for why this
  // exists instead of reusing /veeqo/labels-today. Same session gate as
  // every other /veeqo/* route here (mgmt-only, enforced above already).
  if (path === '/veeqo/print-status' && method === 'GET') {
    try {
      const date = url.searchParams.get('date') || shipTodayKey();
      const result = await veeqoPrintStatus(env, date);
      return veeqoResp(result);
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  // TEMPORARY DEBUG ROUTE — read-only, doesn't touch/affect the numbers
  // above at all. Returns the raw shape of a few real orders (their
  // delivery_method, shipment/tracking, and timestamp fields) so the exact
  // field values veeqoPrintStatus() should be matching against can be
  // confirmed instead of guessed. Safe to delete once print-status is
  // confirmed accurate.
  if (path === '/veeqo/print-status-debug' && method === 'GET') {
    try {
      const pick = o => ({
        id: o.id,
        number: o.number,
        status: o.status,
        delivery_method: o.delivery_method || null,
        shipped_at: o.shipped_at || null,
        created_at: o.created_at || null,
        updated_at: o.updated_at || null,
        allocations: (o.allocations || []).map(a => ({
          updated_at: a.updated_at || null,
          created_at: a.created_at || null,
          // weight_unit lives on the allocation per the Veeqo dev forum
          // (developer-forum.veeqo.com/t/retrieve-order-shipment-information/248)
          // — included here, alongside shipment.weight, specifically to
          // confirm this account's real unit (their example showed "g";
          // veeqoExtractWeightLb assumes "lb" if this comes back empty).
          weight_unit: a.weight_unit || null,
          weight:      a.weight != null ? a.weight : null,
          shipment: a.shipment ? {
            tracking_number:      a.shipment.tracking_number || null,
            carrier:              a.shipment.carrier || null,
            sub_carrier_id:       a.shipment.sub_carrier_id || null,
            service_carrier_name: a.shipment.service_carrier_name || null,
            service_name:         a.shipment.service_name || null,
            short_service_name:   a.shipment.short_service_name || null,
            created_at:           a.shipment.created_at || null,
            updated_at:           a.shipment.updated_at || null,
            weight:               a.shipment.weight != null ? a.shipment.weight : null,
            weight_unit:          a.shipment.weight_unit || null,
          } : null,
        })),
        computedWeightLb: veeqoExtractWeightLb(o),
      });
      const [awaiting, shipped] = await Promise.all([
        veeqoFetch(env, `/orders?page_size=10&page=1&status=awaiting_fulfillment`).catch(() => []),
        veeqoFetch(env, `/orders?page_size=10&page=1&status=shipped`).catch(() => []),
      ]);
      return veeqoResp({
        ok: true,
        note: 'Sample of up to 10 raw orders per status — inspect delivery_method.name and the allocations[].shipment fields to see what "Buy Shipping - USPS/UPS" actually looks like in this account, and which timestamp field really reflects when a label was printed. Also check weight/weight_unit on both the allocation and its shipment against computedWeightLb, to confirm veeqoExtractWeightLb is reading the right field/unit for this account.',
        awaitingSample: (Array.isArray(awaiting) ? awaiting : []).map(pick),
        shippedSample:  (Array.isArray(shipped)  ? shipped  : []).map(pick),
      });
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  if (path === '/veeqo/alerts' && method === 'GET') {
    try {
      await veeqoEnsureMonitorTab(env);
      const data   = await shipSheetGet(env, `${VEEQO_MONITOR_TAB}!A2:M10000`);
      const alerts = (data.values || []).map(r => ({
        date:          r[0]  || '',
        tracking:      r[1]  || '',
        carrier:       r[2]  || '',
        orderNum:      r[3]  || '',
        orderId:       r[4]  || '',
        channel:       r[5]  || '',
        scanDate:      r[6]  || '',
        daysSince:     r[7]  || '',
        lastEvent:     r[8]  || '',
        lastEventDate: r[9]  || '',
        lastLocation:  r[10] || '',
        alertLevel:    r[11] || '',
        status:        r[12] || '',
      }));
      return veeqoResp({ alerts, count: alerts.length });
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  // GET /veeqo/order-search?q=... — search by customer name, order
  // number, or tracking number (Veeqo's query= param, already confirmed
  // working elsewhere in this file for tracking-number lookups during
  // scanning — same general search, just exposed standalone here).
  // Built for the returns workflow: replaces manually searching Veeqo's
  // own UI by customer name to find which marketplace/order a return
  // belongs to. Reuses the same extraction helpers already proven
  // working (veeqoExtractCustomerName, veeqoExtractChannel, etc.)
  // rather than guessing at field names fresh.
  if (path === '/veeqo/order-search' && method === 'GET') {
    try {
      const q = url.searchParams.get('q');
      if (!q) return veeqoResp({ ok: false, error: 'q parameter required' }, 400);

      const qs = `?query=${encodeURIComponent(q)}&page_size=10&page=1`;
      const raw = await veeqoFetch(env, `/orders${qs}`);
      const orders = Array.isArray(raw) ? raw : [];

      const results = await Promise.all(orders.map(async o => ({
        orderNum: String(o.number || o.id || ''),
        orderId: o.id,
        channel: veeqoExtractChannel(o),
        // CORRECTED: confirmed with the user Veeqo genuinely doesn't
        // track returns/refunds — that "refundStatus" guess was wrong
        // and has been removed. Replaced with something real and
        // useful instead: confirmed from Veeqo's own API docs that
        // manually-created orders use a "direct" channel type_code
        // (e.g. their own "Phone" order example) — this is exactly the
        // signal for spotting a possible replacement shipment sent to
        // the same customer outside the normal marketplace order flow.
        channelTypeCode: (o.channel && o.channel.type_code) || null,
        isManuallyCreated: !!(o.channel && o.channel.type_code === 'direct'),
        customerName: veeqoExtractCustomerName(o),
        address: veeqoExtractAddress(o),
        tracking: veeqoExtractTracking(o),
        trackingStatus: veeqoExtractTrackingStatus(o),
        carrier: veeqoExtractCarrier(o),
        status: o.status || '',
        isFBA: veeqoIsFBA(o),
        lineItems: await veeqoExtractLineItems(env, o),
      })));

      return veeqoResp({ ok: true, query: q, count: results.length, results });
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  // GET /veeqo/debug — returns raw structure of first 2 shipped orders.
  // Restricted to 'admin' specifically (not just any mgmt account): this
  // is a leftover development tool for verifying field-mapping logic, and
  // it dumps raw customer PII (full names, addresses, complete order
  // objects) that no real app screen surfaces. Narrowing access rather
  // than removing it outright, since it may still be useful for a
  // developer troubleshooting a mapping issue.
  if (path === '/veeqo/debug' && method === 'GET') {
    if (!session.roles || !session.roles.includes('admin')) {
      return veeqoResp({ error: 'Admin access required' }, 403);
    }
    try {
      const qs  = `?page_size=2&page=1&status=shipped`;
      const raw = await veeqoFetch(env, `/orders${qs}`);
      const orders = Array.isArray(raw) ? raw : [];
      // BUGFIX: .map(o => ({...})) is a plain (non-async) arrow function —
      // using await directly inside it is a SyntaxError ("Unexpected reserved
      // word"), which broke the ENTIRE worker on deploy (a syntax error
      // anywhere fails the whole file's parse, not just this route). Fixed
      // by resolving the async line-items lookups with Promise.all BEFORE
      // building the sample array, so the .map() itself stays synchronous.
      const sampleOrders = orders.slice(0,2);
      const sampleLineItems = await Promise.all(sampleOrders.map(o => veeqoExtractLineItems(env, o)));
      return veeqoResp({ raw_count: orders.length, sample: sampleOrders.map((o, i) => ({
        id: o.id,
        number: o.number,
        status: o.status,
        shipped_at: o.shipped_at,
        fulfilled_by_amazon: o.fulfilled_by_amazon,
        channel_name: o.channel && o.channel.name,
        delivery_method_name: o.delivery_method && o.delivery_method.name,
        allocations_count: o.allocations ? o.allocations.length : 0,
        // Full shipment object from first allocation
        first_shipment_full: o.allocations && o.allocations[0] ? o.allocations[0].shipment : 'no allocation',
        // Raw deliver_to and line_items — use these to verify/adjust
        // veeqoExtractCustomerName / veeqoExtractAddress / veeqoExtractLineItems
        // if the field names below don't match what your Veeqo account returns.
        deliver_to_full: o.deliver_to || 'no deliver_to',
        line_items_full: o.line_items || 'no line_items',
        // What our extract functions now return
        extracted_tracking: veeqoExtractTracking(o),
        extracted_carrier: veeqoExtractCarrier(o),
        extracted_customer_name: veeqoExtractCustomerName(o),
        extracted_address: veeqoExtractAddress(o),
        extracted_line_items: sampleLineItems[i],
      })) });
    } catch(e) { return veeqoResp({ error: e.message }, 500); }
  }

  // Auto Label + channel cancellation watch (mgmt only, like the rest above)
  if (path.startsWith('/veeqo/autolabel/')) {
    try {
      return await handleAutolabelRoute(path, method, url, request, env, session);
    } catch(e) { return veeqoResp({ ok: false, error: e.message }, 500); }
  }

  return veeqoResp({ error: 'Veeqo route not found' }, 404);
}

// ── END VEEQO INTEGRATION ─────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════
// VEEQO AUTO LABEL  +  CHANNEL CANCELLATION WATCH   (/veeqo/autolabel/*)
//
// Built for: "orders come in, wait half an hour, if no second order for
// the same person shows up, buy the label; if 2-3+ orders are for the same
// name + address (any channel), merge them instead." Plus: "check each
// channel for cancellations — cancelled orders must never get printed."
//
// Everything is OFF by default and controlled from Pack & Ship's
// "🤖 Auto Label" tab (mgmt only). Two independent switches:
//   mode        'off'     — nothing runs
//               'preview' — every cron tick works out what it WOULD do
//                           (and blocks cancelled orders) but never buys
//               'auto'    — actually buys labels through Veeqo. Refuses
//                           to buy until one label has been bought
//                           successfully with the tab's "Test buy ONE
//                           label" button (autolabel_buy_verified) — the
//                           Veeqo label-buying API couldn't be checked
//                           against docs from here, so the first real
//                           purchase is done by a person, on purpose.
//   cancelWatch on/off — also puts cancelled orders that ALREADY have a
//                        label onto the existing Cancellation list
//                        (ship_order_cancel_log), so Picking/Packing get
//                        the same "Marked for Cancellation" stop as a
//                        hand-entered one.
//
// Printing: Veeqo's own DirectPrint prints a label the moment it's bought,
// so turning DirectPrint on in Veeqo is what makes "auto buy" = "auto
// print". A Cloudflare worker has no way to reach a printer itself.
//
// Merging: Veeqo has no public merge API, so a same-person group is held
// and listed ("merge in Veeqo") instead of merged automatically. Once it's
// merged in Veeqo, the merged order goes through the normal rules on the
// next run.
//
// Rules live in app_config (autolabel_config) as JSON, so new ones can be
// added without touching the old ones — see AUTOLABEL_DEFAULTS.
// ═══════════════════════════════════════════════════════════════════════

const AUTOLABEL_CONFIG_KEY   = 'autolabel_config';
const AUTOLABEL_LASTRUN_KEY  = 'autolabel_last_run';
const AUTOLABEL_VERIFIED_KEY = 'autolabel_buy_verified';

const AUTOLABEL_DEFAULTS = {
  mode: 'off',                 // 'off' | 'preview' | 'auto'
  cancelWatch: false,          // add cancelled-but-already-printed orders to the Cancellation list
  waitMinutes: 30,             // wait this long after the NEWEST order for a person before buying
  upsMinSavings: 0.80,         // switch USPS -> UPS only if UPS is at least this much cheaper ($)...
  upsMaxDays: 3,               // ...AND UPS arrives in this many days or less
  uspsOnlyChannels: ['walmart'], // channels that must always ship USPS (name contains)
  lowValueRatio: 0.9,          // hold if the label costs >= this share of the order total (0 = rule off)
  lowValueMaxOrder: 0,         // only apply the low-value rule to orders <= this $ total (0 = every order)
  skipChannels: [],            // never auto-buy for these channels (name contains)
  maxBoxLb: 20,                // hold orders whose box would weigh more than this and show how to split them (0 = rule off)
  maxLabelsPerRun: 10,         // most labels one run can buy
  maxLabelsPerDay: 150,        // most labels auto mode can buy per day
  maxQuotesPerRun: 15,         // most orders one run asks Veeqo for rates on
  cancelLookbackDays: 3,       // how far back each channel is checked for cancellations
  minRunGapMinutes: 10,        // cron won't run this more often than this
};

let _autolabelTablesReady = false;
async function autolabelEnsureTables(env) {
  if (_autolabelTablesReady) return;
  await env.DB.prepare('CREATE TABLE IF NOT EXISTS app_config (key TEXT PRIMARY KEY, value TEXT)').run().catch(()=>{});
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS autolabel_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      ts TEXT NOT NULL, date TEXT NOT NULL,
      order_id TEXT, order_number TEXT, channel TEXT, customer TEXT,
      action TEXT NOT NULL, carrier TEXT, service TEXT, price REAL, order_total REAL,
      tracking TEXT, reason TEXT, detail TEXT
    )
  `).run().catch(()=>{});
  await env.DB.prepare('ALTER TABLE autolabel_log ADD COLUMN alloc_id TEXT').run().catch(()=>{}); // one row per box on split orders
  await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_autolabel_log_order ON autolabel_log(order_id)').run().catch(()=>{});
  await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_autolabel_log_date ON autolabel_log(date, action)').run().catch(()=>{});
  // One row per cancelled order seen on a channel, so each one is only
  // looked up in Veeqo / added to the Cancellation list once.
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS channel_cancel_seen (
      channel TEXT NOT NULL, order_num TEXT NOT NULL,
      state TEXT, first_seen TEXT NOT NULL, last_seen TEXT NOT NULL,
      veeqo_order_id TEXT, tracking TEXT, handled TEXT,
      PRIMARY KEY (channel, order_num)
    )
  `).run().catch(()=>{});
  await ensureShipD1Tables(env); // ship_order_cancel_log
  _autolabelTablesReady = true;
}

async function autolabelGetKey(env, key) {
  const row = await d1First(env, 'SELECT value FROM app_config WHERE key=?', [key]);
  return row ? row.value : null;
}
async function autolabelSetKey(env, key, value) {
  await d1Run(env, 'INSERT INTO app_config (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', [key, value]);
}

async function autolabelLoadConfig(env) {
  await autolabelEnsureTables(env);
  let saved = {};
  try { saved = JSON.parse(await autolabelGetKey(env, AUTOLABEL_CONFIG_KEY) || '{}') || {}; } catch (_) { saved = {}; }
  return autolabelCleanConfig({ ...AUTOLABEL_DEFAULTS, ...saved });
}

// Coerces every field to the right type/range so a typo in the UI can't
// turn into e.g. "wait -5 minutes" or "buy 10,000 labels".
function autolabelCleanConfig(c) {
  const num = (v, d, lo, hi) => { const n = parseFloat(v); return isFinite(n) ? Math.min(hi, Math.max(lo, n)) : d; };
  const list = v => (Array.isArray(v) ? v : String(v || '').split(','))
    .map(s => String(s).trim().toLowerCase()).filter(Boolean);
  const D = AUTOLABEL_DEFAULTS;
  return {
    mode: ['off', 'preview', 'auto'].includes(c.mode) ? c.mode : 'off',
    cancelWatch: c.cancelWatch === true || c.cancelWatch === 'true',
    waitMinutes:       num(c.waitMinutes, D.waitMinutes, 0, 1440),
    upsMinSavings:     num(c.upsMinSavings, D.upsMinSavings, 0, 100),
    upsMaxDays:        num(c.upsMaxDays, D.upsMaxDays, 1, 30),
    uspsOnlyChannels:  list(c.uspsOnlyChannels),
    lowValueRatio:     num(c.lowValueRatio, D.lowValueRatio, 0, 10),
    lowValueMaxOrder:  num(c.lowValueMaxOrder, D.lowValueMaxOrder, 0, 100000),
    skipChannels:      list(c.skipChannels),
    maxBoxLb:          num(c.maxBoxLb, D.maxBoxLb, 0, 150),
    maxLabelsPerRun:   Math.round(num(c.maxLabelsPerRun, D.maxLabelsPerRun, 0, 100)),
    maxLabelsPerDay:   Math.round(num(c.maxLabelsPerDay, D.maxLabelsPerDay, 0, 2000)),
    maxQuotesPerRun:   Math.round(num(c.maxQuotesPerRun, D.maxQuotesPerRun, 0, 60)),
    cancelLookbackDays: Math.round(num(c.cancelLookbackDays, D.cancelLookbackDays, 1, 14)),
    minRunGapMinutes:  num(c.minRunGapMinutes, D.minRunGapMinutes, 1, 1440),
  };
}

async function autolabelLog(env, entry) {
  const ts = new Date().toISOString();
  await d1Run(env,
    `INSERT INTO autolabel_log (ts, date, order_id, alloc_id, order_number, channel, customer, action, carrier, service, price, order_total, tracking, reason, detail)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [ts, shipTodayKey(), String(entry.orderId || ''), String(entry.allocId || ''), entry.orderNumber || '', entry.channel || '', entry.customer || '',
     entry.action, entry.carrier || '', entry.service || '', entry.price != null ? entry.price : null,
     entry.orderTotal != null ? entry.orderTotal : null, entry.tracking || '', entry.reason || '',
     entry.detail ? String(entry.detail).slice(0, 2000) : '']);
}

// ── Small helpers ────────────────────────────────────────────────────────

function autolabelNorm(s) { return String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); }
function autolabelOrderNum(s) { return String(s || '').trim().toUpperCase().replace(/^#/, ''); }

function autolabelChannelType(order) {
  const ch = order.channel || {};
  const s = `${ch.type_code || ''} ${ch.name || ''}`.toLowerCase();
  if (s.includes('amazon'))  return 'amazon';
  if (s.includes('ebay'))    return 'ebay';
  if (s.includes('walmart')) return 'walmart';
  if (s.includes('shopify')) return 'shopify';
  return 'other';
}

function autolabelChannelMatches(order, list) {
  if (!list || !list.length) return false;
  const s = `${(order.channel && order.channel.type_code) || ''} ${veeqoExtractChannel(order)}`.toLowerCase();
  return list.some(x => x && s.includes(x));
}

// Same person = same normalized name + street + apt + 5-digit zip,
// regardless of which channel each order came from.
function autolabelPersonKey(order) {
  const a = veeqoExtractAddress(order);
  return [autolabelNorm(veeqoExtractCustomerName(order)), autolabelNorm(a.address1),
          autolabelNorm(a.address2), autolabelNorm(a.zip).slice(0, 5)].join('|');
}

function autolabelMoney(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'object') return autolabelMoney(v.amount != null ? v.amount : v.value);
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return isFinite(n) ? n : null;
}

function autolabelOrderTotal(order) {
  for (const k of ['total_price', 'total', 'subtotal_price']) {
    const n = autolabelMoney(order[k]);
    if (n != null) return n;
  }
  return null;
}

async function autolabelFetchVeeqoPages(env, qs, maxPages) {
  const out = [], seen = new Set();
  for (let page = 1; page <= maxPages; page++) {
    const batch = await veeqoFetch(env, `/orders?page_size=100&page=${page}${qs}`);
    const rows = Array.isArray(batch) ? batch : [];
    for (const o of rows) { if (o && o.id != null && !seen.has(o.id)) { seen.add(o.id); out.push(o); } }
    if (rows.length < 100) break;
  }
  return out;
}

// ── Channel cancellations ────────────────────────────────────────────────
// Each returns { ok, error, count, items: [{ num, alt[], state }] } — one
// channel failing (missing API permission, outage) never stops the others.

async function autolabelEbayCancels(env, sinceIso) {
  const token = await getEbayToken(env);
  const items = [];
  const filter = `lastmodifieddate:[${sinceIso}..]`;
  for (let page = 0, offset = 0; page < 5; page++, offset += 200) {
    const r = await fetch(`https://api.ebay.com/sell/fulfillment/v1/order?filter=${encodeURIComponent(filter)}&limit=200&offset=${offset}`,
      { headers: { Authorization: `Bearer ${token}` } });
    const data = await r.json().catch(() => ({}));
    if (!r.ok || (data.errors && data.errors.length)) throw new Error(`eBay ${r.status}: ${(data.errors && data.errors[0] && data.errors[0].message) || ''}`);
    for (const o of (data.orders || [])) {
      const cs = o.cancelStatus || {};
      const state = String(cs.cancelState || '').toUpperCase();
      const openReq = (cs.cancelRequests || []).find(q => /REQUESTED|COMPLETED/i.test(q.cancelRequestState || ''));
      const refunded = /FULLY_REFUNDED/i.test(o.orderPaymentStatus || '');
      if ((state && state !== 'NONE_REQUESTED') || openReq || refunded) {
        items.push({
          num: o.orderId, alt: [o.legacyOrderId, o.salesRecordReference].filter(Boolean),
          state: refunded ? 'FULLY_REFUNDED' : (openReq ? `CANCEL_${String(openReq.cancelRequestState).toUpperCase()}` : state),
        });
      }
    }
    if ((data.orders || []).length < 200) break;
  }
  return items;
}

async function autolabelAmazonCancels(env, sinceIso) {
  const token = await getAmazonToken(env);
  const mp = env.AMAZON_MARKETPLACE_ID || 'ATVPDKIKX0DER';
  const items = [];
  let next = null;
  for (let page = 0; page < 5; page++) {
    const qs = next
      ? `MarketplaceIds=${mp}&NextToken=${encodeURIComponent(next)}`
      : `MarketplaceIds=${mp}&LastUpdatedAfter=${encodeURIComponent(sinceIso)}&OrderStatuses=Canceled&FulfillmentChannels=MFN`;
    const data = await spApiRetry(async () => {
      const r = await fetch(`https://sellingpartnerapi-na.amazon.com/orders/v0/orders?${qs}`, { headers: { 'x-amz-access-token': token } });
      const d = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(`Amazon ${r.status}: ${JSON.stringify(d.errors || d).slice(0, 200)}`);
      return d;
    }, 2, 2000);
    const p = data.payload || {};
    for (const o of (p.Orders || [])) items.push({ num: o.AmazonOrderId, alt: [], state: 'CANCELED' });
    next = p.NextToken;
    if (!next) break;
  }
  return items;
}

// Amazon's "buyer asked to cancel" flag only lives on the order ITEMS, so
// it's checked one order at a time, right before a label would be bought.
async function autolabelAmazonBuyerCancel(env, amazonOrderId) {
  if (!/^\d{3}-\d{7}-\d{7}$/.test(amazonOrderId || '')) return { checked: false };
  try {
    const token = await getAmazonToken(env);
    const r = await fetch(`https://sellingpartnerapi-na.amazon.com/orders/v0/orders/${encodeURIComponent(amazonOrderId)}/orderItems`,
      { headers: { 'x-amz-access-token': token } });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) return { checked: false, error: `Amazon items ${r.status}` };
    const hit = ((d.payload && d.payload.OrderItems) || []).find(it =>
      String(it.BuyerRequestedCancel && it.BuyerRequestedCancel.IsBuyerRequestedCancel).toLowerCase() === 'true');
    return { checked: true, requested: !!hit, reason: hit ? (hit.BuyerRequestedCancel.BuyerCancelReason || '') : '' };
  } catch (e) { return { checked: false, error: e.message }; }
}

async function autolabelWalmartCancels(env, sinceIso) {
  const token = await getWalmartToken(env);
  const items = [];
  let qs = `?limit=200&status=Cancelled&createdStartDate=${encodeURIComponent(sinceIso.slice(0, 10))}`;
  for (let page = 0; page < 5; page++) {
    const r = await fetch(`https://marketplace.walmartapis.com/v3/orders${qs}`, {
      headers: { 'WM_SEC.ACCESS_TOKEN': token, 'WM_QOS.CORRELATION_ID': crypto.randomUUID(), 'WM_SVC.NAME': 'Walmart Marketplace', 'Accept': 'application/json' },
    });
    const data = await r.json().catch(() => ({}));
    if (r.status === 404) break; // Walmart answers "no orders found" with a 404
    if (!r.ok) throw new Error(`Walmart ${r.status}: ${JSON.stringify(data).slice(0, 200)}`);
    const raw = (data.list && data.list.elements && data.list.elements.order) || [];
    for (const o of (Array.isArray(raw) ? raw : [raw])) {
      const lines = (o.orderLines && o.orderLines.orderLine) || [];
      const lineArr = Array.isArray(lines) ? lines : [lines];
      const cancelled = lineArr.filter(l => {
        const st = (l.orderLineStatuses && l.orderLineStatuses.orderLineStatus) || [];
        return (Array.isArray(st) ? st : [st]).some(s => /cancel/i.test(s.status || ''));
      }).length;
      items.push({
        num: o.customerOrderId, alt: [o.purchaseOrderId].filter(Boolean),
        state: cancelled && cancelled < lineArr.length ? 'PARTIAL_CANCEL' : 'CANCELLED',
      });
    }
    const next = data.list && data.list.meta && data.list.meta.nextCursor;
    if (!next || !String(next).includes('hasMoreElements=true')) break;
    qs = next;
  }
  return items;
}

async function autolabelShopifyCancels(env, sinceIso) {
  const items = [];
  const query = `query($cursor: String, $q: String!) {
    orders(first: 100, after: $cursor, query: $q) {
      edges { node { name cancelledAt displayFinancialStatus } }
      pageInfo { hasNextPage endCursor }
    } }`;
  let cursor = null;
  for (let page = 0; page < 5; page++) {
    const d = await shopifyGraphQL(env, query, { cursor, q: `updated_at:>='${sinceIso}' AND (status:cancelled OR financial_status:refunded)` });
    const conn = d.orders || {};
    for (const e of (conn.edges || [])) {
      const n = e.node || {};
      items.push({ num: n.name, alt: [], state: n.cancelledAt ? 'CANCELLED' : String(n.displayFinancialStatus || 'REFUNDED') });
    }
    if (!conn.pageInfo || !conn.pageInfo.hasNextPage) break;
    cursor = conn.pageInfo.endCursor;
  }
  return items;
}

async function autolabelCollectCancels(env, cfg) {
  const sinceIso = new Date(Date.now() - cfg.cancelLookbackDays * 86400000).toISOString();
  const sources = {
    amazon:  () => autolabelAmazonCancels(env, sinceIso),
    ebay:    () => autolabelEbayCancels(env, sinceIso),
    walmart: () => autolabelWalmartCancels(env, sinceIso),
    shopify: () => autolabelShopifyCancels(env, sinceIso),
    veeqo:   async () => (await autolabelFetchVeeqoPages(env,
               `&status=cancelled&updated_at_min=${encodeURIComponent(sinceIso.slice(0, 10))}`, 3))
               .filter(o => !veeqoIsFBA(o))
               .map(o => ({ num: o.number, alt: [], state: 'CANCELLED_IN_VEEQO', order: o })),
  };
  const channels = {};
  const byNum = new Map(); // normalized order number -> { channel, state }
  const all = [];
  await Promise.all(Object.entries(sources).map(async ([ch, fn]) => {
    try {
      const items = await fn();
      channels[ch] = { ok: true, count: items.length };
      for (const it of items) {
        if (!it.num) continue;
        all.push({ channel: ch, ...it });
        for (const n of [it.num, ...(it.alt || [])]) byNum.set(autolabelOrderNum(n), { channel: ch, state: it.state });
      }
    } catch (e) {
      channels[ch] = { ok: false, error: String(e && e.message || e).slice(0, 300) };
    }
  }));
  return { channels, byNum, all };
}

// For each cancellation not seen before: find it in Veeqo. If a label was
// already bought (it has tracking) and it shipped recently, put that
// tracking on the Cancellation list so Picking/Packing stop it. Only runs
// when cancelWatch is on. Capped per run — the rest are picked up next run.
async function autolabelHandleNewCancels(env, cancels, cfg) {
  const out = { newSeen: 0, addedToCancelList: 0, notPrinted: 0, notInVeeqo: 0 };
  const now = new Date().toISOString();
  let lookups = 0;
  for (const c of cancels.all) {
    const num = autolabelOrderNum(c.num);
    const seen = await d1First(env, 'SELECT handled FROM channel_cancel_seen WHERE channel=? AND order_num=?', [c.channel, num]);
    if (seen) { await d1Run(env, 'UPDATE channel_cancel_seen SET last_seen=?, state=? WHERE channel=? AND order_num=?', [now, c.state, c.channel, num]); continue; }
    if (lookups >= 15) break;

    let order = c.order || null;
    if (!order) {
      lookups++;
      const res = await veeqoFetch(env, `/orders?query=${encodeURIComponent(c.num)}&page_size=5&page=1`).catch(() => []);
      order = (Array.isArray(res) ? res : []).find(o => autolabelOrderNum(o.number) === num) || null;
    }
    let handled, tracking = '';
    if (!order) { handled = 'not_in_veeqo'; out.notInVeeqo++; }
    else {
      tracking = veeqoExtractTracking(order) || '';
      const shippedAt = Date.parse(order.shipped_at || '') || 0;
      const recent = !shippedAt || (Date.now() - shippedAt) < 3 * 86400000;
      if (tracking && recent) {
        const clean = normalizeShipTracking(tracking);
        const open = await d1First(env, `SELECT id FROM ship_order_cancel_log WHERE UPPER(tracking)=? AND status!='done' LIMIT 1`, [clean]);
        if (!open) {
          await d1Run(env,
            `INSERT INTO ship_order_cancel_log (date, timestamp, tracking, order_num, reason, requested_by, requested_at, status)
             VALUES (?, ?, ?, ?, ?, 'AUTO', ?, 'pending')`,
            [shipTodayKey(), now, clean, order.number || c.num, `Auto: cancelled on ${c.channel} (${c.state}) after the label was bought — void the label in Veeqo`, now]);
          out.addedToCancelList++;
          await autolabelLog(env, { orderId: order.id, orderNumber: order.number, channel: veeqoExtractChannel(order),
            customer: veeqoExtractCustomerName(order), action: 'cancel_listed', tracking: clean, reason: `${c.channel}: ${c.state}` });
        }
        handled = 'added_to_cancel_list';
      } else if (tracking) { handled = 'already_shipped'; }
      else { handled = 'not_printed'; out.notPrinted++; }
    }
    await d1Run(env,
      `INSERT OR IGNORE INTO channel_cancel_seen (channel, order_num, state, first_seen, last_seen, veeqo_order_id, tracking, handled)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [c.channel, num, c.state, now, now, order ? String(order.id) : '', tracking, handled]);
    out.newSeen++;
  }
  return out;
}

// ── Veeqo rates + buying ─────────────────────────────────────────────────
// The rate endpoints below are tried in order; whichever answers with a
// list of rates first is used. /veeqo/autolabel/rates shows the raw answer
// of each, so the field names can be adjusted if this account differs.
const AUTOLABEL_QUOTE_SOURCES = [
  { name: 'amazon_shipping_v2', path: id => `/shipping/quotes/amazon_shipping_v2?allocation_id=${id}&from_allocation_package=true` },
  { name: 'rates',              path: id => `/shipping/rates/${id}` },
];

function autolabelParseQuote(q, source) {
  const txtOf = x => (x && typeof x === 'object') ? `${x.name || ''} ${x.slug || ''}` : String(x || '');
  const txt = ['sub_carrier_id', 'service_carrier', 'carrier_name', 'carrier', 'name', 'title', 'service_name', 'service_type', 'short_service_name']
    .map(k => txtOf(q[k])).join(' ').toUpperCase();
  const carrier = txt.includes('USPS') || txt.includes('POSTAL') ? 'USPS' : (/\bUPS\b|^UPS|UPS_/.test(txt) ? 'UPS' : 'OTHER');
  let price = null;
  for (const k of ['total_net_charge', 'total_charge', 'net_charge', 'total_price', 'price', 'rate', 'amount', 'cost', 'base_rate']) {
    price = autolabelMoney(q[k]); if (price != null) break;
  }
  let days = null;
  for (const k of ['transit_days', 'delivery_days', 'estimated_delivery_days', 'days', 'transit_time']) {
    const n = parseFloat(q[k]); if (isFinite(n)) { days = n; break; }
  }
  if (days == null) {
    for (const k of ['delivery_promise_date', 'estimated_delivery_date', 'delivery_date', 'latest_delivery_date', 'delivery_by', 'estimated_delivery']) {
      const v = q[k] && typeof q[k] === 'object' ? (q[k].end || q[k].latest || q[k].date) : q[k];
      const t = Date.parse(v || '');
      if (t) { days = Math.max(0, Math.ceil((t - Date.now()) / 86400000)); break; }
    }
  }
  const service = String(q.name || q.title || q.service_name || q.short_service_name || q.service_type || '').slice(0, 80);
  return { carrier, service, price, days, source, raw: q };
}

async function autolabelGetQuotes(env, allocationId) {
  const attempts = [];
  for (const src of AUTOLABEL_QUOTE_SOURCES) {
    try {
      const resp = await veeqoFetch(env, src.path(allocationId));
      const arr = Array.isArray(resp) ? resp : (resp && (resp.quotes || resp.rates || resp.data || resp.results)) || [];
      attempts.push({ source: src.name, ok: true, count: Array.isArray(arr) ? arr.length : 0, raw: resp });
      if (Array.isArray(arr) && arr.length) {
        return { quotes: arr.map(q => autolabelParseQuote(q, src.name)).filter(q => q.price != null), source: src.name, attempts };
      }
    } catch (e) {
      attempts.push({ source: src.name, ok: false, error: String(e.message || e).slice(0, 300) });
    }
  }
  return { quotes: [], source: null, attempts };
}

// The carrier rules. Returns { pick, hold, reason, usps, ups }.
function autolabelChooseRate(order, quotes, cfg) {
  const cheapest = list => list.slice().sort((a, b) => (a.price - b.price) || ((a.days ?? 99) - (b.days ?? 99)))[0] || null;
  const usps = cheapest(quotes.filter(q => q.carrier === 'USPS'));
  const ups  = cheapest(quotes.filter(q => q.carrier === 'UPS' && q.days != null && q.days <= cfg.upsMaxDays));
  const uspsOnly = autolabelChannelMatches(order, cfg.uspsOnlyChannels);
  let pick = null, reason = '';
  if (uspsOnly) {
    pick = usps; reason = 'USPS only for this channel';
  } else if (usps && ups && ups.price <= usps.price - cfg.upsMinSavings + 0.001) {
    pick = ups; reason = `UPS $${(usps.price - ups.price).toFixed(2)} cheaper than USPS, ${ups.days} day(s)`;
  } else if (usps) {
    pick = usps; reason = ups ? `USPS preferred (UPS only $${(usps.price - ups.price).toFixed(2)} cheaper)` : 'USPS preferred';
  }
  if (!pick) return { pick: null, hold: 'no_rate', reason: usps || !quotes.length ? 'No rates from Veeqo' : 'No USPS rate — pick a service by hand', usps, ups };

  const low = autolabelLowValue(order, pick.price, cfg);
  if (low) return { pick, hold: 'low_value', reason: low, usps, ups };
  return { pick, hold: null, reason, usps, ups };
}

// Low-value rule on the TOTAL label cost of an order (all boxes together).
function autolabelLowValue(order, cost, cfg) {
  const total = autolabelOrderTotal(order);
  if (cfg.lowValueRatio > 0 && total != null && total > 0 &&
      (!cfg.lowValueMaxOrder || total <= cfg.lowValueMaxOrder) && cost >= total * cfg.lowValueRatio) {
    return `Label $${cost.toFixed(2)} vs order $${total.toFixed(2)} — check before shipping`;
  }
  return null;
}

// ── Box weight + split plan ──────────────────────────────────────────────
// Weight comes from the same place Pack & Ship's weight estimate does: each
// line's bin -> products.weight (one piece) x the SKU's "N=" multiplier x
// qty (_psFetchWeightByKey / _psComputeOrderWeight). If any line has no
// catalog weight, falls back to Veeqo's own product weights (weight_grams),
// then to the allocation's weight; null when nothing is known.
async function autolabelWeighAllocation(env, order, alloc) {
  const items = await veeqoExtractLineItems(env, order, alloc);
  const bins = Array.from(new Set(items.map(li => String(li.b || '').trim().toUpperCase()).filter(Boolean)));
  const weightByKey = await _psFetchWeightByKey(env, bins).catch(() => ({}));
  const w = _psComputeOrderWeight(items, weightByKey, null);
  const units = w.debugLines.map(l => ({
    sku: l.sku, qty: l.qty,
    unitLb: l.perPieceWeightLb != null ? Math.round(l.perPieceWeightLb * l.multiplier * 1000) / 1000 : null,
  }));
  if (w.weightLb != null) return { lb: w.weightLb, source: 'catalog', units };

  // Veeqo's own product weights (grams per sellable).
  const lines = (alloc && Array.isArray(alloc.line_items) && alloc.line_items.length) ? alloc.line_items : (order.line_items || []);
  let grams = 0, ok = lines.length > 0;
  const vUnits = [];
  for (const li of lines) {
    const sell = li.sellable || li.product || {};
    const g = parseFloat(sell.weight_grams != null ? sell.weight_grams : sell.weight);
    const q = parseInt(li.quantity) || 1;
    if (!isFinite(g) || g <= 0) { ok = false; break; }
    grams += g * q;
    vUnits.push({ sku: sell.sku_code || sell.sku || '', qty: q, unitLb: Math.round(g / 453.59237 * 1000) / 1000 });
  }
  if (ok) return { lb: Math.round(grams / 453.59237 * 100) / 100, source: 'veeqo_products', units: vUnits };

  const aw = parseFloat(alloc && alloc.weight);
  if (isFinite(aw) && aw > 0) {
    const u = String((alloc && alloc.weight_unit) || 'g').toLowerCase();
    const lb = u.startsWith('oz') ? aw / 16 : u.startsWith('lb') ? aw : u.startsWith('kg') ? aw / 0.45359237 : aw / 453.59237;
    return { lb: Math.round(lb * 100) / 100, source: 'veeqo_allocation', units };
  }
  return { lb: null, source: null, units };
}

// Packs whole units (one Veeqo qty of a SKU — a "10=" pack stays one unit)
// into as few boxes as possible, each <= maxLb, heaviest units first.
function autolabelSplitPlan(units, maxLb) {
  const pieces = [];
  for (const u of units) {
    if (u.unitLb == null) return { ok: false, reason: `no weight for ${u.sku}` };
    if (u.unitLb > maxLb) return { ok: false, reason: `one ${u.sku} alone weighs ${u.unitLb} lb` };
    for (let i = 0; i < u.qty; i++) pieces.push(u);
  }
  if (pieces.length > 2000) return { ok: false, reason: 'too many pieces to plan' };
  pieces.sort((a, b) => b.unitLb - a.unitLb);
  const boxes = [];
  for (const pc of pieces) {
    let box = boxes.find(b => b.lb + pc.unitLb <= maxLb + 1e-9);
    if (!box) { box = { lb: 0, items: {} }; boxes.push(box); }
    box.lb += pc.unitLb;
    box.items[pc.sku] = (box.items[pc.sku] || 0) + 1;
  }
  return { ok: true, boxes: boxes.map(b => ({ lb: Math.round(b.lb * 100) / 100, items: b.items })) };
}

function autolabelSplitText(weight, maxLb) {
  const plan = autolabelSplitPlan(weight.units, maxLb);
  if (!plan.ok) return `${weight.lb} lb — over ${maxLb} lb, split by hand (${plan.reason})`;
  return `${weight.lb} lb — split in Veeqo into ${plan.boxes.length} boxes: ` + plan.boxes.map((b, i) =>
    `Box ${i + 1} (${b.lb} lb): ` + Object.entries(b.items).map(([sku, q]) => `${q}× ${sku}`).join(', ')).join(' | ');
}

async function autolabelBuy(env, order, allocationId, quote) {
  const q = quote.raw || {};
  const shipment = { allocation_id: allocationId, notify_customer: false };
  for (const k of ['carrier_id', 'remote_shipment_id', 'service_type', 'sub_carrier_id', 'service_carrier',
                   'total_net_charge', 'base_rate', 'service_id', 'rate_id', 'quote_id', 'value_added_services']) {
    if (q[k] != null) shipment[k] = q[k];
  }
  const carrierSlug = typeof q.carrier === 'string' ? q.carrier : ((q.carrier && q.carrier.slug) || q.carrier_slug || quote.source);
  const body = { carrier: carrierSlug, shipment };
  const resp = await veeqoFetch(env, '/shipping/shipments', { method: 'POST', body: JSON.stringify(body) });
  const tnObj = resp && (resp.tracking_number || (resp.shipment && resp.shipment.tracking_number));
  const tracking = tnObj && typeof tnObj === 'object' ? (tnObj.tracking_number || '') : (tnObj || '');
  return { tracking: String(tracking || '').toUpperCase(), response: resp, requestBody: body };
}

// ── The run ──────────────────────────────────────────────────────────────
// opts.buy: actually buy (cron in 'auto' mode only).
// opts.trigger: 'cron' | 'manual' (just for the saved summary).
async function autolabelRun(env, opts = {}) {
  const cfg = await autolabelLoadConfig(env);
  const startedAt = new Date().toISOString();
  const buyVerified = (await autolabelGetKey(env, AUTOLABEL_VERIFIED_KEY)) === 'yes';
  const buy = !!opts.buy && cfg.mode === 'auto' && buyVerified;
  const result = { ok: true, trigger: opts.trigger || 'manual', startedAt, mode: cfg.mode, buying: buy, buyVerified,
                   counts: {}, orders: [], channels: {}, cancelWatch: null, quoteSource: null, notes: [] };
  if (opts.buy && cfg.mode === 'auto' && !buyVerified) result.notes.push('Auto mode is on but no label has been test-bought yet — nothing was bought. Use "Test buy ONE label" first.');

  // 1) Cancellations from every channel (and Veeqo itself).
  const cancels = await autolabelCollectCancels(env, cfg);
  result.channels = cancels.channels;
  if (cfg.cancelWatch) {
    try { result.cancelWatch = await autolabelHandleNewCancels(env, cancels, cfg); }
    catch (e) { result.cancelWatch = { error: e.message }; }
  }
  if (cfg.mode === 'off' && !opts.force) { result.finishedAt = new Date().toISOString(); return result; }

  // Orders already on the (hand-entered or auto) Cancellation list, by order number.
  const listed = new Set((await d1All(env, `SELECT order_num FROM ship_order_cancel_log WHERE status!='done' AND order_num!=''`))
    .map(r => autolabelOrderNum(r.order_num)));

  // 2) Every order still waiting for a label.
  const awaiting = (await autolabelFetchVeeqoPages(env, '&status=awaiting_fulfillment', 10)).filter(o => !veeqoIsFBA(o));

  // 3) Group by person across channels.
  const groups = new Map();
  for (const o of awaiting) {
    const k = autolabelPersonKey(o);
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(o);
  }

  const boughtToday = (await d1First(env, `SELECT COUNT(*) AS n FROM autolabel_log WHERE date=? AND action='bought'`, [shipTodayKey()]) || {}).n || 0;
  let quotesLeft = cfg.maxQuotesPerRun;
  let buysLeft = Math.min(cfg.maxLabelsPerRun, Math.max(0, cfg.maxLabelsPerDay - boughtToday));
  const now = Date.now();

  for (const o of awaiting) {
    const num = autolabelOrderNum(o.number);
    const group = groups.get(autolabelPersonKey(o)) || [o];
    const newest = Math.max(...group.map(g => Date.parse(g.created_at || '') || 0));
    const ageMin = newest ? Math.floor((now - newest) / 60000) : null;
    const row = {
      id: o.id, number: o.number, channel: veeqoExtractChannel(o), customer: veeqoExtractCustomerName(o),
      total: autolabelOrderTotal(o), createdAt: o.created_at, decision: '', reason: '',
      carrier: '', service: '', price: null, days: null, mergeWith: [],
    };
    const cancel = cancels.byNum.get(num);
    const allocs = o.allocations || [];

    if (cancel) { row.decision = 'cancelled'; row.reason = `Cancelled on ${cancel.channel} (${cancel.state}) — do not print`; }
    else if (listed.has(num)) { row.decision = 'cancelled'; row.reason = 'On the Cancellation list — do not print'; }
    else if (autolabelChannelMatches(o, cfg.skipChannels)) { row.decision = 'skipped'; row.reason = 'Channel is on the skip list'; }
    else if (allocs.length && allocs.every(a => _psAllocTrackingNumber(a))) { row.decision = 'has_label'; row.reason = 'Already has a label'; }
    else if (!allocs.length && veeqoExtractTracking(o)) { row.decision = 'has_label'; row.reason = 'Already has a label'; }
    else if (group.length > 1) {
      row.decision = 'merge';
      row.mergeWith = group.filter(g => g.id !== o.id).map(g => `${g.number} (${veeqoExtractChannel(g)})`);
      row.reason = `Same name + address as ${row.mergeWith.join(', ')} — merge in Veeqo`;
    }
    else if (ageMin != null && ageMin < cfg.waitMinutes) { row.decision = 'waiting'; row.reason = `Waiting — ${cfg.waitMinutes - ageMin} min left`; }
    else if (!allocs.length) { row.decision = 'hold'; row.reason = 'Not allocated in Veeqo (stock?)'; }
    else {
      // Every package (allocation) on the order that doesn't have a label
      // yet. A normal order is 1; an order already split in Veeqo has one
      // per box, and each box gets its own label.
      const open = allocs.filter(a => !_psAllocTrackingNumber(a));
      const weights = [];
      for (const a of open) weights.push(await autolabelWeighAllocation(env, o, a));
      row.weightLb = weights.reduce((n, w) => (n == null || w.lb == null) ? null : n + w.lb, 0);
      if (row.weightLb != null) row.weightLb = Math.round(row.weightLb * 100) / 100;
      const heavyIdx = cfg.maxBoxLb > 0 ? weights.findIndex(w => w.lb != null && w.lb > cfg.maxBoxLb) : -1;
      const boxes = open.length > 1 ? `${open.length} boxes: ` : '';

      if (heavyIdx >= 0) {
        row.decision = 'too_heavy';
        row.reason = (open.length > 1 ? `Box ${heavyIdx + 1}: ` : '') + autolabelSplitText(weights[heavyIdx], cfg.maxBoxLb);
      }
      else if (quotesLeft <= 0) { row.decision = 'ready'; row.reason = 'Ready — rates checked on a later run'; }
      else {
        quotesLeft--;
        const prior = await d1First(env,
          `SELECT SUM(action='buy_failed') AS failed FROM autolabel_log WHERE order_id=?`, [String(o.id)]) || {};
        const boughtAllocs = new Set((await d1All(env,
          `SELECT alloc_id FROM autolabel_log WHERE order_id=? AND action='bought'`, [String(o.id)])).map(r => String(r.alloc_id)));
        const todo = open.filter(a => !boughtAllocs.has(String(a.id)));
        if (!todo.length) { row.decision = 'has_label'; row.reason = 'Already bought by Auto Label'; }
        else if ((prior.failed || 0) >= 2) { row.decision = 'hold'; row.reason = 'Buying failed twice — do by hand'; }
        else {
          // Last-second cancellation check for Amazon (buyer asked to cancel).
          const amz = autolabelChannelType(o) === 'amazon' ? await autolabelAmazonBuyerCancel(env, o.number) : { checked: false };
          if (amz.requested) { row.decision = 'cancelled'; row.reason = `Amazon buyer asked to cancel${amz.reason ? ` (${amz.reason})` : ''} — do not print`; }
          else {
            // Rate every box; the carrier rules pick per box, the low-value
            // rule looks at all boxes together.
            const picks = [];
            let hold = null;
            for (const a of todo) {
              const { quotes, source } = await autolabelGetQuotes(env, a.id);
              if (source) result.quoteSource = source;
              const choice = autolabelChooseRate(o, quotes, { ...cfg, lowValueRatio: 0 });
              if (!choice.pick) { hold = choice; break; }
              picks.push({ alloc: a, choice });
            }
            const cost = picks.reduce((n, p) => n + p.choice.pick.price, 0);
            if (picks.length) {
              const first = picks[0].choice.pick;
              row.carrier = Array.from(new Set(picks.map(p => p.choice.pick.carrier))).join('+');
              row.service = picks.length > 1 ? `${picks.length} labels` : first.service;
              row.price = Math.round(cost * 100) / 100;
              row.days = Math.max(...picks.map(p => p.choice.pick.days ?? 0));
            }
            const why = boxes + (picks.length ? picks[0].choice.reason : '');
            const low = !hold ? autolabelLowValue(o, cost, cfg) : null;
            if (hold) { row.decision = hold.hold; row.reason = boxes + hold.reason; }
            else if (low) { row.decision = 'low_value'; row.reason = boxes + low; }
            else if (!buy) { row.decision = 'would_buy'; row.reason = why; }
            else if (buysLeft < picks.length) { row.decision = 'ready'; row.reason = `${why} — label limit reached for this run/day`; }
            else {
              const tracks = [];
              row.decision = 'bought'; row.reason = why;
              for (const p of picks) {
                const pk = p.choice.pick;
                const logBase = { orderId: o.id, allocId: p.alloc.id, orderNumber: o.number, channel: row.channel, customer: row.customer,
                  carrier: pk.carrier, service: pk.service, price: pk.price, orderTotal: row.total, reason: p.choice.reason };
                try {
                  const b = await autolabelBuy(env, o, p.alloc.id, pk);
                  buysLeft--;
                  tracks.push(b.tracking);
                  await autolabelLog(env, { ...logBase, action: 'bought', tracking: b.tracking });
                } catch (e) {
                  row.decision = 'buy_failed';
                  row.reason = (tracks.length ? `${tracks.length} of ${picks.length} boxes bought, then: ` : '') + String(e.message || e).slice(0, 200);
                  await autolabelLog(env, { ...logBase, action: 'buy_failed', detail: e.message });
                  break;
                }
              }
              row.tracking = tracks.filter(Boolean).join(', ');
            }
          }
        }
      }
    }
    result.counts[row.decision] = (result.counts[row.decision] || 0) + 1;
    result.orders.push(row);
  }

  const order = ['bought', 'buy_failed', 'would_buy', 'cancelled', 'merge', 'too_heavy', 'low_value', 'no_rate', 'hold', 'ready', 'waiting', 'skipped', 'has_label'];
  result.orders.sort((a, b) => order.indexOf(a.decision) - order.indexOf(b.decision));
  result.finishedAt = new Date().toISOString();
  return result;
}

async function autolabelSaveLastRun(env, result) {
  const slim = { ...result, orders: result.orders.slice(0, 300) };
  await autolabelSetKey(env, AUTOLABEL_LASTRUN_KEY, JSON.stringify(slim));
}

// Called from scheduled() on every cron tick; returns quickly when off.
async function autolabelCron(env) {
  const cfg = await autolabelLoadConfig(env);
  if (cfg.mode === 'off' && !cfg.cancelWatch) return { skipped: 'off' };
  let last = null;
  try { last = JSON.parse(await autolabelGetKey(env, AUTOLABEL_LASTRUN_KEY) || 'null'); } catch (_) {}
  if (last && last.trigger === 'cron' && last.startedAt &&
      Date.now() - Date.parse(last.startedAt) < cfg.minRunGapMinutes * 60000) return { skipped: 'too_soon' };
  const result = await autolabelRun(env, { trigger: 'cron', buy: cfg.mode === 'auto' });
  await autolabelSaveLastRun(env, result);
  return { counts: result.counts, buying: result.buying };
}

// Finds one order still awaiting a label by its order number.
async function autolabelFindAwaiting(env, number) {
  const want = autolabelOrderNum(number);
  const res = await veeqoFetch(env, `/orders?query=${encodeURIComponent(number)}&status=awaiting_fulfillment&page_size=10&page=1`).catch(() => []);
  return (Array.isArray(res) ? res : []).find(o => autolabelOrderNum(o.number) === want) || null;
}

async function handleAutolabelRoute(path, method, url, request, env, session) {
  await autolabelEnsureTables(env);

  if (path === '/veeqo/autolabel/config' && method === 'GET') {
    let lastRun = null;
    try { lastRun = JSON.parse(await autolabelGetKey(env, AUTOLABEL_LASTRUN_KEY) || 'null'); } catch (_) {}
    return veeqoResp({ ok: true, config: await autolabelLoadConfig(env), defaults: AUTOLABEL_DEFAULTS,
      buyVerified: (await autolabelGetKey(env, AUTOLABEL_VERIFIED_KEY)) === 'yes', lastRun });
  }

  if (path === '/veeqo/autolabel/config' && method === 'POST') {
    const b = await request.json().catch(() => ({}));
    const cfg = autolabelCleanConfig({ ...(await autolabelLoadConfig(env)), ...(b.config || {}) });
    await autolabelSetKey(env, AUTOLABEL_CONFIG_KEY, JSON.stringify(cfg));
    await autolabelLog(env, { action: 'config', reason: `mode=${cfg.mode} cancelWatch=${cfg.cancelWatch}`,
      customer: (session && (session.displayName || session.username)) || '', detail: JSON.stringify(cfg) });
    return veeqoResp({ ok: true, config: cfg });
  }

  // Preview run on demand — never buys, even in auto mode.
  if (path === '/veeqo/autolabel/run' && method === 'POST') {
    const result = await autolabelRun(env, { trigger: 'manual', buy: false, force: true });
    await autolabelSaveLastRun(env, result);
    return veeqoResp(result);
  }

  // GET /veeqo/autolabel/rates?order=NUMBER — read-only: shows every rate
  // Veeqo offers for one waiting order, what the rules would pick, and the
  // raw answers (to adjust field names if this account's differ).
  if (path === '/veeqo/autolabel/rates' && method === 'GET') {
    const number = (url.searchParams.get('order') || '').trim();
    if (!number) return veeqoResp({ ok: false, error: 'order is required' }, 400);
    const o = await autolabelFindAwaiting(env, number);
    if (!o) return veeqoResp({ ok: false, error: `No order ${number} waiting for a label in Veeqo` });
    const alloc = (o.allocations || [])[0];
    if (!alloc) return veeqoResp({ ok: false, error: 'This order is not allocated in Veeqo yet' });
    const cfg = await autolabelLoadConfig(env);
    const q = await autolabelGetQuotes(env, alloc.id);
    const choice = autolabelChooseRate(o, q.quotes, cfg);
    const wt = await autolabelWeighAllocation(env, o, alloc);
    return veeqoResp({ ok: true, order: o.number, channel: veeqoExtractChannel(o), total: autolabelOrderTotal(o),
      allocationId: alloc.id, source: q.source, packages: (o.allocations || []).length,
      weightLb: wt.lb, weightSource: wt.source,
      split: cfg.maxBoxLb > 0 && wt.lb != null && wt.lb > cfg.maxBoxLb ? autolabelSplitText(wt, cfg.maxBoxLb) : null,
      rates: q.quotes.map(x => ({ carrier: x.carrier, service: x.service, price: x.price, days: x.days })),
      pick: choice.pick ? { carrier: choice.pick.carrier, service: choice.pick.service, price: choice.pick.price, days: choice.pick.days } : null,
      hold: choice.hold, reason: choice.reason, attempts: q.attempts });
  }

  // POST /veeqo/autolabel/test-buy { order } — buys ONE real label by hand,
  // using the same rules. The first success unlocks auto mode.
  if (path === '/veeqo/autolabel/test-buy' && method === 'POST') {
    const b = await request.json().catch(() => ({}));
    const number = String(b.order || '').trim();
    if (!number) return veeqoResp({ ok: false, error: 'order is required' }, 400);
    const o = await autolabelFindAwaiting(env, number);
    if (!o) return veeqoResp({ ok: false, error: `No order ${number} waiting for a label in Veeqo` });
    if (veeqoExtractTracking(o)) return veeqoResp({ ok: false, error: 'This order already has a label' });
    const allocs = o.allocations || [];
    if (allocs.length !== 1) return veeqoResp({ ok: false, error: `Order has ${allocs.length} allocations — test with a normal single-package order` });
    const cfg = await autolabelLoadConfig(env);
    if (cfg.maxBoxLb > 0 && !b.ignoreHold) {
      const wt = await autolabelWeighAllocation(env, o, allocs[0]);
      if (wt.lb != null && wt.lb > cfg.maxBoxLb) return veeqoResp({ ok: false, error: `Too heavy: ${autolabelSplitText(wt, cfg.maxBoxLb)}` });
    }
    const cancels = await autolabelCollectCancels(env, cfg);
    const c = cancels.byNum.get(autolabelOrderNum(o.number));
    if (c) return veeqoResp({ ok: false, error: `Order is cancelled on ${c.channel} (${c.state}) — not buying` });
    if (autolabelChannelType(o) === 'amazon') {
      const amz = await autolabelAmazonBuyerCancel(env, o.number);
      if (amz.requested) return veeqoResp({ ok: false, error: 'Amazon buyer asked to cancel — not buying' });
    }
    const q = await autolabelGetQuotes(env, allocs[0].id);
    const choice = autolabelChooseRate(o, q.quotes, cfg);
    if (!choice.pick) return veeqoResp({ ok: false, error: choice.reason, attempts: q.attempts });
    if (choice.hold && !b.ignoreHold) return veeqoResp({ ok: false, error: `Rules say hold: ${choice.reason}` });
    const logBase = { orderId: o.id, allocId: allocs[0].id, orderNumber: o.number, channel: veeqoExtractChannel(o), customer: veeqoExtractCustomerName(o),
      carrier: choice.pick.carrier, service: choice.pick.service, price: choice.pick.price, orderTotal: autolabelOrderTotal(o), reason: 'Test buy: ' + choice.reason };
    try {
      const r = await autolabelBuy(env, o, allocs[0].id, choice.pick);
      await autolabelLog(env, { ...logBase, action: 'bought', tracking: r.tracking });
      await autolabelSetKey(env, AUTOLABEL_VERIFIED_KEY, 'yes');
      return veeqoResp({ ok: true, order: o.number, carrier: choice.pick.carrier, service: choice.pick.service,
        price: choice.pick.price, tracking: r.tracking, veeqoResponse: r.response });
    } catch (e) {
      await autolabelLog(env, { ...logBase, action: 'buy_failed', detail: e.message });
      return veeqoResp({ ok: false, error: e.message, sentToVeeqo: { chosenRate: choice.pick.raw } });
    }
  }

  if (path === '/veeqo/autolabel/log' && method === 'GET') {
    const [log, cancels] = await Promise.all([
      d1All(env, 'SELECT * FROM autolabel_log ORDER BY id DESC LIMIT 100'),
      d1All(env, 'SELECT * FROM channel_cancel_seen ORDER BY first_seen DESC LIMIT 100'),
    ]);
    return veeqoResp({ ok: true, log, cancels });
  }

  return veeqoResp({ error: 'Auto label route not found' }, 404);
}
